    fn test_comparison_ne() {
        query!(br#"{"a": 1, "b": 2}"#, ".a != .b",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn test_comparison_lt() {
        query!(br#"{"a": 1, "b": 2}"#, ".a < .b",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        query!(br#"{"a": 2, "b": 1}"#, ".a < .b",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[test]
    fn test_comparison_le() {
        query!(br#"{"a": 1, "b": 1}"#, ".a <= .b",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn test_comparison_gt() {
        query!(br#"{"a": 2, "b": 1}"#, ".a > .b",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn test_comparison_ge() {
        query!(br#"{"a": 2, "b": 2}"#, ".a >= .b",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn test_comparison_objects() {
        // jq compares objects by [sorted keys] first, then values in
        // sorted-key order. All expected values verified against real jq.
        query!(b"null", r#"{"a":1} < {"a":2}"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(b"null", r#"{"a":1} < {"b":1}"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        // Key arrays decide before any values: ["a","b"] < ["a","c"] even
        // though the value at the shared key "a" compares Greater.
        query!(b"null", r#"{"a":2,"b":1} < {"a":1,"c":9}"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        // Equal key sets fall through to values in sorted-key order.
        query!(b"null", r#"{"a":1,"b":2} < {"a":1,"b":3}"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        // A key array that is a strict prefix compares Less.
        query!(b"null", r#"{"a":1} < {"a":1,"b":2}"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        // Insertion order is irrelevant; these objects are equal.
        query!(b"null", r#"{"b":1,"a":2} <= {"a":2,"b":1}"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(b"null", r#"{"a":1,"b":2} < {"a":1}"#,
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[test]
    fn test_boolean_and() {
        query!(br#"{"a": true, "b": true}"#, ".a and .b",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        query!(br#"{"a": true, "b": false}"#, ".a and .b",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // Short-circuit: if first is falsy, second is not evaluated
        query!(br#"{"a": false}"#, ".a and .nonexistent",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[test]
    fn test_boolean_or() {
        query!(br#"{"a": false, "b": true}"#, ".a or .b",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        query!(br#"{"a": false, "b": false}"#, ".a or .b",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // Short-circuit: if first is truthy, second is not evaluated
        query!(br#"{"a": true}"#, ".a or .nonexistent",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn test_boolean_not() {
        query!(br"true", ". | not",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        query!(br"false", ". | not",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        query!(br"null", ". | not",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        // Numbers are truthy
        query!(br"0", ". | not",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[test]
    fn test_alternative() {
        // Truthy value is returned
        query!(br#"{"a": 1}"#, ".a // 0",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 1);
            }
        );

        // Falsy value (null) uses alternative
        query!(br#"{"a": null}"#, ".a // 0",
            QueryResult::Owned(
                OwnedValue::Int(0) | OwnedValue::NumberLiteral(NumberRepr::Int(0), _)
            ) => {}
        );

        // Missing value uses alternative
        query!(br"{}", ".missing? // \"default\"",
            QueryResult::Owned(OwnedValue::String(s)) if s == "default" => {}
        );

        // Chain alternatives
        query!(br#"{"a": null, "b": null}"#, ".a // .b // 42",
            QueryResult::Owned(
                OwnedValue::Int(42) | OwnedValue::NumberLiteral(NumberRepr::Int(42), _)
            ) => {}
        );
    }

    #[test]
    fn regression_issue_377_alternative_propagates_left_hand_errors() {
        // jq 1.7.1 raises a left-hand error rather than treating it as falsy;
        // `//` only substitutes for false/null/absent output.
        query!(br"null", r#"error("x") // 3"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "x");
            }
        );
        query!(br"1", ".a // 3",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with string \"a\"");
            }
        );

        // A `?` on the erroring operand still suppresses the error and falls
        // through to the right side, since `.a?` never produces `Error` in
        // the first place.
        query!(br"1", ".a? // 3",
            QueryResult::Owned(
                OwnedValue::Int(3) | OwnedValue::NumberLiteral(NumberRepr::Int(3), _)
            ) => {}
        );
    }

    #[test]
    fn regression_issue_160_alternative_emits_every_truthy_output() {
        // `//` is a filter over the whole left stream, not a test of its first
        // output. Before #160 the truthiness check read `vs.first()` and then
        // returned the left stream *unfiltered*, so these gave "backup", 3 and
        // `1 false 2` respectively.
        assert_eq!(
            outputs(b"null", r#"(false,1,null,2) // "backup""#),
            ["1", "2"]
        );
        assert_eq!(outputs(b"null", "(null,1) // 3"), ["1"]);
        assert_eq!(outputs(b"null", "(1,false,2) // 3"), ["1", "2"]);
    }

    #[test]
    fn regression_issue_160_alternative_does_not_filter_its_right_side() {
        // Only the left operand is filtered.
        assert_eq!(outputs(b"null", "false // (null,7)"), ["null", "7"]);

        // Which is exactly what makes the left-associative chain filter the
        // middle operand: `((null,false) // (null,5)) // 6` emits `null, 5`
        // from the inner `//`, and the outer one keeps only the 5.
        assert_eq!(outputs(b"null", "(null,false) // (null,5) // 6"), ["5"]);
    }

    #[test]
    fn regression_issue_160_alternative_keeps_a_borrowed_stream_borrowed() {
        // Document-derived values must survive the filter without being
        // promoted to owned, so `//` keeps the zero-copy path.
        query!(br#"{"a": [1, false, 2]}"#, ".a[] // 9",
            QueryResult::Many(vs) => {
                assert_eq!(vs.len(), 2, "expected both truthy elements to survive");
            }
        );

        // A single survivor normalizes back to `One`, so callers cannot tell a
        // filtered stream from a value that was single all along.
        query!(br#"{"a": [1, false]}"#, ".a[] // 9",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 1);
            }
        );
    }

    #[test]
    fn regression_issue_160_alternative_with_empty_operands() {
        assert_eq!(outputs(b"null", "empty // 9"), ["9"]);

        // Nothing truthy on the left and nothing at all on the right: no output.
        query!(b"null", "false // empty", QueryResult::None => {});
    }

    #[test]
    fn regression_issue_160_boolean_operators_are_cartesian() {
        // jq loops the left operand outermost and short-circuits per output, so
        // the trailing `false` of `(true,false) and _` contributes a single
        // `false` while the leading `true` fans out over the right operand.
        assert_eq!(
            outputs(b"null", "(true,false) and (true,false)"),
            ["true", "false", "false"]
        );
        assert_eq!(
            outputs(b"null", "(true,false) or (true,false)"),
            ["true", "true", "false"]
        );
        assert_eq!(
            outputs(b"null", "(false,true) and (1,2)"),
            ["false", "true", "true"]
        );
    }

    #[test]
    fn regression_issue_160_boolean_short_circuit_skips_the_right_operand() {
        // A short-circuiting left output must not evaluate the right operand at
        // all, so the error never surfaces.
        query!(b"null", r#"false and error("x")"#,
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        query!(b"null", r#"true or error("x")"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn regression_issue_160_boolean_with_empty_operand_yields_nothing() {
        // These used to be `Error("no value")` / `Error("empty result")`,
        // because each operand was funnelled through `result_to_owned`.
        query!(b"null", "empty and true", QueryResult::None => {});
        query!(b"null", "true and empty", QueryResult::None => {});
        query!(b"null", "false or empty", QueryResult::None => {});
    }

    #[test]
    fn regression_issue_160_boolean_propagates_break() {
        // `result_to_owned` turned a `Break` into
        // `Error("break $out not in label")`; it now reaches its label.
        query!(b"null", "label $out | ((break $out) and true)",
            QueryResult::None => {}
        );
    }

    /// Render a `Vec<OwnedValue>` prefix as compact JSON strings, for
    /// comparing a `QueryResult::Partial`'s prefix the same way `outputs()`
    /// compares a whole stream.
    fn prefix_json(vs: &[OwnedValue]) -> Vec<String> {
        vs.iter().map(OwnedValue::to_json).collect()
    }

    #[test]
    fn regression_issue_400_comma_keeps_the_prefix_before_an_error() {
        // The root cause: before #400, any sibling erroring collapsed the
        // whole comma to a bare `Error`, discarding `1`.
        query!(b"null", r#"1,error("x")"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "x");
            }
        );
        // Same shape with more than one surviving output.
        query!(b"null", r#"1,2,error("x"),4"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
                assert_eq!(e.message, "x");
            }
        );
        // A zero-prefix error is unaffected: still the bare variant.
        query!(b"null", r#"error("x"),1"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "x");
            }
        );
    }

    #[test]
    fn regression_issue_400_pipe_keeps_the_prefix_before_an_error() {
        // Verified against jq 1.7.1: `(1,2,error("x")) | .+10` is `11`, `12`,
        // then the error.
        query!(b"null", r#"(1,2,error("x")) | .+10"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["11", "12"]);
                assert_eq!(e.message, "x");
            }
        );
    }

    #[test]
    fn regression_issue_400_as_binding_keeps_the_prefix_before_an_error() {
        // Verified against jq 1.7.1: `(1,2,error("x")) as $v | $v + 10` is
        // `11`, `12`, then the error.
        query!(b"null", r#"(1,2,error("x")) as $v | $v + 10"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["11", "12"]);
                assert_eq!(e.message, "x");
            }
        );
    }

    #[test]
    fn regression_issue_400_alternative_keeps_the_prefix_before_an_error() {
        // `(1,error("x")) // 2` is `1`, then the error — not `2` (the old
        // whole-stream collapse made the left side look like a bare error,
        // so `//` fell through to the right).
        query!(b"null", r#"(1,error("x")) // 2"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "x");
            }
        );
        // The prefix is still truthy-filtered like any `//` left operand:
        // `false` does not survive, but the error still does.
        query!(b"null", r#"(1,false,error("x")) // 2"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "x");
            }
        );
        // If filtering empties the prefix, it collapses back to a bare
        // error rather than a `Partial` with nothing in it.
        query!(b"null", r#"(false,false,error("x")) // 2"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "x");
            }
        );
    }

    #[test]
    fn regression_issue_400_boolean_keeps_the_prefix_before_a_control() {
        // Verified against jq 1.7.1: the first left output pairs against the
        // right operand's own prefix (`1`, truthy) before the right
        // operand's error/break surfaces.
        query!(b"null", r#"(true,true) and (1,error("x"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["true"]);
                assert_eq!(e.message, "x");
            }
        );
        // Raw shape (no enclosing label to catch the break): the pairing's
        // truthy prefix survives alongside the still-propagating break.
        query!(b"null", "(true,true) and (1, break $out)",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["true"]);
                assert_eq!(label, "out");
            }
        );
        query!(b"null", "(false,false) or (1, break $out)",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["true"]);
                assert_eq!(label, "out");
            }
        );
        // With an enclosing label, the matching break is caught and the
        // prefix is what's left — the issue's own example.
        query!(b"null", "label $out | ((true,true) and (1, break $out))",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(b"null", "label $out | ((false,false) or (1, break $out))",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn regression_issue_400_try_catch_emits_the_prefix_then_the_handler() {
        // Verified against jq 1.7.1: `try (1,2,error("x")) catch "caught:
        // \(.)"` is `1`, `2`, `"caught: x"`.
        assert_eq!(
            outputs(b"null", r#"try (1,2,error("x")) catch "caught: \(.)""#),
            ["1", "2", "\"caught: x\""]
        );
        // `try` catches `break` the same way it catches an error (#562),
        // and a `Partial` ending in `Break` gets the same treatment as one
        // ending in `Error` above: emit the prefix, then run the handler.
        assert_eq!(
            outputs(b"null", r#"try (1,2,break $out) catch "c""#),
            ["1", "2", "\"c\""]
        );
    }

    #[test]
    fn regression_issue_400_label_break_emits_the_prefix_and_drops_the_control() {
        // The issue's own example.
        assert_eq!(
            outputs(b"null", "label $out | 1,2,break $out,4"),
            ["1", "2"]
        );
    }

    #[test]
    fn regression_issue_494_foreach_keeps_the_prefix_before_an_error() {
        // Verified against jq 1.7.1: the update loop's own error.
        assert_eq!(
            outputs(
                b"null",
                "foreach (1,2,3) as $x (0; if $x == 3 then error(\"boom\") else .+$x end)"
            ),
            ["1", "3"]
        );
        // Verified against jq 1.7.1: the *input stream*'s own error, reached
        // after processing the input values that came before it.
        assert_eq!(
            outputs(b"null", r#"foreach (1,2,error("x"),4) as $v (0; .+$v)"#),
            ["1", "3"]
        );
    }

    #[test]
    fn regression_issue_494_while_keeps_the_prefix_before_an_error() {
        query!(b"1", "while(. < 5; if . == 3 then error(\"boom\") else .+1 end)",
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "2", "3"]);
                assert_eq!(e.message, "boom");
            }
        );
    }

    #[test]
    fn regression_issue_494_limit_keeps_the_prefix_before_an_error() {
        // `n` is not reached before the error, so it still surfaces.
        query!(b"null", r#"limit(3; 1,2,error("boom"),4)"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
                assert_eq!(e.message, "boom");
            }
        );
        // `limit` never asks its operand for values past `n` (verified
        // against jq 1.7.1), so once `n` is satisfied by the prefix, the
        // trailing error never surfaces at all.
        assert_eq!(
            outputs(b"null", r#"limit(2; 1,2,error("boom"))"#),
            ["1", "2"]
        );
        // A `break` used to be silently swallowed here; it now reaches its
        // label with the prefix intact (raw shape, no enclosing label).
        query!(b"null", "limit(5; 1,2,(3|break $out),4)",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
                assert_eq!(label, "out");
            }
        );
        // With an enclosing label, the break is caught — the issue's own
        // example.
        query!(b"null", "label $out | limit(5; 1,2,(3|break $out),4)",
            QueryResult::ManyOwned(vs) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
            }
        );
    }

    #[test]
    fn regression_issue_575_while_break_reaches_enclosing_label() {
        // The issue's own example, verified against jq 1.7.1: the label
        // catches the break cleanly, keeping whatever the loop already
        // output before it broke.
        assert_eq!(
            outputs(
                b"1",
                "label $out | while(true; if . >= 1 then break $out else .+1 end)"
            ),
            ["1"]
        );
        // Without an enclosing label, the break used to degrade into a
        // synthetic "break $out not in label" error; it now surfaces as a
        // real `Break`, with the value already output kept as a prefix
        // (same shape #494 already gives an `error(...)` in this position).
        query!(
            b"1",
            "while(true; if . >= 1 then break $out else .+1 end)",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(label, "out");
            }
        );
        // A break in `cond` (rather than `update`) is caught the same way,
        // with no output at all since it fires before the first value would
        // have been emitted.
        assert_eq!(
            outputs(b"1", "label $out | while(break $out; .+1)"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn regression_issue_575_foreach_break_reaches_enclosing_label() {
        // The issue's own example: break in UPDATE.
        assert_eq!(
            outputs(
                b"null",
                "label $out | foreach (1,2,3) as $x (0; if $x == 2 then break $out else . + $x end)"
            ),
            ["1"]
        );
        // Break in EXTRACT, verified against jq 1.7.1.
        assert_eq!(
            outputs(
                b"null",
                "label $out | foreach (1,2,3) as $x (0; .+$x; if $x == 2 then break $out else . end)"
            ),
            ["1"]
        );
        // Without an enclosing label, UPDATE's break surfaces as a real
        // `Break`, keeping the outputs already extracted as a prefix.
        query!(
            b"null",
            "foreach (1,2,3) as $x (0; if $x == 2 then break $out else . + $x end)",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(label, "out");
            }
        );
    }

    #[test]
    fn regression_issue_575_repeat_break_reaches_enclosing_label() {
        // The issue's own example: breaks on the very first iteration, so
        // nothing is ever output.
        assert_eq!(
            outputs(
                b"1",
                "label $out | repeat(if . >= 1 then break $out else .+1 end)"
            ),
            Vec::<String>::new()
        );
        // Without an enclosing label, the break surfaces as a real `Break`
        // rather than a synthetic error.
        query!(
            b"1",
            "repeat(if . >= 1 then break $out else .+1 end)",
            QueryResult::Break(label) => {
                assert_eq!(label, "out");
            }
        );
    }

    #[test]
    fn regression_issue_575_reduce_break_reaches_enclosing_label() {
        // Verified against jq 1.7.1.
        assert_eq!(
            outputs(
                b"null",
                "label $out | reduce (1,2,3) as $x (0; if $x == 2 then break $out else . + $x end)"
            ),
            Vec::<String>::new()
        );
        // `reduce` only ever emits its final accumulator, never
        // intermediates, so without a label the break surfaces bare (no
        // prefix to preserve) rather than as a synthetic error.
        query!(
            b"null",
            "reduce (1,2,3) as $x (0; if $x == 2 then break $out else . + $x end)",
            QueryResult::Break(label) => {
                assert_eq!(label, "out");
            }
        );
        // Corrected by #693 (was asserted the other way, unverified — see
        // below): `?` *does* swallow an escaping `break` the same way it
        // swallows a real error, exactly like `try` already does (#562) —
        // jq defines `E?` as sugar for `try E`, and it does not
        // special-case `break`. Re-verified directly against jq 1.7.1 three
        // ways (`?`, `try` with no catch, and the bare/uncaught form for
        // contrast) immediately before writing this assertion:
        // `jq -n 'label $out | ((reduce (1,2,3) as $x (0; if $x==2 then
        // break $out else .+$x end))?, "reached")'` prints `"reached"`
        // (`?` catches the break, so the comma continues); the `try`
        // spelling prints the same; the bare form with no `?`/`try` at all
        // prints nothing (the break escapes uncaught to `label $out`,
        // which then discards the rest of the comma). This test previously
        // asserted the *bare* form's behavior for the `?`-wrapped query —
        // an assumption that went unverified because, pre-#693, this
        // codebase's `Expr::Optional` never caught a `break` at all, so the
        // (wrong) expectation and the (buggy) implementation happened to
        // agree.
        assert_eq!(
            outputs(
                b"null",
                r#"label $out | ((reduce (1,2,3) as $x (0; if $x==2 then break $out else .+$x end))?, "reached")"#
            ),
            ["\"reached\""]
        );
    }

    #[test]
    fn regression_issue_575_until_break_reaches_enclosing_label() {
        // Break in `cond`, verified against jq 1.7.1.
        assert_eq!(
            outputs(b"1", "label $out | until(break $out; .+1)"),
            Vec::<String>::new()
        );
        // Break in `update`, verified against jq 1.7.1.
        assert_eq!(
            outputs(
                b"1",
                "label $out | until(. > 5; if . == 3 then break $out else .+1 end)"
            ),
            Vec::<String>::new()
        );
        // `until` only ever emits its final value, so without a label the
        // break surfaces bare rather than as a synthetic error.
        query!(
            b"1",
            "until(break $out; .+1)",
            QueryResult::Break(label) => {
                assert_eq!(label, "out");
            }
        );
    }

    #[test]
    fn regression_issue_400_first_last_nth_short_circuit_semantics() {
        // `first` and `nth` never ask their operand for values past what
        // they need, so a non-empty-enough prefix drops the trailing error
        // (verified against jq 1.7.1); `last` never short-circuits, so it
        // always sees the error.
        query!(b"null", r#"first(1,2,error("x"))"#,
            QueryResult::Owned(
                OwnedValue::Int(1) | OwnedValue::NumberLiteral(NumberRepr::Int(1), _)
            ) => {}
        );
        query!(b"null", r#"nth(1; 1,2,error("x"))"#,
            QueryResult::Owned(
                OwnedValue::Int(2) | OwnedValue::NumberLiteral(NumberRepr::Int(2), _)
            ) => {}
        );
        query!(b"null", r#"nth(5; 1,2,error("x"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "x");
            }
        );
        query!(b"null", r#"last(1,2,error("x"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "x");
            }
        );
    }

    #[test]
    fn regression_issue_400_array_and_object_construction_stay_atomic() {
        // Verified against jq 1.7.1: an error with nothing yet successfully
        // combined aborts with no output at all, unlike a bare top-level
        // comma. Array construction is unconditionally atomic this way — see
        // `partial_in_value_position_collapses_to_its_control`. Object
        // construction only looks atomic here because neither entry has a
        // completed sibling to combine with when `b` errors; once one does,
        // it streams the completed combinations first (#354) — see
        // `partial_prefix_survives_the_stream_forwarding_constructs`.
        query!(b"null", r#"[1,error("x"),3]"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "x");
            }
        );
        query!(b"null", r#"{a:1,b:error("x")}"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "x");
            }
        );
    }

    /// Assert that `filter` on `json` collapses a `Partial` sub-stream to a
    /// bare `Error` carrying `message`.
    ///
    /// The value-position constructs share one policy — "a sub-expression that
    /// errors partway aborts outright rather than exposing a prefix" — so they
    /// share one assertion helper. `divergence` records what jq 1.7.1 actually
    /// prints for the same filter, so a case where succinctly is *not* the
    /// oracle stays visibly labelled rather than reading as pinned-correct.
    fn assert_collapses_to_error(json: &[u8], filter: &str, message: &str, divergence: &str) {
        let index = JsonIndex::build(json);
        let cursor = index.root(json);
        let expr = parse(filter).unwrap();
        match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
            QueryResult::Error(e) => {
                assert_eq!(e.message, message, "filter: {filter} ({divergence})");
            }
            other => panic!("{filter} ({divergence}): expected a bare Error, got {other:?}"),
        }
    }

    /// Same as [`assert_collapses_to_error`] for a `Partial` ending in
    /// `break $out` — every case here uses that one label.
    fn assert_collapses_to_break(json: &[u8], filter: &str) {
        let index = JsonIndex::build(json);
        let cursor = index.root(json);
        let expr = parse(filter).unwrap();
        match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
            QueryResult::Break(l) => assert_eq!(l, "out", "filter: {filter}"),
            other => panic!("{filter}: expected a bare Break, got {other:?}"),
        }
    }

    #[test]
    fn partial_in_value_position_collapses_to_its_control() {
        // Every construct that embeds a sub-expression's output *into a value*
        // rather than forwarding it as a stream treats a `Partial` operand the
        // same as a bare `Error`/`Break`: the prefix is dropped and the control
        // surfaces alone.
        //
        // For array construction and `map`/`with_entries` (which desugar to it)
        // that matches jq 1.7.1. For the rest it does not — jq emits the value
        // built from the prefix and *then* fails. Those are recorded here as
        // divergences so the arms are covered without the expectation reading
        // as an oracle-backed one.
        //
        // Object construction *used* to be listed here too (`{a:1,b:(2,error("x"))}`
        // collapsing straight to the error), but #354's rewrite made it a real
        // generator like jq's: it now streams `{"a":1,"b":2}` before failing,
        // the same as jq 1.7.1. See
        // `partial_prefix_survives_the_stream_forwarding_constructs` for its
        // coverage.
        let atomic: &[(&[u8], &str, &str, &str)] = &[
            // Matches jq 1.7.1: no output at all, then the error.
            (b"null", r#"[1,(2,error("x")),3]"#, "x", "matches jq 1.7.1"),
            (b"[1,2]", r#"map((.,error("x")))"#, "x", "matches jq 1.7.1"),
            (
                br#"{"a":1}"#,
                r#"with_entries((.,error("x")))"#,
                "x",
                "matches jq 1.7.1",
            ),
            // `select`/`if` fan out over their condition's outputs (#378) —
            // they forward their operand as a stream, not a value, so they no
            // longer belong in this list; see
            // `partial_prefix_survives_the_stream_forwarding_constructs`.
            //
            // String interpolation *used* to be listed here too
            // (`"v=\((1,error("x")))"` collapsing straight to the error),
            // but #1403's rewrite made jq mode a real generator like
            // object construction's own #354 fix — it now streams "v=1"
            // before failing, the same as jq 1.7.1. See
            // `partial_prefix_survives_the_stream_forwarding_constructs`
            // for its coverage.
            (
                b"[10,20,30]",
                r#".[(1,error("x"))]"#,
                "x",
                "jq 1.7.1 prints 20, then fails",
            ),
            (
                b"[[7],[8]]",
                r#"(.[0],(.[1],error("x")))[(0+0)]"#,
                "x",
                "jq 1.7.1 prints 7 and 8, then fails",
            ),
            // `map_values` keeps only each key's first output, so jq 1.7.1
            // never reaches the error at all and exits 0.
            (
                br#"{"a":1}"#,
                r#"map_values((.,error("x")))"#,
                "x",
                r#"jq 1.7.1 prints {"a":1} and exits 0"#,
            ),
            (
                b"[1,2]",
                r#"map_values((.,error("x")))"#,
                "x",
                "jq 1.7.1 prints [1,2] and exits 0",
            ),
            // `reduce` only ever emits its final accumulator, so there is no
            // prefix to expose either way — this one matches jq 1.7.1.
            (
                b"null",
                r#"reduce (1,2,error("x")) as $v (0;.+$v)"#,
                "x",
                "matches jq 1.7.1",
            ),
        ];
        for (json, filter, message, divergence) in atomic {
            assert_collapses_to_error(json, filter, message, divergence);
        }

        // The `break` counterpart of each arm above. A bare `Break` keeps
        // propagating to its label, so these are the raw (unlabelled) shapes.
        let atomic_break: &[(&[u8], &str)] = &[
            (b"null", "[1,(2,break $out),3]"),
            (b"[1,2]", "map((.,break $out))"),
            (br#"{"a":1}"#, "with_entries((.,break $out))"),
            // `select`/`if`, string interpolation: see the comment in
            // `atomic` above.
            (b"[10,20,30]", ".[(1,break $out)]"),
            (b"[[7],[8]]", "(.[0],(.[1],break $out))[(0+0)]"),
            (br#"{"a":1}"#, "map_values((.,break $out))"),
            (b"[1,2]", "map_values((.,break $out))"),
            (b"null", "reduce (1,2,break $out) as $v (0;.+$v)"),
        ];
        for (json, filter) in atomic_break {
            assert_collapses_to_break(json, filter);
        }

        // With an enclosing label the break is caught, which is what makes the
        // array/object split above observable end-to-end: jq 1.7.1 agrees that
        // `[...]` yields nothing here. Object construction used to match that
        // (wrongly — see the comment above `atomic`); post-#354 it agrees with
        // jq 1.7.1 instead, printing the object built from the prefix.
        assert!(outputs(b"null", "label $out | [1,(2,break $out),3]").is_empty());
        assert_eq!(
            outputs(b"null", "label $out | {a:1,b:(2,break $out)}"),
            [r#"{"a":1,"b":2}"#]
        );
    }

    #[test]
    fn partial_prefix_survives_the_stream_forwarding_constructs() {
        // The mirror image of the test above: constructs that forward their
        // operand as a *stream* keep the prefix and re-attach the control.
        // Each expectation below matches jq 1.7.1.

        // A comma sibling that is itself a `Partial`.
        query!(b"null", r#"(1,error("x")), 9"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "x");
            }
        );

        // `skip` always wants the rest of the stream, so the control always
        // surfaces after whatever survived the skip.
        query!(b"null", r#"skip(1; 1,2,error("x"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["2"]);
                assert_eq!(e.message, "x");
            }
        );

        // A pipe whose *first* stage is a borrowed multi-element stream: the
        // elements already piped through survive a later element's control.
        query!(b"[1,2]", r#".[] | (., error("x"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "x");
            }
        );
        query!(b"[1,2]", ".[] | if . == 2 then break $out else . end",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(label, "out");
            }
        );

        // A pipe whose first stage is a single *owned* value.
        query!(b"null", r#"(1+1) | (., error("x"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["2"]);
                assert_eq!(e.message, "x");
            }
        );

        // A `Partial` first stage: every already-produced value is piped
        // through the rest before the held control is re-attached.
        query!(b"null", r#"(1,2,error("x")) | (., .+100)"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "101", "2", "102"]);
                assert_eq!(e.message, "x");
            }
        );
        // A control hit *while* piping the prefix takes precedence: the
        // generator never reaches the held one.
        query!(b"null", r#"(1,2,error("x")) | if . == 2 then error("y") else . end"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "y");
            }
        );
        query!(b"null", "(1,2,error(\"x\")) | if . == 2 then break $out else . end",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(label, "out");
            }
        );
        query!(b"null", r#"(1,2,error("x")) | (., error("z"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "z");
            }
        );
        // Piping the prefix through `empty` leaves nothing, so the held
        // control normalizes back to a bare `Error`.
        query!(b"null", r#"(1,2,error("x")) | empty"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "x");
            }
        );

        // `select`/`if` fan out over their condition's outputs (#378), so —
        // like every other construct in this test — a `Partial` condition
        // keeps whatever the truthy bits already produced before the
        // trailing control surfaces. Matches jq 1.7.1 (`select((true,error("x")))`
        // on `5` prints `5`, then fails; `if (1,error("x")) then "t" else "f" end`
        // prints `"t"`, then fails).
        query!(b"5", r#"select((true,error("x")))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["5"]);
                assert_eq!(e.message, "x");
            }
        );
        query!(b"5", r"select((true,break $out))",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["5"]);
                assert_eq!(label, "out");
            }
        );
        query!(b"null", r#"if (1,error("x")) then "t" else "f" end"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#""t""#]);
                assert_eq!(e.message, "x");
            }
        );
        query!(b"null", r#"if (1,break $out) then "t" else "f" end"#,
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), [r#""t""#]);
                assert_eq!(label, "out");
            }
        );

        // Object construction (#354): a value generator's own prefix is
        // combined into objects before its trailing control surfaces.
        // Matches jq 1.7.1 (`{a:1,b:(2,error("x"))}` prints `{"a":1,"b":2}`,
        // then fails).
        query!(b"null", r#"{a:1,b:(2,error("x"))}"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#"{"a":1,"b":2}"#]);
                assert_eq!(e.message, "x");
            }
        );
        query!(b"null", r"{a:1,b:(2,break $out)}",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), [r#"{"a":1,"b":2}"#]);
                assert_eq!(label, "out");
            }
        );
        // A trailing control on an *earlier* entry aborts every enclosing
        // loop outright rather than resuming it — jq 1.7.1 agrees `a`'s
        // second branch is never tried once `b` fails on its first.
        query!(b"null", r#"{a:(1,2),b:(10,error("x"))}"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#"{"a":1,"b":10}"#]);
                assert_eq!(e.message, "x");
            }
        );
        // A trailing control on the key generator: every key it already
        // produced runs its full value loop first (jq 1.7.1: `{"x":10}` then
        // `{"x":20}`, then the non-string-key error).
        query!(b"null", r#"{("x",1):(10,20)}"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#"{"x":10}"#, r#"{"x":20}"#]);
                assert_eq!(e.message, "Cannot use number (1) as object key");
            }
        );

        // #1403: jq mode's string interpolation is now the same kind of
        // generator object construction became under #354 -- it used to be
        // listed in `partial_in_value_position_collapses_to_its_control`'s
        // `atomic` table (labelled as a documented divergence from jq
        // 1.7.1, which the old comment already recorded as printing "v=1"
        // then failing); now that it's a real fan-out generator, it agrees
        // with jq 1.7.1 exactly, same as object construction's own move.
        query!(b"null", r#""v=\((1,error("x")))""#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#""v=1""#]);
                assert_eq!(e.message, "x");
            }
        );
        query!(b"null", r#""v=\((1,break $out))""#,
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), [r#""v=1""#]);
                assert_eq!(label, "out");
            }
        );
        // A trailing control on an *earlier* slot aborts every enclosing
        // loop outright rather than resuming it -- matches object
        // construction's identical rule above, just under string
        // interpolation's own reversed nesting (#1403: the *first*/
        // leftmost slot varies fastest, the opposite of object
        // construction's "last entry varies fastest"). jq 1.7.1 agrees the
        // second slot's `4` is never tried once the first slot fails on
        // its own second output.
        query!(b"null", r#""\((1,error("x")))-\(3,4)""#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#""1-3""#]);
                assert_eq!(e.message, "x");
            }
        );
    }

    #[test]
    fn partial_flows_through_as_and_destructuring_binds() {
        // `as` and its destructuring form both hold the bind expression's own
        // control until the loop over its prefix has run. Verified against jq
        // 1.7.1: `([1],[2],error("x")) as [$a] | $a` is `1`, `2`, then the
        // error.
        query!(b"null", r#"([1],[2],error("x")) as [$a] | $a"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
                assert_eq!(e.message, "x");
            }
        );
        // A control raised by the *body* stops the loop, keeping the outputs
        // the earlier bindings already produced — whether the body raises it
        // bare or as the tail of its own `Partial`.
        query!(b"null", r#"(1,2) as $v | if $v == 2 then error("y") else $v end"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "y");
            }
        );
        query!(b"null", r#"([1],[2]) as [$a] | if $a == 2 then error("y") else $a end"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "y");
            }
        );
        query!(b"null", r#"(1,2) as $v | ($v, error("q"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "q");
            }
        );
        query!(b"null", "(1,2) as $v | if $v == 2 then break $out else $v end",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(label, "out");
            }
        );
        query!(b"null", r#"([1],[2]) as [$a] | ($a, error("z"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "z");
            }
        );
        query!(b"null", "([1],[2]) as [$a] | if $a == 2 then break $out else $a end",
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(label, "out");
            }
        );

        // The non-`Partial` bind shapes, which share the same match: a
        // borrowed single value, a borrowed stream, an owned value, an empty
        // stream, and a bind that is itself a bare control.
        assert_eq!(outputs(b"5", ". as $v | $v"), ["5"]);
        assert_eq!(outputs(b"null", "(1+1) as $v | $v"), ["2"]);
        assert_eq!(outputs(b"[1,2]", ".[] as $v | $v"), ["1", "2"]);
        assert_eq!(outputs(b"[[1],[2]]", ".[] as [$a] | $a"), ["1", "2"]);
        for (json, filter) in [
            (b"null".as_slice(), "empty as $v | 1"),
            (b"null".as_slice(), "empty as [$a] | $a"),
        ] {
            let index = JsonIndex::build(json);
            let cursor = index.root(json);
            let expr = parse(filter).unwrap();
            assert!(
                matches!(
                    eval::<Vec<u64>, JqSemantics>(&expr, cursor),
                    QueryResult::None
                ),
                "filter: {filter}"
            );
        }
        assert_collapses_to_error(b"null", r#"error("x") as $v | 1"#, "x", "matches jq 1.7.1");
        assert_collapses_to_error(
            b"null",
            r#"error("x") as [$a] | $a"#,
            "x",
            "matches jq 1.7.1",
        );
        assert_collapses_to_break(b"null", "(break $out) as $v | 1");
        assert_collapses_to_break(b"null", "(break $out) as [$a] | $a");
    }

    #[test]
    fn partial_flows_through_foreach_input_and_state() {
        // Every shape `foreach`'s input stream can take, all sharing one
        // match: a borrowed single value, an owned value, an empty stream, and
        // a bare control.
        assert_eq!(outputs(b"null", "foreach . as $x (0; .+1)"), ["1"]);
        assert_eq!(outputs(b"null", "foreach (1+1) as $x (0; .+$x)"), ["2"]);
        assert!(outputs(b"null", "foreach empty as $x (0; .+$x)").is_empty());
        assert_collapses_to_error(
            b"null",
            r#"foreach error("x") as $x (0; .+$x)"#,
            "x",
            "matches jq 1.7.1",
        );
        assert_collapses_to_break(b"null", "foreach (break $out) as $x (0; .+$x)");

        // A multi-output UPDATE fans out — each output is extracted on its
        // own via the implicit identity EXTRACT — instead of folding into a
        // single collapsed array, and a `Partial` UPDATE's trailing error
        // still surfaces once the outputs it did produce are recorded
        // (#534). Verified against jq 1.7.1: `1`, then the error, since the
        // error happens mid-step (before `foreach` ever reaches $x=2).
        query!(b"null", r#"foreach (1,2) as $x (0; (.+$x, error("q")))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "q");
            }
        );
        // Verified against jq 1.7.1: `1`, `100`, then the error — both of
        // UPDATE's successful outputs are extracted individually, not
        // folded into `[1,100]` first.
        query!(b"null", r#"foreach (1,2) as $x (0; (.+$x, .+100, error("q")))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "100"]);
                assert_eq!(e.message, "q");
            }
        );
        // A `Partial` INIT forks over every output it did produce before
        // erroring — here just the one, `0` — and that fork's own complete
        // output is kept ahead of INIT's own deferred error (#534). Verified
        // against jq 1.7.1: `1`, `3`, then the error.
        query!(b"null", r#"foreach (1,2) as $x ((0,error("i")); .+$x)"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "3"]);
                assert_eq!(e.message, "i");
            }
        );

        // A failing EXTRACT keeps the steps already emitted, the same as a
        // failing UPDATE does. Verified against jq 1.7.1: `1`, then the error.
        query!(b"null", r#"foreach (1,2) as $x (0; .+$x; if . == 3 then error("e") else . end)"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1"]);
                assert_eq!(e.message, "e");
            }
        );
    }

    #[test]
    fn partial_while_condition_error_keeps_the_values_already_output() {
        // #494 covers `while`'s UPDATE erroring; its CONDITION has its own
        // arm. Verified against jq 1.7.1: `1`, `2`, then the error.
        query!(b"1", r#"while(if . == 3 then error("c") else . < 5 end; .+1)"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
                assert_eq!(e.message, "c");
            }
        );
    }

    #[test]
    fn partial_short_circuit_split_across_first_last_nth_limit() {
        // `last` cannot short-circuit, so a `Partial` ending in a break
        // surfaces that break (the error case is already pinned above).
        assert_collapses_to_break(b"null", "last(1,2,break $out)");
        // `nth` stops at index `n`, so the break is reached only when the
        // prefix is too short.
        query!(b"null", "nth(1; 1,2,break $out)",
            QueryResult::Owned(
                OwnedValue::Int(2) | OwnedValue::NumberLiteral(NumberRepr::Int(2), _)
            ) => {}
        );
        assert_collapses_to_break(b"null", "nth(5; 1,2,break $out)");
        // Same split for `first`.
        query!(b"null", "first(1,2,break $out)",
            QueryResult::Owned(
                OwnedValue::Int(1) | OwnedValue::NumberLiteral(NumberRepr::Int(1), _)
            ) => {}
        );
        // A `limit` operand that is a *bare* break still reaches its label —
        // the arm that used to swallow it.
        assert_collapses_to_break(b"null", "limit(5; break $out)");
    }

    #[test]
    fn try_splices_its_catch_handler_after_the_prefix() {
        // `prepend` joins the body's prefix to whatever the catch handler
        // yields, so each handler shape gets its own arm. All verified
        // against jq 1.7.1 except the `break` case, which jq catches (#562).
        assert_eq!(
            outputs(b"null", r#"try (1,2,error("x")) catch empty"#),
            ["1", "2"]
        );
        assert_eq!(
            outputs(b"null", r#"try (1,2,error("x")) catch (., .)"#),
            ["1", "2", "\"x\"", "\"x\""]
        );
        // No handler at all: the prefix is kept and the error swallowed.
        assert_eq!(outputs(b"null", r#"try (1,2,error("x"))"#), ["1", "2"]);
        assert_eq!(outputs(b"null", r#"(1,2,error("x"))?"#), ["1", "2"]);
        // The error-in-last-position cases above happen to be numerically
        // correct even under #693's bug (nothing follows the error to wrongly
        // continue to). An operand *after* the masked error is the case that
        // actually distinguishes correct behavior: jq stops at the error and
        // never reaches `2`.
        assert_eq!(outputs(b"null", r#"try (1,error("x"),2)"#), ["1"]);
        assert_eq!(outputs(b"null", r#"(1,error("x"),2)?"#), ["1"]);
        // A handler that fails in turn: the two prefixes concatenate and the
        // handler's own control terminates the stream.
        query!(b"null", r#"try (1,2,error("x")) catch error("y")"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
                assert_eq!(e.message, "y");
            }
        );
        query!(b"null", r#"try (1,2,error("x")) catch (1, error("y"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), ["1", "2", "1"]);
                assert_eq!(e.message, "y");
            }
        );
        query!(b"null", r#"try (1,2,error("x")) catch break $out"#,
            QueryResult::Partial(vs, Control::Break(label)) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
                assert_eq!(label, "out");
            }
        );
    }

    /// #1908 (#1820 Category 2): `prepend` -- the function backing
    /// `try`/`catch`'s output-prefix splicing -- used unchecked `to_owned_lossy`
    /// on the catch handler's own result, silently substituting `""` for an
    /// undecodable string instead of raising `EvalError::decode_failure`.
    ///
    /// Exercised directly against `prepend` rather than through a full
    /// `try`/`catch` query: every path that could hand `prepend` an
    /// undecodable *borrowed* cursor turns out to be intercepted upstream
    /// today (`error(msg)`'s own payload materialization already raises a
    /// decode failure unconditionally per #1907's fix, before `prepend` is
    /// ever reached; `break`'s catch input is hardcoded `Null`; a variable
    /// bound before `try` resolves through a separate, already-owned path
    /// that never reaches `prepend`'s cursor arms at all). Matching #1897's
    /// own `eval_index_expr` precedent for this same situation, this
    /// white-box test still pins the fix directly against the function
    /// (and was confirmed to fail without it, by temporarily reverting the
    /// fix and re-running).
    #[test]
    fn prepend_raises_on_handler_decode_failure_1908() {
        let json: &[u8] = b"{\"a\": \"\xff\xfe\", \"b\": \"ok\"}";
        let index = JsonIndex::build(json);
        let cursor = index.root(json);

        // `One` arm.
        let expr = parse(".a").unwrap();
        let result = eval_single::<Vec<u64>, JqSemantics>(&expr, cursor.value(), false);
        match prepend(vec![OwnedValue::Int(1)], result) {
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(vs, vec![OwnedValue::Int(1)]);
                assert!(e.is_decode_failure());
            }
            other => panic!("unexpected result: {other:?}"),
        }

        // `Many` arm: a decodable value ahead of the undecodable one.
        let expr = parse(".b, .a").unwrap();
        let result = eval_single::<Vec<u64>, JqSemantics>(&expr, cursor.value(), false);
        match prepend(vec![OwnedValue::Int(1)], result) {
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(
                    vs,
                    vec![OwnedValue::Int(1), OwnedValue::String("ok".to_string())]
                );
                assert!(e.is_decode_failure());
            }
            other => panic!("unexpected result: {other:?}"),
        }

        // Positive control: a fully decodable handler result still splices
        // normally.
        let expr = parse(".b").unwrap();
        let result = eval_single::<Vec<u64>, JqSemantics>(&expr, cursor.value(), false);
        match prepend(vec![OwnedValue::Int(1)], result) {
            QueryResult::ManyOwned(vs) => {
                assert_eq!(
                    vs,
                    vec![OwnedValue::Int(1), OwnedValue::String("ok".to_string())]
                );
            }
            other => panic!("unexpected result: {other:?}"),
        }
    }

    #[test]
    fn partial_reduced_to_a_single_value_keeps_its_first_output() {
        // The "this position takes one value, not a stream" helpers all keep
        // the prefix's first output and drop the trailing control.
        //
        // Assignment RHS used to be pinned here too (`.a = (1,error("x"))`
        // used to reduce to `Owned({"a":1})`, diverging from jq 1.7.1's
        // `{"a":1}` then exit 5), but `=` no longer reduces its RHS to a
        // single value (#392) — see
        // `test_assign_multi_output_rhs_errors_after_partial_output`, which
        // now pins the matching-jq `Partial` behavior instead.

        // `pick`/`omit` key expressions. jq 1.7.1 rejects both filters
        // outright ("Invalid path expression"), a separate pre-existing gap.
        query!(br#"{"a":1,"b":2}"#, r#"pick((["a"],error("x")))"#,
            QueryResult::Owned(OwnedValue::Object(m)) => {
                assert_eq!(m.len(), 1);
                assert!(m.contains_key("a"));
            }
        );
        query!(br#"{"a":1,"b":2}"#, r#"omit((["a"],error("x")))"#,
            QueryResult::Owned(OwnedValue::Object(m)) => {
                assert_eq!(m.len(), 1);
                assert!(m.contains_key("b"));
            }
        );
    }

    #[test]
    fn boolean_operand_that_is_a_bare_error_propagates_it() {
        // The zero-prefix counterpart of the `and`/`or` prefix cases already
        // pinned above: with nothing accumulated, the operand's control is
        // all that is left. Matches jq 1.7.1.
        assert_collapses_to_error(b"null", r#"true and error("x")"#, "x", "matches jq 1.7.1");
        assert_collapses_to_error(b"null", r#"false or error("x")"#, "x", "matches jq 1.7.1");
    }

    #[test]
    fn query_result_partial_is_an_error_and_collects_its_prefix() {
        // `is_error` answers "did evaluating this end in an error", so a
        // `Partial` that ends in one counts; a `Partial` ending in a break
        // does not. `collect_owned` keeps the prefix either way — that is the
        // whole point of #400/#494.
        let err: QueryResult<Vec<u64>> = QueryResult::Partial(
            vec![OwnedValue::Int(1)],
            Control::Error(EvalError::new("x")),
        );
        assert!(err.is_error());
        assert_eq!(err.collect_owned(), vec![OwnedValue::Int(1)]);

        let brk: QueryResult<Vec<u64>> = QueryResult::Partial(
            vec![OwnedValue::Int(1), OwnedValue::Int(2)],
            Control::Break("out".into()),
        );
        assert!(!brk.is_error());
        assert_eq!(
            brk.collect_owned(),
            vec![OwnedValue::Int(1), OwnedValue::Int(2)]
        );
    }

    #[test]
    fn eval_lenient_drops_a_partial_prefix() {
        // `eval_lenient` is the public "give me borrowed values, swallow the
        // failures" entry point: an owned prefix has no borrowed
        // representation, so a `Partial` yields nothing, exactly like the
        // `Owned`/`ManyOwned`/`Break` arms beside it.
        let json = b"null";
        let index = JsonIndex::build(json);
        let expr = parse(r#"1,error("x")"#).unwrap();
        let out = eval_lenient::<Vec<u64>, JqSemantics>(&expr, index.root(json));
        assert!(out.is_empty());
    }

    #[test]
    fn test_complex_expressions() {
        // Comparison with arithmetic
        query!(br#"{"x": 10}"#, ".x > 5 and .x < 20",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        // Alternative with comparison
        query!(br#"{"val": 3}"#, ".val > 0 // false",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    // Phase 3 tests: Conditionals and Control Flow

    #[test]
    fn test_if_then_else() {
        // Basic if-then-else: true condition
        query!(br#"{"a": true}"#, "if .a then 1 else 2 end",
            QueryResult::Owned(
                OwnedValue::Int(1) | OwnedValue::NumberLiteral(NumberRepr::Int(1), _)
            ) => {}
        );

        // Basic if-then-else: false condition
        query!(br#"{"a": false}"#, "if .a then 1 else 2 end",
            QueryResult::Owned(
                OwnedValue::Int(2) | OwnedValue::NumberLiteral(NumberRepr::Int(2), _)
            ) => {}
        );

        // If with comparison condition
        query!(br#"{"x": 10}"#, "if .x > 5 then \"big\" else \"small\" end",
            QueryResult::Owned(OwnedValue::String(s)) if s == "big" => {}
        );

        // If with null condition (falsy)
        query!(br#"{"a": null}"#, "if .a then 1 else 2 end",
            QueryResult::Owned(
                OwnedValue::Int(2) | OwnedValue::NumberLiteral(NumberRepr::Int(2), _)
            ) => {}
        );

        // If with number condition (truthy, even 0)
        query!(br#"{"a": 0}"#, "if .a then 1 else 2 end",
            QueryResult::Owned(
                OwnedValue::Int(1) | OwnedValue::NumberLiteral(NumberRepr::Int(1), _)
            ) => {}
        );
    }

    #[test]
    fn test_if_elif() {
        // if-elif-else with first condition true
        query!(br#"{"x": 1}"#, "if .x == 1 then \"one\" elif .x == 2 then \"two\" else \"other\" end",
            QueryResult::Owned(OwnedValue::String(s)) if s == "one" => {}
        );

        // if-elif-else with second condition true
        query!(br#"{"x": 2}"#, "if .x == 1 then \"one\" elif .x == 2 then \"two\" else \"other\" end",
            QueryResult::Owned(OwnedValue::String(s)) if s == "two" => {}
        );

        // if-elif-else with else branch
        query!(br#"{"x": 3}"#, "if .x == 1 then \"one\" elif .x == 2 then \"two\" else \"other\" end",
            QueryResult::Owned(OwnedValue::String(s)) if s == "other" => {}
        );
    }

    #[test]
    fn test_if_no_else() {
        // if without else (defaults to null)
        query!(br#"{"a": false}"#, "if .a then 1 end",
            QueryResult::Owned(OwnedValue::Null) => {}
        );

        query!(br#"{"a": true}"#, "if .a then 1 end",
            QueryResult::Owned(
                OwnedValue::Int(1) | OwnedValue::NumberLiteral(NumberRepr::Int(1), _)
            ) => {}
        );
    }

    #[test]
    fn test_if_with_expressions() {
        // if with arithmetic in branches
        query!(br#"{"x": 5}"#, "if .x > 0 then .x * 2 else .x end",
            QueryResult::Owned(OwnedValue::Int(10)) => {}
        );

        // if with field access
        query!(br#"{"type": "a", "a": 1, "b": 2}"#, "if .type == \"a\" then .a else .b end",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 1);
            }
        );
    }

    #[test]
    fn test_if_multi_output_condition_forks_the_branches() {
        // jq fans `if`/`select` out over every output of the condition,
        // running the body once per output rather than consulting only the
        // first one (#378). Pinned against jq 1.7.1.
        assert_eq!(
            outputs(b"null", r#"if (true,false) then "a" else "b" end"#),
            [r#""a""#, r#""b""#]
        );
        assert_eq!(
            outputs(b"null", r#"if (1==1, 1==2, 1==1) then "t" else "f" end"#),
            [r#""t""#, r#""f""#, r#""t""#]
        );
        // An `empty` condition contributes no bits, so no branch runs at all.
        assert!(outputs(b"null", r#"if empty then "t" else "f" end"#).is_empty());
    }

    #[test]
    fn test_try_catch_success() {
        // try with no error - returns result
        query!(br#"{"a": 1}"#, "try .a catch 0",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 1);
            }
        );

        // try without catch, no error
        query!(br#"{"a": 1}"#, "try .a",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 1);
            }
        );
    }

    #[test]
    fn test_try_catch_error() {
        // try with catch on missing field - no error to catch, returns null
        // (jq returns null for missing fields on objects, not an error)
        query!(br"{}", "try .missing catch \"default\"",
            QueryResult::One(StandardJson::Null) => {}
        );

        // try without catch on missing field - returns null
        query!(br"{}", "try .missing",
            QueryResult::One(StandardJson::Null) => {}
        );

        // try with catch on actual error (field access on number) - catch is triggered
        query!(br"123", "try .foo catch \"default\"",
            QueryResult::Owned(OwnedValue::String(s)) if s == "default" => {}
        );

        // try without catch on actual error - error is suppressed (returns None)
        query!(br"123", "try .foo",
            QueryResult::None => {}
        );

        // try with null catch on actual error
        query!(br"123", "try .foo catch null",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
    }

    #[test]
    fn regression_issue_562_try_catches_break() {
        // `eval_try` only matched `QueryResult::Error`; a `Break` fell
        // through to the `other => other` arm and escaped an enclosing
        // `try`/`catch` untouched. jq's `catch` catches `break` the same
        // way it catches a raised error.
        query!(b"null", r#"label $out | try break $out catch "c""#,
            QueryResult::Owned(OwnedValue::String(s)) if s == "c" => {}
        );
    }

    #[test]
    fn regression_issue_562_try_without_catch_swallows_break() {
        // A bare `try break $out` (no catch) also absorbs the break, same
        // as it absorbs an uncaught error.
        assert_eq!(
            outputs(b"null", r#"label $out | (try break $out) , "after""#),
            vec!["\"after\""]
        );
    }

    #[test]
    fn test_try_catch_optional() {
        // Optional on missing field returns null, not None
        query!(br"{}", "try .missing? catch \"default\"",
            QueryResult::One(StandardJson::Null) => {}
        );

        // Optional on actual error (field on number) - optional suppresses error
        query!(br"123", "try .foo? catch \"default\"",
            QueryResult::None => {}
        );
    }

    #[test]
    fn test_error_basic() {
        // Bare `error` raises the input value, as jq does: `{} | error`
        // reports `{}`, not `null`.
        query!(br"{}", "error",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "{}");
                assert_eq!(
                    e.value,
                    EvalErrorPayload::Value(OwnedValue::Object(IndexMap::new()))
                );
            }
        );

        // error with string message
        query!(br"{}", "error(\"something went wrong\")",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "something went wrong");
                assert_eq!(
                    e.value,
                    EvalErrorPayload::Value(OwnedValue::String("something went wrong".into()))
                );
            }
        );

        // error with number message (message is serialized, payload is not)
        query!(br"{}", "error(42)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "42");
                assert_eq!(e.value, EvalErrorPayload::Value(OwnedValue::Int(42)));
            }
        );
    }

    #[test]
    fn test_error_with_field() {
        // error with field access for message
        query!(br#"{"msg": "custom error"}"#, "error(.msg)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "custom error");
            }
        );
    }

    #[test]
    fn eval_error_msg_expr_raises_decode_failure_1907() {
        // #1907 item 1: `error(msg)`'s `Some(msg_expr)` branch used to
        // materialize `msg` via the unchecked `to_owned_lossy`, silently
        // substituting `""` for an undecodable string instead of raising its
        // own decode failure -- asymmetric with bare `error` (this file's
        // `None` arm, fixed by #1820), which already used `to_owned`.
        //
        // Exercised directly through this macro's own `eval::eval` dispatch,
        // not the CLI: `Expr::Error` has no native `eval_generic::eval_single`
        // arm, so every CLI-parsed `error(msg)` query is decode-checked
        // earlier, by that file's wildcard bridge (`to_owned_with_cursor` /
        // `owned_or_err!`), before this function ever runs -- confirmed live
        // against the built CLI binary with the identical `{"a": "\uXXXX"}` /
        // `error(.a)` repro, which already raised correctly before this fix.
        query!(br#"{"a": "\uXXXX"}"#, "error(.a)",
            QueryResult::Error(e) => {
                assert!(e.is_decode_failure(), "expected a decode failure, got: {e:?}");
                assert_eq!(e.message, "invalid unicode escape sequence");
            }
        );
    }

    #[test]
    fn eval_error_msg_expr_decode_failure_not_suppressed_by_optional_1907() {
        // Sibling of the above: per #1247/#1620, a decode failure is never
        // suppressed by `?` -- `error(.a)?` must still raise uncaught, the
        // same rule bare `error?` on an undecodable value already follows.
        query!(br#"{"a": "\uXXXX"}"#, "error(.a)?",
            QueryResult::Error(e) => {
                assert!(e.is_decode_failure(), "expected a decode failure, got: {e:?}");
            }
        );
    }

    #[test]
    fn eval_error_msg_expr_raises_decode_failure_through_comma_1907() {
        // A comma expression (`(.a, .b)`) keeps both operands lazily
        // borrowed when neither forces owned promotion (`eval_comma`'s
        // `borrowed_vec_to_result`), so `msg_result` here is
        // `QueryResult::Many`, not `One` -- a case the initial version of
        // this fix missed (only special-casing `One`), letting a `Many`
        // whose first element is undecodable fall through to
        // `result_to_owned`'s own unchecked `to_owned_lossy` (#1907 review).
        // `error`'s generator-argument semantics only ever consume the
        // *first* output (see `result_to_owned_ctrl`'s doc comment), so
        // checking `Many`'s first element is the correct, matching fix.
        query!(br#"{"a": "\uXXXX", "b": "ok"}"#, "error((.a, .b))",
            QueryResult::Error(e) => {
                assert!(e.is_decode_failure(), "expected a decode failure, got: {e:?}");
            }
        );
        query!(br#"{"a": "\uXXXX", "b": "ok"}"#, "error((.a, .b))?",
            QueryResult::Error(e) => {
                assert!(e.is_decode_failure(), "expected a decode failure, got: {e:?}");
            }
        );
    }

    #[test]
    fn eval_error_msg_expr_malformed_member_reaches_an_enclosing_catch_1907() {
        // A more discriminating sibling of the plain-raise test below: `?`
        // and `try`/`catch` suppression is `eval_try`'s own decision, made
        // *after* inspecting whatever this function returns -- for a bare
        // `?` (no catch handler), `eval_try` discards any non-decode-failure
        // `Error` to `None` regardless of how it got there, so that shape
        // can't tell an internally-self-suppressing `eval_error` apart from
        // one that raises and lets `eval_try` decide. Wrapping a *real*
        // catch handler inside the `?` can: with `optional` forced `true` by
        // the outer `?`, the inner `eval_try`'s `catch = Some(...)` arm only
        // ever runs if this function actually returns `Error(e)` rather than
        // self-suppressing to `None` first. Confirmed this reaches the
        // handler with the fix, and would return bare `None` (skipping the
        // handler entirely) without it.
        query!(br#"{"a":1,"b"}"#, r#"(try error(.) catch "caught")?"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "caught");
            }
        );
    }

    #[test]
    fn eval_error_msg_expr_malformed_member_raised_1907() {
        // Sibling to the decode-failure tests above, for the *other* error
        // class `to_owned` can raise: a #1194 malformed-member error
        // (a trailing unpaired object member JSON's own semi-index accepts,
        // e.g. `{"a":1,"b"}`) is not `is_decode_failure()`-tagged, but
        // `to_owned` raises it unconditionally at every other call
        // site in this file, including this function's own `None` arm below
        // -- so `error(.)` must raise it here too, not silently swallow it
        // into `""` via an unchecked `to_owned_lossy`.
        //
        // This does *not* assert anything about a *wrapping* `?`/`try`:
        // that suppression/catch decision belongs to `eval_try`, one level
        // up, whose own `is_decode_failure()`-only exclusion is a separate,
        // pre-existing gap (closely related to #1907's own item 3) outside
        // this fix's scope -- `eval_try` re-decides uniformly from the
        // `Error` this function returns, regardless of *how* this function
        // arrived at it.
        query!(br#"{"a":1,"b"}"#, "error(.)",
            QueryResult::Error(e) => {
                assert!(!e.is_decode_failure());
            }
        );
    }

    #[test]
    fn test_try_catch_raised_error() {
        // try-catch with error - error is caught
        query!(br"{}", "try error(\"oops\") catch \"caught\"",
            QueryResult::Owned(OwnedValue::String(s)) if s == "caught" => {}
        );

        // try without catch - error is suppressed
        query!(br"{}", "try error(\"oops\")",
            QueryResult::None => {}
        );
    }

    /// `halt`, `halt_error`/`halt_error(n)`, and `stderr` (#791). These tests
    /// only exercise `eval.rs`'s `QueryResult`/`Control` shape — `eval.rs`
    /// never calls `process::exit` itself (only `main.rs` does, once the CLI
    /// runner sees the exit code), so asserting on `Control::Halt` here can't
    /// terminate the test process. `stderr`'s real write (std-gated) does
    /// fire during these tests, same as any other test exercising it; that's
    /// harmless, just not asserted on here (see the CLI-level tests in
    /// `tests/jq_cli_tests.rs`/`tests/yq_cli_tests.rs` for the actual byte
    /// content of what gets written).
    #[test]
    fn test_halt_basic() {
        // Bare `halt`: no output, exit code 0, no prior prefix.
        query!(b"null", "halt",
            QueryResult::Halt(0) => {}
        );
    }

    #[test]
    fn test_halt_keeps_prior_output_as_a_partial_prefix() {
        // Verified against jq 1.7.1: `jq -n '1,2,halt,3'` prints `1` and `2`
        // then exits 0 -- outputs already produced before `halt` survive,
        // same #400/#494 mechanism as `error`/`break`, but nothing after it
        // runs.
        query!(b"null", "1,2,halt,3",
            QueryResult::Partial(vs, Control::Halt(0)) => {
                assert_eq!(prefix_json(&vs), ["1", "2"]);
            }
        );
    }

    #[test]
    fn test_halt_not_caught_by_try_catch() {
        // Verified live against jq 1.7.1: `jq -n 'try (halt) catch "caught"'`
        // exits 0 and never prints "caught" -- unlike `error`, `halt` is not
        // catchable.
        query!(b"null", r#"try (halt) catch "caught""#,
            QueryResult::Halt(0) => {}
        );
    }

    #[test]
    fn test_halt_not_caught_by_label_break() {
        // Verified live against jq 1.7.1: `jq -n 'label $out | (halt, break
        // $out)'` exits 0 -- the label's own `break $out` never gets a chance
        // to run, and even if it did, `halt` wouldn't be caught by it either.
        query!(b"null", "label $out | (halt, break $out)",
            QueryResult::Halt(0) => {}
        );
    }

    #[test]
    fn test_halt_error_default_exit_code() {
        // Bare `halt_error` defaults to jq's exit code 5 under `JqSemantics`
        // (`query!` always evaluates with `JqSemantics`; the yq-mode default
        // of 1 is exercised by `yq_query!` in the sibling test below).
        query!(br#""x""#, "halt_error",
            QueryResult::Halt(5) => {}
        );
    }

    #[test]
    fn test_halt_error_custom_exit_code() {
        // Verified against jq 1.7.1: `"foo" | halt_error(7)` exits 7, not 5.
        query!(br#""x""#, "halt_error(7)",
            QueryResult::Halt(7) => {}
        );
    }

    #[test]
    fn test_halt_error_not_caught_by_try_catch() {
        // Verified live against jq 1.7.1: `try ("x"|halt_error) catch
        // "caught"` exits 5 and never prints "caught".
        query!(b"null", r#"try ("x"|halt_error) catch "caught""#,
            QueryResult::Halt(5) => {}
        );
    }

    #[test]
    fn test_stderr_passes_through_unchanged() {
        // `stderr`'s whole point is a real side effect the evaluator alone
        // can't observe in-process (see this block's doc comment) -- what
        // *can* be asserted here is the passthrough contract: the returned
        // value is exactly the input, unchanged.
        query!(br#""hello""#, "stderr",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "hello");
            }
        );
        query!(b"[1,2]", "stderr",
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(vs, vec![OwnedValue::Int(1), OwnedValue::Int(2)]);
            }
        );
    }

    #[test]
    fn test_yq_halt_error_default_exit_code() {
        // yq mode's bare `halt_error` defaults to 1 (yq's uniform failure
        // code, `DiagStyle::error_exit_code()`'s yq arm in `output.rs`), not
        // jq's 5 -- there is no real `yq` to verify this against (mikefarah/yq
        // has no `halt_error`; this is this codebase's own documented
        // extension), so this pins the deliberate design choice instead.
        yq_query!(br#""x""#, "halt_error",
            QueryResult::Halt(1) => {}
        );
    }

    /// The catch handler's input is the *raised error value*, not the input the
    /// `try` was evaluated against — regression test for #158, where the error
    /// was discarded and `catch` ran on the original input.
    #[test]
    fn test_catch_binds_the_error_value() {
        // String payload: the handler sees "boom", not the input {"x":1}.
        query!(br#"{"x":1}"#, "try error(\"boom\") catch .",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "boom");
            }
        );

        // ...and it is a real input, not just a value that prints right.
        query!(br#"{"x":1}"#, r#"try error("boom") catch "c:\(.)""#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "c:boom");
            }
        );

        // Object payload survives as an object, so the handler can index it.
        query!(br#"{"x":1}"#, r#"try error({"a":1}) catch .a"#,
            QueryResult::Owned(v) => {
                assert_eq!(v, OwnedValue::Int(1));
            }
        );

        // A null payload is preserved rather than collapsing to the input.
        query!(br#"{"x":1}"#, "try error(null) catch .",
            QueryResult::Owned(OwnedValue::Null) => {}
        );

        // Bare `error` raises the input, so `catch` sees it round-tripped.
        query!(br#"{"x":1}"#, "try error catch .x",
            QueryResult::Owned(v) => {
                assert_eq!(v, OwnedValue::Int(1));
            }
        );

        // Internal (non-`error`) failures raise their message as a string.
        query!(br"1", "try .foo catch type",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "string");
            }
        );

        // A handler that fans out keeps every output instead of collapsing
        // into a single array.
        query!(br"{}", "try error(\"x\") catch (., .)",
            QueryResult::ManyOwned(vs) => {
                assert_eq!(
                    vs,
                    vec![
                        OwnedValue::String("x".into()),
                        OwnedValue::String("x".into()),
                    ]
                );
            }
        );
    }

    #[test]
    fn test_control_flow_combinations() {
        // if inside try - missing field returns null (no error to catch)
        query!(br#"{"a": true}"#, "try (if .a then .missing else .a end) catch \"error\"",
            QueryResult::One(StandardJson::Null) => {}
        );

        // if inside try with actual error (field access on number)
        query!(br#"{"a": 123}"#, "try (if true then .a.foo else 0 end) catch \"error\"",
            QueryResult::Owned(OwnedValue::String(s)) if s == "error" => {}
        );

        // try inside if - missing field returns null (no error to catch)
        query!(br#"{"a": true}"#, "if .a then try .missing catch 0 else 1 end",
            QueryResult::One(StandardJson::Null) => {}
        );

        // try inside if with actual error
        query!(br#"{"a": 123}"#, "if true then try .a.foo catch 0 else 1 end",
            QueryResult::Owned(
                OwnedValue::Int(0) | OwnedValue::NumberLiteral(NumberRepr::Int(0), _)
            ) => {}
        );

        // Nested if with arithmetic
        query!(br#"{"x": 15}"#, "if .x < 10 then \"small\" elif .x < 20 then \"medium\" else \"large\" end",
            QueryResult::Owned(OwnedValue::String(s)) if s == "medium" => {}
        );
    }

    // Phase 4 tests: Core Builtin Functions

    #[test]
    fn test_builtin_type() {
        query!(br"null", "type",
            QueryResult::Owned(OwnedValue::String(s)) if s == "null" => {}
        );
        query!(br"true", "type",
            QueryResult::Owned(OwnedValue::String(s)) if s == "boolean" => {}
        );
        query!(br"42", "type",
            QueryResult::Owned(OwnedValue::String(s)) if s == "number" => {}
        );
        query!(br#""hello""#, "type",
            QueryResult::Owned(OwnedValue::String(s)) if s == "string" => {}
        );
        query!(br"[1, 2]", "type",
            QueryResult::Owned(OwnedValue::String(s)) if s == "array" => {}
        );
        query!(br#"{"a": 1}"#, "type",
            QueryResult::Owned(OwnedValue::String(s)) if s == "object" => {}
        );
    }

    #[test]
    fn test_builtin_is_type() {
        // isnull
        query!(br"null", "isnull",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"1", "isnull",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // isboolean
        query!(br"true", "isboolean",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"1", "isboolean",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // isnumber
        query!(br"42", "isnumber",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br#""42""#, "isnumber",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // isstring
        query!(br#""hello""#, "isstring",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"42", "isstring",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // isarray
        query!(br"[1, 2]", "isarray",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"{}", "isarray",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // isobject
        query!(br#"{"a": 1}"#, "isobject",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"[]", "isobject",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[test]
    fn test_builtin_length() {
        // null has length 0
        query!(br"null", "length",
            QueryResult::Owned(OwnedValue::Int(0)) => {}
        );

        // string length (characters)
        query!(br#""hello""#, "length",
            QueryResult::Owned(OwnedValue::Int(5)) => {}
        );

        // unicode string length - use escaped UTF-8 for é (c3 a9)
        query!(b"\"h\\u00e9llo\"", "length",
            QueryResult::Owned(OwnedValue::Int(5)) => {}
        );

        // array length
        query!(br"[1, 2, 3]", "length",
            QueryResult::Owned(OwnedValue::Int(3)) => {}
        );

        // object length (key count)
        query!(br#"{"a": 1, "b": 2}"#, "length",
            QueryResult::Owned(OwnedValue::Int(2)) => {}
        );

        // number length is absolute value
        query!(br"-5", "length",
            QueryResult::Owned(OwnedValue::Int(5)) => {}
        );
    }

    #[test]
    fn test_builtin_utf8bytelength() {
        query!(br#""hello""#, "utf8bytelength",
            QueryResult::Owned(OwnedValue::Int(5)) => {}
        );

        // Unicode string - use escaped UTF-8 for é
        query!(b"\"h\\u00e9llo\"", "utf8bytelength",
            QueryResult::Owned(OwnedValue::Int(6)) => {}
        );
    }

    #[test]
    fn test_builtin_keys() {
        // Object keys (sorted)
        query!(br#"{"b": 2, "a": 1, "c": 3}"#, "keys",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 3);
                assert_eq!(arr[0], OwnedValue::String("a".into()));
                assert_eq!(arr[1], OwnedValue::String("b".into()));
                assert_eq!(arr[2], OwnedValue::String("c".into()));
            }
        );

        // Array keys (indices)
        query!(br#"["x", "y", "z"]"#, "keys",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 3);
                assert_eq!(arr[0], OwnedValue::Int(0));
                assert_eq!(arr[1], OwnedValue::Int(1));
                assert_eq!(arr[2], OwnedValue::Int(2));
            }
        );
    }

    #[test]
    fn test_builtin_keys_unsorted() {
        // keys_unsorted preserves original order
        query!(br#"{"b": 2, "a": 1}"#, "keys_unsorted",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 2);
                // Note: Order depends on how JSON was parsed
            }
        );
    }

    /// #1829: `keys`/`keys_unsorted` used to silently drop a decode-failure
    /// key, disagreeing with `length` (which counts every field regardless)
    /// and with `path(.[])`/`tojson` (which already preserve it via its raw
    /// source span, #1642/#1734). Both builtins must now agree: the key is
    /// present, at its raw-source-span spelling.
    #[test]
    fn test_builtin_keys_preserves_decode_failure_key_1829() {
        let doc: &[u8] = b"{\"\xff\xfe\": 1, \"a\": 2}";

        query!(doc, "length",
            QueryResult::Owned(OwnedValue::Int(n)) => assert_eq!(n, 2)
        );
        // The fallback spelling itself is pinned, not just the count: a
        // regression that replaced the decode-failure key with `""`, a
        // placeholder, or an accidental duplicate of `"a"` would still pass
        // a length-2 check alone.
        query!(doc, "keys_unsorted",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(
                    arr,
                    vec![
                        OwnedValue::String("\u{FFFD}\u{FFFD}".to_string()),
                        OwnedValue::String("a".to_string()),
                    ]
                );
            }
        );
        query!(doc, "keys",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(
                    arr,
                    vec![
                        OwnedValue::String("a".to_string()),
                        OwnedValue::String("\u{FFFD}\u{FFFD}".to_string()),
                    ]
                );
            }
        );
    }

    /// #1829's other axis: a structurally non-string/unpaired key (#1194,
    /// `{"a":1,"b"}`) must raise for `keys`/`keys_unsorted` too, matching
    /// `path(.[])`/`tojson` -- previously silently dropped instead (`["a"]`
    /// rather than an error).
    #[test]
    fn test_builtin_keys_raises_on_structurally_malformed_key_1829() {
        let doc: &[u8] = br#"{"a":1,"b"}"#;

        query!(doc, "keys_unsorted",
            QueryResult::Error(e) => {
                assert!(!e.is_decode_failure(), "message: {}", e.message);
            }
        );
        query!(doc, "keys",
            QueryResult::Error(_) => {}
        );
    }

    /// #1829 review: delegating to `DocumentFields::keys()` (`document.rs`)
    /// rather than hand-rolling a narrower walk closes a third axis this
    /// function never explicitly set out to fix -- a malformed `,`/`:`
    /// delimiter (#1677). JSON's semi-index treats the two as interchangeable
    /// gap bytes, so a missing colon leaves an even sibling count and
    /// `ends_unpaired()` alone can't see it; only `key_delimiter_ok`/
    /// `value_delimiter_ok` (both inside `effective_keys`) can. Real jq
    /// rejects this document outright at parse time; succinctly's own CLI
    /// path (`eval_generic.rs`) already raises here too
    /// (`test_nonreserializing_builtins_raise_on_missing_delimiter_1677`) --
    /// this pins the library `eval()` entry point catching up to it for
    /// `keys`/`keys_unsorted` specifically.
    #[test]
    fn test_builtin_keys_raises_on_malformed_delimiter_1677() {
        let doc: &[u8] = br#"{"a" 1, "b": 2}"#;

        query!(doc, "keys_unsorted",
            QueryResult::Error(_) => {}
        );
        query!(doc, "keys",
            QueryResult::Error(_) => {}
        );
    }

    /// Code review, #1829/#1835: the object arm's new error paths (#1194,
    /// #1677) return `QueryResult::Error` directly, with no `optional`
    /// check of their own -- unlike this same function's scalar/array
    /// `_ if optional => QueryResult::None` fallthrough. Not a gap: `keys?`/
    /// `keys_unsorted?` always parses to `Expr::Optional`, whose own
    /// `eval_try` unconditionally catches an ordinary `QueryResult::Error`
    /// (mirrors `builtin_length`'s identical scalar-arm shape, already
    /// established elsewhere in this file). Pinned here since neither
    /// prior #1829 test exercises `?` at all.
    #[test]
    fn test_builtin_keys_optional_suppresses_malformed_key_errors_1829() {
        for expr in ["keys?", "keys_unsorted?"] {
            query!(br#"{"a":1,"b"}"#, expr, QueryResult::None => {});
            query!(br#"{"a" 1, "b": 2}"#, expr, QueryResult::None => {});
        }
    }

    #[test]
    fn test_builtin_has() {
        // Object has key
        query!(br#"{"a": 1, "b": 2}"#, "has(\"a\")",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br#"{"a": 1, "b": 2}"#, "has(\"c\")",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // Array has index
        query!(br"[1, 2, 3]", "has(0)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"[1, 2, 3]", "has(5)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[test]
    fn test_builtin_has_float_and_nan_array_key_909() {
        // #909: the array-index arm used to match only Int, erroring on a
        // Float/NaN key instead of truncating toward zero (matching jq's
        // own `.[1.5]` coercion) or, for NaN, answering `false` -- both via
        // the existing `numeric_key_to_index` helper. Confirmed against jq
        // 1.7.1: `[1,2,3] | has(1.5)` and `has(2.9)` are both `true`
        // (truncate to index 1/2, in bounds); `has(5.5)` is `false` (index
        // 5, out of bounds); `has(nan)` is `false`.
        query!(br"[1, 2, 3]", "has(1.5)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"[1, 2, 3]", "has(2.9)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"[1, 2, 3]", "has(5.5)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        query!(br"[1, 2, 3]", "has(nan)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

