    fn test_builtin_in() {
        // in() checks if a key/index exists
        // Note: in() with piped owned values requires fixing eval_pipe
        // For now, test has() which works similarly
        query!(br#"{"a": 1, "b": 2}"#, "has(\"a\")",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    // `"in({a:1}, {a:9})"` is a jq filter literal, not a formatting string;
    // clippy cannot tell the two apart from the brace shape alone.
    #[allow(clippy::literal_string_with_formatting_args)]
    fn test_builtin_in_fans_out_over_every_xs_output_880() {
        // `in(xs)` = `. as $x | xs | has($x)` (jq 1.7.1) -- a plain pipe, so
        // it forks once per `xs` output rather than only consulting the
        // first (#880's own review discovery, distinct from the
        // Halt/Break-swallowing bug this issue is titled after). Confirmed
        // against jq 1.7.1: `"a" | [in({a:1}, {a:9})]` is `[true,true]`;
        // `"a" | [in({a:1}, {b:2})]` is `[true,false]`.
        assert_eq!(outputs(br#""a""#, "in({a:1}, {a:9})"), ["true", "true"]);
        assert_eq!(outputs(br#""a""#, "in({a:1}, {b:2})"), ["true", "false"]);
    }

    #[test]
    fn test_builtin_in_empty_xs_produces_no_output_880() {
        // `in(empty)` -- `xs` producing zero outputs means `in(xs)` produces
        // zero outputs too (same as any pipe into a filter with nothing to
        // feed it). Confirmed against jq 1.7.1: `"a" | in(empty)` exits 0
        // with no output.
        assert!(outputs(br#""a""#, "in(empty)").is_empty());
    }

    #[test]
    // `"in([1,2,3])"` is a jq filter literal, not a formatting string;
    // clippy cannot tell the two apart from the brace shape alone.
    #[allow(clippy::literal_string_with_formatting_args)]
    fn test_builtin_in_array_index_880() {
        // The array-index arm of `in(xs)` (jq's non-negative-only index
        // semantics, `S::NEGATIVE_INDEX_IN_HAS == false`) alongside the
        // object-key arm exercised by the fan-out test above. Confirmed
        // against jq 1.7.1: `2 | in([1,2,3])` is `true`; `5 | in([1,2,3])`
        // is `false`.
        assert_eq!(outputs(b"2", "in([1,2,3])"), ["true"]);
        assert_eq!(outputs(b"5", "in([1,2,3])"), ["false"]);
    }

    #[test]
    // `"in([1,2,3])"` is a jq filter literal, not a formatting string;
    // clippy cannot tell the two apart from the brace shape alone.
    #[allow(clippy::literal_string_with_formatting_args)]
    fn test_builtin_in_float_and_nan_array_key_909() {
        // #909: `in(xs)`'s array-index arm had the identical Float/NaN gap
        // as `builtin_has`'s (see `test_builtin_has_float_and_nan_array_key_909`).
        // Confirmed against jq 1.7.1: `1.5 | in([1,2,3])` and `2.9 |
        // in([1,2,3])` are both `true`; `5.5 | in([1,2,3])` is `false`;
        // `nan | in([1,2,3])` is `false`.
        assert_eq!(outputs(b"1.5", "in([1,2,3])"), ["true"]);
        assert_eq!(outputs(b"2.9", "in([1,2,3])"), ["true"]);
        assert_eq!(outputs(b"5.5", "in([1,2,3])"), ["false"]);
        // JSON has no NaN literal, so `nan` has to come from the filter's
        // own jq-level constant rather than the input document.
        assert_eq!(outputs(b"null", "nan | in([1,2,3])"), ["false"]);
    }

    #[test]
    // `"in(null)"`/`"in({a:1}, null)"` are jq filter literals, not
    // formatting strings; clippy cannot tell the two apart from the brace
    // shape alone.
    #[allow(clippy::literal_string_with_formatting_args)]
    fn test_builtin_in_null_candidate_is_never_in_anything_908() {
        // Review finding on #908: a null `xs` candidate has no arm of its
        // own, unlike `builtin_has`'s `(StandardJson::Null, _) => false`
        // short-circuit, so it fell into the type-mismatch catch-all and
        // errored instead of contributing `false`. Confirmed against jq
        // 1.7.1: `"a" | in(null)` is `false`; `"a" | in({a:1}, null)` is
        // `true` *and* `false` (the null candidate doesn't truncate the
        // stream); `5 | in(null)` is `false` regardless of key type.
        assert_eq!(outputs(br#""a""#, "in(null)"), ["false"]);
        assert_eq!(outputs(br#""a""#, "in({a:1}, null)"), ["true", "false"]);
        assert_eq!(outputs(b"5", "in(null)"), ["false"]);
    }

    #[test]
    // `"in(5, {a:1})?"` is a jq filter literal, not a formatting string;
    // clippy cannot tell the two apart from the brace shape alone.
    #[allow(clippy::literal_string_with_formatting_args)]
    fn test_builtin_in_optional_with_zero_prior_candidates_880() {
        // Companion to `test_builtin_in_optional_truncates_stream_at_first_type_mismatch_880`:
        // that test suppresses an error after one candidate already
        // succeeded (`results.len() == 1`); this one suppresses an error on
        // the *very first* candidate, so `results` is still empty when the
        // `optional` guard fires. Confirmed against jq 1.7.1: `"a" |
        // in(5, {a:1})?` produces no output at all, exit 0 -- `{a:1}`'s own
        // `true` is never reached (real jq's `try` truncates the stream,
        // it doesn't skip just the erroring candidate).
        assert!(outputs(br#""a""#, "in(5, {a:1})?").is_empty());
    }

    #[test]
    // `"in({a:1}, {b:2}, 5)"` is a jq filter literal, not a formatting
    // string; clippy cannot tell the two apart from the brace shape alone.
    #[allow(clippy::literal_string_with_formatting_args)]
    fn test_builtin_in_optional_with_multiple_prior_candidates_880() {
        // Companion to the two tests above: suppresses an error after *two*
        // candidates already succeeded (`results.len() >= 2`, the
        // `ManyOwned` sub-arm). Confirmed against jq 1.7.1: `"a" |
        // in({a:1}, {b:2}, 5)?` prints `true` and `false` (both already-
        // produced candidates), then stops -- exit 0, no error surfaces.
        assert_eq!(
            outputs(br#""a""#, "in({a:1}, {b:2}, 5)?"),
            ["true", "false"]
        );
    }

    #[test]
    fn test_builtin_select() {
        // select outputs input only if condition is true
        query!(br"5", "select(. > 3)",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 5);
            }
        );

        // select outputs nothing if condition is false, collapsing to a bare
        // `None` since #1043 — `outputs()` is deliberately variant-agnostic
        // about the exact `QueryResult` shape, per its own doc comment.
        assert!(outputs(br"2", "select(. > 3)").is_empty());
    }

    #[test]
    fn test_builtin_select_multi_output_condition_forks() {
        // A multi-output condition republishes the input once per truthy
        // output instead of only consulting the first one (#378). Pinned
        // against jq 1.7.1.
        assert!(outputs(b"1", "select((false,false) and true)").is_empty());
        assert_eq!(outputs(b"1", "select((true,false) and true)"), ["1"]);
        assert_eq!(outputs(b"1", "select((true,true))"), ["1", "1"]);
    }

    #[test]
    fn test_builtin_select_yq_collapses_to_at_most_one_1613() {
        // Real yq's rule is "emit once iff any output is truthy", not jq's
        // "emit once per truthy output" -- an `ADR-0018` rule-2 mode split
        // (`eval_fanout` is shared by `eval_if`/`builtin_select`, but only
        // `select` needs a yq answer: yq's lexer rejects `if/then/else`
        // outright). Every row here is live-verified against yq v4.53.3;
        // jq's own per-bit fanout above must stay exactly as it was.
        assert!(outputs_yq(b"1", "select((false,false))").is_empty());
        assert_eq!(outputs_yq(b"1", "select((true,false))"), ["1"]);
        assert_eq!(outputs_yq(b"1", "select((false,true))"), ["1"]);
        assert_eq!(outputs_yq(b"1", "select((true,true))"), ["1"]);
        assert_eq!(outputs_yq(b"1", "select((true,false,true))"), ["1"]);
        assert_eq!(outputs_yq(b"1", "select((true,true,true))"), ["1"]);
        // Non-literal spelling too (#1613's own acceptance criteria): a
        // literal-only test would not have caught this, since the bug is in
        // how outputs are *counted*, not in how truthiness is computed.
        assert_eq!(outputs_yq(b"1", "select((. == 1, . == 1))"), ["1"]);
        assert!(outputs_yq(b"1", "select((. == 1, . == 2) and false)").is_empty());
    }

    #[test]
    fn test_builtin_select_yq_collapse_still_escapes_after_a_truthy_prefix_1613() {
        // Collapsing to "at most one" only caps the republish *count* -- it
        // doesn't change error/break propagation. `cond` is still walked to
        // completion, so an error after an already-truthy bit still escapes,
        // carrying the (now-capped, one-element) prefix rather than silently
        // discarding it. Live-verified against yq v4.53.3:
        // `select((true, error("boom")))` raises "boom" (not silently
        // dropped) -- the same `Partial`-prefix shape jq's own
        // `select((true, error("x")))` already uses (see `Expr::Builtin
        // (Builtin::Select(cond))`'s doc comment in `resolve_node`).
        yq_query!(br"1", r#"select((true, error("boom")))"#,
            QueryResult::Partial(vs, Control::Error(_)) => {
                assert_eq!(vs, vec![OwnedValue::Int(1)]);
            }
        );
    }

    #[test]
    fn test_builtin_select_yq_collapse_also_applies_through_an_assignment_1613() {
        // `select`'s per-truthy-bit forking is independently reimplemented a
        // *fourth* time in `resolve_node`'s path-tracking `Expr::Builtin
        // (Builtin::Select(cond))` arm (`resolve_cond_fork`, reached by
        // `|=`/`=`/`del()`/`path()`, not `eval_fanout`) -- found live while
        // fixing this issue, not in its original scope. Unpatched, a
        // multi-truthy condition inside `|=` applied the update *once per
        // truthy bit* instead of once: `(.a[] | select((true,true))) |= . +
        // 10` on `[1,2,3]` gave `[21,22,23]` (each element updated twice)
        // where real yq v4.53.3 gives `[11,12,13]`. jq mode is intentionally
        // unaffected -- confirmed live, real jq's own `(.a[] | select((true,
        // true))) |= . + 10` on `[1,2,3]` gives `[21,22,23]`, matching its
        // per-bit `eval_fanout` rule exactly.
        let json: &[u8] = br#"{"a":[1,2,3]}"#;
        let index = JsonIndex::build(json);
        let cursor = index.root(json);
        let expr = parse("(.a[] | select((true,true))) |= . + 10").unwrap();
        let out: Vec<String> = eval::<Vec<u64>, YqSemantics>(&expr, cursor)
            .collect_owned()
            .iter()
            .map(OwnedValue::to_json)
            .collect();
        assert_eq!(out, vec![r#"{"a":[11,12,13]}"#]);
    }

    #[test]
    fn test_builtin_select_jq_assignment_fanout_unchanged_1613() {
        // Companion regression pin for the jq side of the test just above:
        // `resolve_node`'s `Select` arm keeps its pre-existing per-truthy-bit
        // fanout under `JqSemantics`, applying `|=`'s update once per truthy
        // bit. Live-verified against jq 1.7.1.
        assert_outcomes(&[(
            br#"{"a":[1,2,3]}"#,
            "(.a[] | select((true,true))) |= . + 10",
            Ok(r#"{"a":[21,22,23]}"#),
        )]);
    }

    #[test]
    fn test_builtin_select_yq_path_context_arm_collapses_too_1613() {
        // The third of the four independent `select` implementations:
        // `eval_pipe_with_path_context_internal`'s own `Select` arm (not
        // `builtin_select`, though it shares `eval_fanout` with it) — reached
        // whenever `select(...)` sits in a pipe alongside a path-dependent
        // builtin like `key`/`parent`/`file_index` (`needs_path_context`),
        // not only under `--eval-all`. Unlike the other three sites, this one
        // had no dedicated regression test before -- found during this
        // issue's own review. Live-verified against yq v4.53.3:
        // `.[] | select((true,true)) | key` on `{"a":1,"b":2}` gives
        // `["a","b"]`, not `["a","a","b","b"]`.
        assert_eq!(
            outputs_yq(br#"{"a":1,"b":2}"#, "[.[] | select((true,true)) | key]"),
            [r#"["a","b"]"#]
        );
    }

    #[test]
    fn test_builtin_select_jq_path_context_arm_fanout_unchanged_1613() {
        // Companion pin for the jq side of the test just above, at the same
        // site. `key` isn't a real jq builtin (a succinctly position-based
        // navigation extension), so there's no oracle to diff against here —
        // this pins succinctly jq's own existing behavior rather than
        // verifying fidelity, confirming `select_emits::<JqSemantics>` still
        // republishes once per truthy bit at this third site too.
        assert_eq!(
            outputs(br#"{"a":1,"b":2}"#, "[.[] | select((true,true)) | key]"),
            [r#"["a","a","b","b"]"#]
        );
    }

    #[test]
    fn test_builtin_empty() {
        query!(br"1", "empty",
            QueryResult::None => {}
        );
    }

    #[test]
    fn test_builtin_map() {
        // map applies function to each element
        query!(br"[1, 2, 3]", "map(. * 2)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 3);
                assert_eq!(arr[0], OwnedValue::Int(2));
                assert_eq!(arr[1], OwnedValue::Int(4));
                assert_eq!(arr[2], OwnedValue::Int(6));
            }
        );

        // map with type check
        query!(br"[1, 2, 3]", "map(. + 1)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr[0], OwnedValue::Int(2));
            }
        );

        // map(f) is [.[] | f], and .[] over an object iterates its values,
        // so jq accepts an object of entries as readily as an array (#422).
        query!(br#"{"a": 1, "b": 2}"#, "map(. + 1)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![OwnedValue::Int(2), OwnedValue::Int(3)]);
            }
        );
        query!(br"{}", "map(. + 1)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert!(arr.is_empty());
            }
        );
    }

    #[test]
    fn test_builtin_map_values() {
        // map_values on object
        query!(br#"{"a": 1, "b": 2}"#, "map_values(. * 10)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("a"), Some(&OwnedValue::Int(10)));
                assert_eq!(obj.get("b"), Some(&OwnedValue::Int(20)));
            }
        );

        // map_values on array
        query!(br"[1, 2, 3]", "map_values(. + 1)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr[0], OwnedValue::Int(2));
                assert_eq!(arr[1], OwnedValue::Int(3));
                assert_eq!(arr[2], OwnedValue::Int(4));
            }
        );
    }

    /// #1829: `map_values` used to silently drop a decode-failure or #1194
    /// structurally malformed key, disagreeing with `length`/`keys`/
    /// `to_entries` (fixed in #1835/#1848). `resolve_display_key`/
    /// `DisplayKeyGuard`, not plain `key_display_string`: `map_values`
    /// builds a real `IndexMap`, unlike `keys`/`to_entries`'s `Vec` output.
    #[test]
    fn test_builtin_map_values_preserves_decode_failure_key_1829() {
        let doc: &[u8] = b"{\"\xff\xfe\": 1, \"a\": 2}";

        query!(doc, "length",
            QueryResult::Owned(OwnedValue::Int(n)) => assert_eq!(n, 2)
        );
        query!(doc, "map_values(.+1)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.len(), 2);
                assert_eq!(
                    obj.get("\u{FFFD}\u{FFFD}"),
                    Some(&OwnedValue::Int(2))
                );
                assert_eq!(obj.get("a"), Some(&OwnedValue::Int(3)));
            }
        );
    }

    /// #1829's other axis: a structurally non-string/unpaired key (#1194,
    /// `{"a":1,"b"}`) must raise for `map_values` too, matching
    /// `keys`/`to_entries`/`path(.[])`/`tojson` -- previously silently
    /// dropped instead (a 1-entry object, not an error).
    #[test]
    fn test_builtin_map_values_raises_on_structurally_malformed_key_1829() {
        query!(br#"{"a":1,"b"}"#, "map_values(.+1)",
            QueryResult::Error(_) => {}
        );
    }

    /// #1677: a malformed `,`/`:` delimiter now raises for `map_values` too,
    /// on both the object and array arms -- the array arm's own gap mirrors
    /// the one `to_entries`'s array arm had before its own #1677 fix
    /// (#1848).
    #[test]
    fn test_builtin_map_values_raises_on_malformed_delimiter_1677() {
        query!(br#"{"a" 1, "b": 2}"#, "map_values(.+1)",
            QueryResult::Error(_) => {}
        );
        query!(br"[1 2, 3]", "map_values(.+1)",
            QueryResult::Error(_) => {}
        );
        // Positive control: a well-formed array is unaffected.
        query!(br"[1, 2, 3]", "map_values(.+1)",
            QueryResult::Owned(OwnedValue::Array(arr)) => assert_eq!(arr.len(), 3)
        );
    }

    /// Code review precedent from #1835/#1848/#1829: `map_values?` must
    /// still suppress both error axes via the outer `Expr::Optional` catch.
    #[test]
    fn test_builtin_map_values_optional_suppresses_malformed_key_errors_1829() {
        query!(br#"{"a":1,"b"}"#, "map_values(.+1)?", QueryResult::None => {});
        query!(br#"{"a" 1, "b": 2}"#, "map_values(.+1)?", QueryResult::None => {});
        query!(br"[1 2, 3]", "map_values(.+1)?", QueryResult::None => {});
    }

    /// Code review, #1829: a duplicate object key must be collapsed to its
    /// last occurrence *before* `f` runs, matching real jq -- an earlier
    /// draft of this fix hardcoded `collapse: false` (correct for
    /// `keys`/`to_entries`, which lack an `S: EvalSemantics` parameter to
    /// derive a mode-correct flag from, but `map_values` has one) and so
    /// walked every raw duplicate, applying `f` to a value real jq would
    /// have already discarded. `"x" + 1` would raise here if the collapse
    /// didn't happen before `f` ran; real jq (`{"a":"x","a":2} |
    /// map_values(.+1)`, confirmed live) gives `{"a":3}`, never evaluating
    /// `f` against `"x"` at all.
    #[test]
    fn test_builtin_map_values_collapses_duplicate_key_before_evaluating_f_1829() {
        query!(br#"{"a": "x", "a": 2}"#, "map_values(.+1)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.len(), 1);
                assert_eq!(obj.get("a"), Some(&OwnedValue::Int(3)));
            }
        );
    }

    /// Code review, #1829: two decode-failure keys that lossy-decode to the
    /// identical #1642 fallback spelling must raise via `DisplayKeyGuard`
    /// (the reason a key-resolution + collision-guard pair was chosen over
    /// plain `key_display_string` for this function) once both survive `f`
    /// and would genuinely land in `result_map` together.
    #[test]
    fn test_builtin_map_values_raises_on_colliding_fallback_keys_1829() {
        // `\xff\xfe` and `\xff\xfd` are both 2-byte invalid UTF-8 sequences
        // that lossy-decode to the same fallback, `"\u{FFFD}\u{FFFD}"`.
        let doc: &[u8] = b"{\"\xff\xfe\": 1, \"\xff\xfd\": 2}";
        query!(doc, "map_values(.+1)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("ambiguous"), "message: {}", e.message);
            }
        );
    }

    /// Code review, #1829: the collision guard's check must be deferred
    /// until a field's own `f`-output is known to actually land in
    /// `result_map` -- checking (and registering the key in the guard)
    /// eagerly, before `f` runs, previously raised a false-positive
    /// collision even when the earlier field's own value was filtered out
    /// by `select` and never inserted at all. The two keys here share the
    /// same #1642 fallback spelling as the collision test above, but only
    /// one field's value survives `select(. > 0)`, so this must succeed
    /// with a single entry, not raise.
    #[test]
    fn test_builtin_map_values_no_false_positive_collision_when_value_dropped_1829() {
        let doc: &[u8] = b"{\"\xff\xfe\": 1, \"\xff\xfd\": -1}";
        query!(doc, "map_values(select(.>0))",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.len(), 1);
                assert_eq!(obj.get("\u{FFFD}\u{FFFD}"), Some(&OwnedValue::Int(1)));
            }
        );
    }

    /// Code review, #1829: `S::COLLAPSE_DUPLICATE_KEYS` makes the
    /// `effective_fields_checked` call mode-dependent -- jq mode collapses a
    /// duplicate key before `f` runs (pinned above), yq mode does not, so
    /// both occurrences reach `f` and the second's result overwrites the
    /// first's in `result_map` (`IndexMap`'s own last-write-wins insert),
    /// matching yq's own last-key-wins convention. Neither prior test nor
    /// the pre-existing `map_values` coverage exercises this branch under
    /// `YqSemantics` at all.
    #[test]
    fn test_builtin_map_values_yq_mode_does_not_collapse_duplicate_key_1829() {
        yq_query!(br#"{"a": 10, "a": 2}"#, "map_values(.+1)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.len(), 1);
                assert_eq!(obj.get("a"), Some(&OwnedValue::Int(3)));
            }
        );
    }

    #[test]
    fn test_builtin_add() {
        // Add numbers
        query!(br"[1, 2, 3]", "add",
            QueryResult::Owned(OwnedValue::Int(6)) => {}
        );

        // Add strings
        query!(br#"["a", "b", "c"]"#, "add",
            QueryResult::Owned(OwnedValue::String(s)) if s == "abc" => {}
        );

        // Add arrays
        query!(br"[[1], [2], [3]]", "add",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 3);
            }
        );

        // Empty array returns null
        query!(br"[]", "add",
            QueryResult::Owned(OwnedValue::Null) => {}
        );

        // add is [.[] | .] folded with +, and .[] over an object iterates
        // its values, so jq accepts an object here as readily as an array
        // (#422).
        query!(br#"{"a": 1, "b": 2, "c": 3}"#, "add",
            QueryResult::Owned(OwnedValue::Int(6)) => {}
        );
        query!(br"{}", "add",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
    }

    #[test]
    fn test_builtin_any() {
        query!(br"[true, false]", "any",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"[false, false]", "any",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        query!(br"[null, null]", "any",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        query!(br"[1, 0]", "any",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}  // numbers are truthy
        );

        // any is [.[] | .] with an early-exit truthiness check, and .[] over
        // an object iterates its values, so jq accepts an object here as
        // readily as an array (#422).
        query!(br#"{"a": false, "b": true}"#, "any",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"{}", "any",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    /// #1494: `builtin_any`/`builtin_all`/`builtin_flatten`/`builtin_from_entries`
    /// (plus `set_path`/`set_path_steps`, exercised separately by
    /// `test_set_path_cannot_iterate_uses_the_real_mode_tag_1494`) used the
    /// jq-pinned `EvalError::cannot_iterate` shim unconditionally, so a
    /// yq-mode error message always carried jq's own value-preview
    /// convention regardless of the real evaluation mode. Threaded `S:
    /// EvalSemantics` through instead, matching the 19 call sites #1055
    /// already migrated.
    ///
    /// jq mode's own assertion below is unaffected by #1901 (still exactly
    /// what #1494 fixed): `(1.0 + 2.0)` is a *computed* float
    /// (`OwnedValue::Float(3.0)`, not a source-literal-preserving
    /// `NumberLiteral`), which is exactly where jq's error-message
    /// convention (a computed whole-number float spells without a decimal
    /// point, "3", matching `1.0 + 2.0 | tostring` in real jq) and
    /// yq/plain-JSON's convention (keeps it, "3.0" -- confirmed against
    /// `stream_owned_value_json_jq`'s own dedicated unit test
    /// `test_stream_json_jq_convention_keeps_shortest_float`) provably
    /// diverge.
    ///
    /// #1901 revision: these four builtins' *yq-mode* assertion no longer
    /// belongs here -- #1901 found real yq doesn't use jq's
    /// "Cannot iterate over `<type>` (`<value>`)" template at all for these
    /// four (its own wording carries no value preview, so this test's
    /// original "3.0 vs 3" distinction is structurally moot for them now).
    /// #1494's yq-mode concern (does `S::TAG` genuinely reach
    /// `cannot_iterate_with` as `EvalTag::Yq`) remains covered by
    /// `test_set_path_cannot_iterate_uses_the_real_mode_tag_1494`, whose
    /// call sites #1901 didn't touch. This test now just pins that none of
    /// these four leak jq's template into yq mode any more.
    #[test]
    fn test_cannot_iterate_call_sites_use_the_real_mode_tag_1494() {
        for (expr, want_yq) in [
            ("any", "any only supports arrays, was !!float"),
            ("all", "all only supports arrays, was !!float"),
            ("flatten", "only arrays are supported for flatten"),
            ("from_entries", "from entries only runs against arrays"),
        ] {
            let filter = format!("(1.0 + 2.0) | {expr}");
            // #1901 revision: an exact match on real yq's own wording
            // (confirmed live against v4.53.3), not merely the absence of
            // jq's old template -- the weaker `!contains("Cannot iterate")`
            // form this replaced would pass just as well for any other
            // wrong string (#1901 review).
            yq_query!(br"null", &filter,
                QueryResult::Error(e) => {
                    assert_eq!(
                        e.message, want_yq,
                        "{filter}: yq mode must use real yq's own wording (#1901)"
                    );
                }
            );
            query!(br"null", &filter,
                QueryResult::Error(e) => {
                    assert_eq!(
                        e.message, "Cannot iterate over number (3)",
                        "{filter}: jq mode must be unchanged from before this fix"
                    );
                }
            );
        }
    }

    /// #1901 review: `builtin_any`/`builtin_all`'s new yq-mode rejection arm
    /// used to sit *after* the pre-existing `_ if optional => QueryResult::None`
    /// wildcard, so it (and the decode-failure check inside `scalar_fallback`)
    /// was unreachable whenever `optional` was `true` -- an undecodable
    /// scalar under `any?`/`all?` in yq mode would silently return `None`
    /// instead of raising, unlike the other five #1901-fixed builtins
    /// (flatten/group_by/unique/unique_by/from_entries), none of which have
    /// this preceding wildcard arm. Confirmed live via mutation testing
    /// during review; fixed by reordering the arms so the yq-mode check runs
    /// first, matching the other five.
    #[test]
    fn test_any_all_respect_decode_failure_before_optional_in_yq_mode_1901() {
        // A lone-byte string token the JSON semi-index accepts as a span but
        // whose bytes are not valid UTF-8.
        let json: &[u8] = b"\"\xff\xfe\"";
        for expr in ["any?", "all?"] {
            yq_query!(json, expr,
                QueryResult::Error(e) if e.is_decode_failure() => {
                    assert!(
                        e.message.contains("invalid UTF-8"),
                        "{expr}: message: {}",
                        e.message
                    );
                }
            );
        }
    }

    #[test]
    fn test_builtin_all() {
        query!(br"[true, true]", "all",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"[true, false]", "all",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        query!(br"[1, 2, 3]", "all",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}  // numbers are truthy
        );

        // Same shape as `any` — see #422.
        query!(br#"{"a": true, "b": false}"#, "all",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        query!(br"{}", "all",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn test_builtin_any_f() {
        // any(cond) is any(.[]; cond) - iterate the container, test cond.
        query!(br"[1, 2, 3]", "any(. > 2)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"[1, 2, 3]", "any(. > 5)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        // .[] over an object iterates its values (#422).
        query!(br#"{"a": false, "b": true}"#, "any(.)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        // `?` on a non-iterable input swallows the "cannot iterate" error.
        query!(br"1", "any(. > 0)?",
            QueryResult::None => {}
        );
    }

    #[test]
    fn test_builtin_all_f() {
        query!(br"[1, 2, 3]", "all(. > 0)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(br"[1, 2, 3]", "all(. > 1)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        query!(br#"{"a": true, "b": false}"#, "all(.)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        query!(br"1", "all(. > 0)?",
            QueryResult::None => {}
        );
    }

    #[test]
    fn test_builtin_any_cond() {
        // The generator ignores `.` entirely, matching jq's own idiom of
        // driving any/all off an explicit generator rather than the input.
        query!(b"null", "any(1,2,3; . > 2)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(b"null", "any(1,2,3; . > 5)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // Short-circuit past a trailing error: a match at `2` means `error`
        // (the generator's third output) is never reached (verified against
        // jq 1.7.1).
        query!(b"null", r#"any(1,2,error("boom"); . > 1)"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        // No match precedes the error, so it surfaces.
        query!(b"null", r#"any(1,2,error("boom"); . > 5)"#,
            QueryResult::Error(e) => assert_eq!(e.message, "boom")
        );

        // Per-element short-circuit: `cond` itself yields a truthy output
        // before erroring on the very same generator element - the match
        // still wins over that trailing error (verified against jq 1.7.1).
        query!(b"null", r#"any(1,2,3; (true, error("nope")))"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn test_builtin_all_cond() {
        query!(b"null", "all(1,2,3; . > 0)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
        query!(b"null", "all(1,2,3; . > 1)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // No falsy element precedes the error, so `all` cannot conclude
        // early and the error surfaces (verified against jq 1.7.1) - unlike
        // `any` above, `all` only short-circuits on a *falsy* match.
        query!(b"null", r#"all(1,2,error("boom"); . > 0)"#,
            QueryResult::Error(e) => assert_eq!(e.message, "boom")
        );

        // Per-element short-circuit: `cond` yields a falsy output before
        // erroring on the same generator element (verified against jq
        // 1.7.1).
        query!(b"null", r#"all(1,2,3; (false, error("nope")))"#,
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

