    #[test]
    fn test_builtin_ltrimstr() {
        query!(br#""hello world""#, r#"ltrimstr("hello ")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "world");
            }
        );

        // No match - returns original
        query!(br#""hello world""#, r#"ltrimstr("goodbye")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "hello world");
            }
        );

        // jq's ltrimstr is total: non-string argument leaves input unchanged (#394)
        query!(br#""abc""#, "ltrimstr(1)",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "abc");
            }
        );

        // jq's ltrimstr is total: non-string input passes through unchanged (#394).
        // A document-sourced number materializes as NumberLiteral, not Int (#387).
        query!(b"1", r#"ltrimstr("a")"#,
            QueryResult::Owned(OwnedValue::NumberLiteral(NumberRepr::Int(n), _)) => {
                assert_eq!(n, 1);
            }
        );

        // Prefix equal to the whole string trims to the empty string.
        query!(br#""foobar""#, r#"ltrimstr("foobar")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "");
            }
        );

        // #1538 review: a pattern strictly longer than the input must not
        // panic (`cow[pattern.len()..]` would be out of bounds) -- it's
        // simply not a prefix, so the input passes through unchanged.
        query!(br#""ab""#, r#"ltrimstr("abcdef")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "ab");
            }
        );
    }

    #[test]
    fn test_builtin_rtrimstr() {
        query!(br#""hello world""#, r#"rtrimstr(" world")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "hello");
            }
        );

        // No match - returns original
        query!(br#""hello world""#, r#"rtrimstr("goodbye")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "hello world");
            }
        );

        // jq's rtrimstr is total: non-string argument leaves input unchanged (#394)
        query!(br#""abc""#, "rtrimstr(null)",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "abc");
            }
        );

        // jq's rtrimstr is total: non-string input passes through unchanged (#394).
        // A document-sourced number materializes as NumberLiteral, not Int (#387).
        query!(b"1", r#"rtrimstr("a")"#,
            QueryResult::Owned(OwnedValue::NumberLiteral(NumberRepr::Int(n), _)) => {
                assert_eq!(n, 1);
            }
        );

        // Suffix equal to the whole string trims to the empty string.
        query!(br#""foobar""#, r#"rtrimstr("foobar")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "");
            }
        );

        // #1538 review: a pattern strictly longer than the input must not
        // panic (`cow.len() - pattern.len()` would underflow) -- it's
        // simply not a suffix, so the input passes through unchanged.
        query!(br#""ab""#, r#"rtrimstr("abcdef")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "ab");
            }
        );
    }

    #[test]
    fn test_builtin_startswith() {
        query!(br#""hello world""#, r#"startswith("hello")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        query!(br#""hello world""#, r#"startswith("world")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );

        // Substring that isn't a prefix is still false.
        query!(br#""foobar""#, r#"startswith("oob")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );

        // Unlike ltrimstr/rtrimstr, startswith is not total: a non-string
        // argument errors.
        query!(br#""abc""#, "startswith(1)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "startswith() requires string inputs");
            }
        );

        // A non-string input errors too.
        query!(b"1", r#"startswith("a")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "startswith() requires string inputs");
            }
        );
    }

