    /// #1073: real yq (confirmed live against v4.53.3) only ever accepts a
    /// *string* for `@sh` -- every other type errors, not just array/object
    /// (`5 | @sh`, `1.5 | @sh`, `true | @sh`, and `null | @sh` all error the
    /// same way in real yq). jq's own, far more permissive rules (numbers/
    /// bools/null convert to strings, arrays quote each element --
    /// `test_format_sh_multibyte_boundary_647`'s array case above) stay
    /// jq-only after this fix. The pre-existing object error (#929) already
    /// applied under both modes.
    #[test]
    fn test_format_sh_yq_mode_only_accepts_strings() {
        yq_query!(br"[1, 2, 3]", "@sh",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "array ([1,2,3]) can not be escaped for shell");
            }
        );

        // Nested/mixed-content arrays error the same way -- yq's own rule
        // doesn't inspect elements, unlike jq's per-element quoting.
        yq_query!(br#"[[1, 2], "x", null]"#, "@sh",
            QueryResult::Error(e) => {
                assert!(e.message.starts_with("array ("), "{}", e.message);
                assert!(e.message.ends_with("can not be escaped for shell"), "{}", e.message);
            }
        );

        // Every scalar type errors too -- not just containers.
        yq_query!(br"5", "@sh",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (5) can not be escaped for shell");
            }
        );
        yq_query!(br"1.5", "@sh",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (1.5) can not be escaped for shell");
            }
        );
        yq_query!(br"true", "@sh",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "boolean (true) can not be escaped for shell");
            }
        );
        yq_query!(br"null", "@sh",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "null (null) can not be escaped for shell");
            }
        );

        // A string is still the one accepted type.
        yq_query!(br#""hello""#, "@sh",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "'hello'");
            }
        );
    }

    #[test]
    fn test_format_yaml() {
        // Simple object
        query!(br#"{"a": 1, "b": 2}"#, "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "{a: 1, b: 2}");
            }
        );

        // Array
        query!(br"[1, 2, 3]", "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "[1, 2, 3]");
            }
        );

        // Nested structure
        query!(br#"{"name": "test", "items": [1, 2]}"#, "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "{name: test, items: [1, 2]}");
            }
        );

        // String that needs quoting (reserved word)
        query!(br#"{"value": "true"}"#, "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "{value: \"true\"}");
            }
        );

        // Null and boolean
        query!(br#"{"flag": true, "nothing": null}"#, "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "{flag: true, nothing: null}");
            }
        );

        // Empty containers
        query!(br"[]", "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "[]");
            }
        );

        query!(br"{}", "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "{}");
            }
        );

        // Float values
        query!(br"3.14", "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "3.14");
            }
        );

        // #1064: NaN/Infinity spell YAML-native, not jq's bare NaN/inf.
        query!(br"null", "nan | @yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, ".nan");
            }
        );
        query!(br"null", "infinite | @yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, ".inf");
            }
        );
        query!(br"null", "-infinite | @yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "-.inf");
            }
        );

        // Same, but for a *document-sourced* NumberLiteral (an exponent
        // overflowing to +/-infinity), not a computed Float -- a separate
        // match arm in owned_to_yaml_at_depth.
        query!(br"1e400", "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, ".inf");
            }
        );
        query!(br"-1e400", "@yaml",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "-.inf");
            }
        );
    }

    #[test]
    fn test_format_props() {
        // Simple object
        query!(br#"{"database": "postgres", "port": 5432}"#, "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "database = postgres\nport = 5432");
            }
        );

        // Nested object
        query!(br#"{"nested": {"a": 1, "b": 2}, "top": "value"}"#, "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "nested.a = 1\nnested.b = 2\ntop = value");
            }
        );

        // Array
        query!(br#"{"arr": [1, 2, 3]}"#, "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "arr.0 = 1\narr.1 = 2\narr.2 = 3");
            }
        );

        // Deeply nested
        query!(br#"{"a": {"b": {"c": 42}}}"#, "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "a.b.c = 42");
            }
        );

        // Top-level scalar
        query!(br#""just a string""#, "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "just a string");
            }
        );

        // Null
        query!(br"null", "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "null");
            }
        );

        // Boolean values
        query!(br#"{"enabled": true, "disabled": false}"#, "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "enabled = true\ndisabled = false");
            }
        );

        // Special characters in values (preserved)
        query!(br#"{"key": "value=with=equals"}"#, "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "key = value=with=equals");
            }
        );

        // Empty object
        query!(br"{}", "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "");
            }
        );

        // Top-level array
        query!(br"[1, 2, 3]", "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "0 = 1\n1 = 2\n2 = 3");
            }
        );

        // #1064: NaN/Infinity spell YAML-native, not jq's bare NaN/inf.
        query!(br"null", "nan | @props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, ".nan");
            }
        );
        query!(br"null", "infinite | @props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, ".inf");
            }
        );
        query!(br"null", "-infinite | @props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "-.inf");
            }
        );

        // Same, but for a *document-sourced* NumberLiteral (an exponent
        // overflowing to +/-infinity), not a computed Float -- a separate
        // match arm in props_value_to_string.
        query!(br"1e400", "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, ".inf");
            }
        );
        query!(br"-1e400", "@props",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "-.inf");
            }
        );
    }

    /// #1755: `eval_format` -- the single materialization point every
    /// `@format` function shares -- used unchecked `to_owned_lossy`, so an
    /// undecodable string silently formatted as if it were `""` instead of
    /// raising. Covers a representative format from each of `format_owned`'s
    /// dispatch arms: a plain stringifier (`@text`), a serializer (`@json`),
    /// a byte-transform (`@base64`), a percent-encoder (`@uri`), and a
    /// row-formatter (`@csv`) -- both on the malformed value directly and
    /// nested inside a container, since `@json`/`@csv`/etc. recurse into
    /// containers via `to_owned`'s own (already-fixed) recursion.
    #[test]
    fn test_format_raises_on_decode_failure_1755() {
        for expr in ["@text", "@json", "@base64", "@uri", "@csv", "@sh", "@html"] {
            query!(
                &b"[1, \"\xff\xfe\"]"[..],
                expr,
                QueryResult::Error(e) if e.is_decode_failure() => {
                    assert!(
                        e.message.contains("invalid UTF-8"),
                        "expr={expr} message: {}",
                        e.message
                    );
                }
            );
        }
    }

    /// #1755 positive control: valid data through each of `eval_format`'s
    /// dispatch arms is unaffected by routing through `to_owned`.
    #[test]
    fn test_format_valid_data_unaffected_1755() {
        query!(br#""hi""#, "@text",
            QueryResult::Owned(OwnedValue::String(s)) => { assert_eq!(s, "hi"); }
        );
        query!(br"[1,2]", "@json",
            QueryResult::Owned(OwnedValue::String(s)) => { assert_eq!(s, "[1,2]"); }
        );
        query!(br#""hi""#, "@base64",
            QueryResult::Owned(OwnedValue::String(s)) => { assert_eq!(s, "aGk="); }
        );
        query!(br#""hi""#, "@uri",
            QueryResult::Owned(OwnedValue::String(s)) => { assert_eq!(s, "hi"); }
        );
    }

    /// #1755: `eval_format`'s `to_owned` runs *before* any
    /// format-specific type/shape check, so a decode failure now preempts
    /// an error that would have fired regardless of the string's content
    /// (`@csv` on an object always errors; yq's `@uri`/`@base64`/`@html`
    /// always reject a container) -- matching the established rule that a
    /// decode failure is never suppressed, here extended to "never
    /// outranked by an unrelated type error" (`scalar_decode_failure`'s
    /// own doc comment states the same precedence for the sort family).
    /// Pinned in both modes since `format_owned`'s yq-specific container
    /// rejection (`stringify_for_format`) is the one dispatch arm that
    /// could plausibly have raced with this ordering.
    ///
    /// Restored after PR #1797's merge silently dropped this test (the
    /// merge commit was byte-identical to the PR's first commit only,
    /// despite the PR's actual, all-green HEAD having two commits) --
    /// see the `merge-queue-squash-drops-later-commit` memory note.
    #[test]
    fn test_format_decode_failure_outranks_shape_error_1755() {
        // jq: `{"a": ...} | @csv` always errors -- @csv never accepts an
        // object, content aside. With a decode failure inside it, that
        // decode failure now fires first, not the "not both arrays" shape
        // error.
        query!(
            &b"{\"a\": \"\xff\xfe\"}"[..],
            "@csv",
            QueryResult::Error(e) if e.is_decode_failure() => {}
        );

        // yq: `[...] | @uri` on a container always errors (yq rejects
        // encoding a !!seq as URI outright, real-yq-verified per #1096's
        // own divergence note) -- with a decode failure inside it, that
        // decode failure now fires first, not yq's container-rejection
        // type error.
        yq_query!(
            &b"[\"\xff\xfe\"]"[..],
            "@uri",
            QueryResult::Error(e) if e.is_decode_failure() => {}
        );
    }

