    #[test]
    fn test_builtin_explode() {
        query!(br#""abc""#, "explode",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 3);
                assert_eq!(arr[0], OwnedValue::Int(97));  // 'a'
                assert_eq!(arr[1], OwnedValue::Int(98));  // 'b'
                assert_eq!(arr[2], OwnedValue::Int(99));  // 'c'
            }
        );
    }

    #[test]
    fn test_builtin_explode_round_trips_max_valid_codepoint() {
        query!("[\"\u{10FFFF}\"]".as_bytes(), ".[0] | explode",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![OwnedValue::Int(1114111)]);
            }
        );
    }

    #[test]
    fn test_builtin_implode() {
        query!(br"[97, 98, 99]", "implode",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "abc");
            }
        );
    }

    /// jq.test's codepoint boundary table (surrogates, max valid codepoint,
    /// overflow, fractional truncation) — see issue #706. Every expected
    /// value below is captured from live jq 1.7.1, not derived.
    #[test]
    fn test_builtin_implode_boundary_table() {
        for (codepoint, expected) in [
            ("-1", "\u{FFFD}"), // negative -> replacement char
            // large-magnitude negative: wraps to a spuriously "valid" low
            // codepoint (100) under a naive `as u32` cast -- must still
            // replace, not silently produce U+0064 ('d'). See #738.
            ("-4294967196", "\u{FFFD}"),
            ("0", "\u{0}"),
            ("1", "\u{1}"),
            ("2", "\u{2}"),
            ("3", "\u{3}"),
            ("1114111", "\u{10FFFF}"), // max valid codepoint: round-trips
            ("1114112", "\u{FFFD}"),   // one past max -> replacement char
            ("55295", "\u{D7FF}"),     // just below surrogate range: valid
            ("55296", "\u{FFFD}"),     // low surrogate boundary -> replacement char
            ("57343", "\u{FFFD}"),     // high surrogate boundary -> replacement char
            ("57344", "\u{E000}"),     // just above surrogate range: valid
            ("1.1", "\u{1}"),          // fractional codepoints truncate
            ("1.9", "\u{1}"),
        ] {
            let json = format!("[{codepoint}]");
            query!(json.as_bytes(), "implode",
                QueryResult::Owned(OwnedValue::String(s)) => {
                    assert_eq!(s, expected, "implode([{codepoint}])");
                }
            );
        }

        // The full table round-tripped through one call, matching jq.test's
        // single-array-literal shape and jq 1.7.1's exact output.
        query!(
            br"[-1, 0, 1, 2, 3, 1114111, 1114112, 55295, 55296, 57343, 57344, 1.1, 1.9]",
            "implode",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(
                    s,
                    "\u{FFFD}\u{0}\u{1}\u{2}\u{3}\u{10FFFF}\u{FFFD}\u{D7FF}\u{FFFD}\u{FFFD}\u{E000}\u{1}\u{1}"
                );
            }
        );
    }

    /// implode's error messages are type-specific per invalid element, not a
    /// generic "invalid codepoint" — see issue #706.
    #[test]
    fn test_builtin_implode_element_errors() {
        for (json, filter, message) in [
            (&br"1"[..], "implode", "implode input must be an array"),
            (
                &br#"["a", 98, 99]"#[..],
                "implode",
                r#"string ("a") can't be imploded, unicode codepoint needs to be numeric"#,
            ),
            (
                &br"null"[..],
                "[97, nan] | implode",
                "number (null) can't be imploded, unicode codepoint needs to be numeric",
            ),
        ] {
            query!(json, filter,
                QueryResult::Error(e) => assert_eq!(e.message, message, "{filter}")
            );
        }
    }

    /// `implode?` on an array with an invalid element backtracks to no
    /// output at all, not a partial string built from the valid elements —
    /// live-verified against jq 1.7.1 (`echo '["a",98,99]' | jq 'implode?'`
    /// prints nothing).
    #[test]
    fn test_builtin_implode_optional_suppresses_whole_result() {
        query!(br#"["a", 98, 99]"#, "implode?",
            QueryResult::None => {}
        );
    }

    #[test]
    fn test_builtin_test() {
        query!(br#""hello world""#, r#"test("world")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        query!(br#""hello world""#, r#"test("xyz")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );
    }

    /// #956 (#943 follow-up): the non-regex `builtin_test` fallback (only
    /// reachable with `regex` compiled out) unpacks a non-empty array
    /// pattern the same way the regex-enabled path does, ignoring the
    /// flags element entirely (this fallback has no flag support at all).
    /// Confirmed against jq 1.7.1 (regex-enabled succinctly matches it
    /// too): `"abc" | test(["a","i"])` is `true`.
    #[test]
    #[cfg(not(feature = "regex"))]
    fn test_builtin_test_unpacks_bare_array_pattern_956() {
        query!(br#""abc""#, r#"test(["a","i"])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
        // Extra elements past index 1 are silently ignored, same as #943's
        // regex-enabled behavior.
        query!(br#""abc""#, r#"test(["a","i","x"])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
        // A 1-element array (no flags slot at all) still unpacks.
        query!(br#""abc""#, r#"test(["a"])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
        // A non-matching pattern still returns false, not an error.
        query!(br#""abc""#, r#"test(["z"])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );
        // A non-string unpacked pattern reports the array-unpacked wording,
        // matching #943's regex-enabled precedent.
        query!(br#""abc""#, r#"test([1,"i"])"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (1) is not a string");
            }
        );
        // A genuinely empty array falls through to the plain
        // non-string-pattern check, using the array's own type name.
        query!(br#""abc""#, r"test([])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "array not a string or array");
            }
        );
        // `optional` (`?`) suppresses an array-unpacked pattern error too,
        // same as it already did for a plain non-string/array pattern.
        query!(br#""abc""#, r#"test([1,"i"])?"#,
            QueryResult::None => {}
        );
        // Review round: a validly-typed pattern with a malformed *flags*
        // slot must still error, not silently discard the bad flags value
        // and succeed -- confirmed against jq 1.7.1 and the regex-enabled
        // path: `"abc" | test(["a", 5])` raises "number (5) is not a
        // string" in both. This fallback still has no flag support at all
        // once validated (a *valid* flags string can't change the outcome
        // -- see the first case above), but validation itself must agree.
        query!(br#""abc""#, r#"test(["a", 5])"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (5) is not a string");
            }
        );
        // `null` flags is valid (treated as "no flags"), matching the
        // regex-enabled path.
        query!(br#""abc""#, r#"test(["a", null])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
    }

    /// #929: `EvalError::type_error` is documented as reserved for sites
    /// with no jq counterpart, but several call sites had a real jq
    /// wording they didn't match. Confirmed against jq 1.7.1 for every
    /// case below.
    #[test]
    fn test_type_error_sites_match_real_jq_wording_929() {
        // map_values/min_by/max_by/unique_by all fail like a bare `.[]`
        // would on a non-object/array input.
        query!(br"5", r"map_values(.)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over number (5)");
            }
        );
        query!(br"5", r"min_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over number (5)");
            }
        );
        query!(br"5", r"max_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over number (5)");
            }
        );
        query!(br"5", r"unique_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over number (5)");
            }
        );
        // nth(n) is `.[n]` in real jq: a non-numeric n names itself as the
        // bad key, a non-array input names the successfully-parsed n.
        query!(br"[1,2,3]", r#"nth("x")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index array with string \"x\"");
            }
        );
        query!(br"5", r"nth(1)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with number");
            }
        );
        query!(br#""abc""#, r"nth(1)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index string with number");
            }
        );
        // @csv/@tsv on a non-array, @sh on an object.
        query!(br"5", r"@csv",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (5) cannot be csv-formatted, only array");
            }
        );
        query!(br"5", r"@tsv",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (5) cannot be tsv-formatted, only array");
            }
        );
        query!(br#"{"a":1}"#, r"@sh",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "object ({\"a\":1}) can not be escaped for shell");
            }
        );
        // strptime/fromdate: real jq validates both the input and the
        // format argument with one combined check, same message either way.
        query!(br#""2020""#, r"strptime(1)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "strptime/1 requires string inputs and arguments");
            }
        );
        query!(br"5", r#"strptime("%Y")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "strptime/1 requires string inputs and arguments");
            }
        );
        query!(br"5", r"fromdate",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "strptime/1 requires string inputs and arguments");
            }
        );
    }

    /// #929's mandatory code review found six further gaps beyond the
    /// initial wording audit above -- two pre-existing `nth` bugs the new
    /// wording made "more confidently wrong", a missing object-input
    /// variant for `min_by`/`max_by`/`unique_by`, and a second `@sh` site.
    /// Confirmed against jq 1.7.1 for every case below.
    #[test]
    fn test_review_response_929() {
        // nth(n) is really `.[n]`: a string key on an object behaves like
        // any other object field access (missing key => null, not an
        // error), and a float key truncates toward zero instead of being
        // rejected outright.
        assert_eq!(outputs(br#"{"a":1}"#, r#"nth("x")"#), ["null"]);
        assert_eq!(outputs(br#"{"a":1}"#, r#"nth("a")"#), ["1"]);
        assert_eq!(outputs(br"[1,2,3]", r"nth(1.5)"), ["2"]);
        assert_eq!(outputs(br"[1,2,3]", r"nth(-1.5)"), ["3"]);
        // `n` is evaluated against the original input before indexing, so
        // it runs even when `.` is null instead of short-circuiting to
        // null first.
        query!(br"null", r#"nth(error("boom"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "boom");
            }
        );
        assert_eq!(outputs(br"null", r"nth(0)"), ["null"]);

        // min_by/max_by/unique_by on an object input pair the object with
        // the array `map([f])` computes on it -- not the generic
        // single-value "Cannot iterate over" a bare scalar gets.
        query!(br#"{"a":3,"b":1}"#, r"min_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "object ({\"a\":3,\"b\":1}) and array ([[3],[1]]) cannot be iterated over"
                );
            }
        );
        query!(br#"{"a":3,"b":1}"#, r"max_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "object ({\"a\":3,\"b\":1}) and array ([[3],[1]]) cannot be iterated over"
                );
            }
        );
        query!(br#"{"a":3,"b":1}"#, r"unique_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "object ({\"a\":3,\"b\":1}) and array ([[3],[1]]) cannot be sorted, as they are not both arrays"
                );
            }
        );

        // A `?`-suffixed min_by/max_by/unique_by on an object input
        // suppresses the pairing error the same way it already did for a
        // bare scalar, and an error `f` raises on the object's own values
        // still propagates instead of being swallowed by that suppression.
        assert_eq!(outputs(br#"{"a":1}"#, r"min_by(.)?"), Vec::<String>::new());
        assert_eq!(outputs(br#"{"a":1}"#, r"max_by(.)?"), Vec::<String>::new());
        assert_eq!(
            outputs(br#"{"a":1}"#, r"unique_by(.)?"),
            Vec::<String>::new()
        );
        query!(br#"{"a":1}"#, r#"min_by(error("boom"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "boom");
            }
        );
        query!(br#"{"a":1}"#, r#"max_by(error("boom"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "boom");
            }
        );
        query!(br#"{"a":1}"#, r#"unique_by(error("boom"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "boom");
            }
        );

        // @sh's array arm validates each *element* the same way the
        // top-level value is validated, not just the top level itself --
        // including the non-string scalar arms of `shell_quote_value`
        // itself (a bool element takes a different branch than a string
        // or number one).
        query!(br#"[{"a":1}]"#, r"@sh",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "object ({\"a\":1}) can not be escaped for shell");
            }
        );
        assert_eq!(outputs(br"[false]", r"@sh"), ["\"false\""]);
    }

    /// #995: `group_by`/`sort_by` on an object input have the identical
    /// pairing bug #929's review found for `unique_by` -- they share the
    /// same `map([f])` computation and "not both arrays" suffix, but
    /// predate #929's diff (they never called `EvalError::type_error`, so
    /// they were outside that issue's grep-based scope). Confirmed against
    /// jq 1.7.1 for every case below.
    #[test]
    fn test_group_by_sort_by_object_wording_995() {
        query!(br#"{"a":3,"b":1}"#, r"group_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "object ({\"a\":3,\"b\":1}) and array ([[3],[1]]) cannot be sorted, as they are not both arrays"
                );
            }
        );
        query!(br#"{"a":3,"b":1}"#, r"sort_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "object ({\"a\":3,\"b\":1}) and array ([[3],[1]]) cannot be sorted, as they are not both arrays"
                );
            }
        );
        // The computed array tracks the actual filter, not a fixed
        // placeholder.
        query!(br#"{"a":3,"b":1}"#, r"group_by(. + 100)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "object ({\"a\":3,\"b\":1}) and array ([[103],[101]]) cannot be sorted, as they are not both arrays"
                );
            }
        );
        query!(br#"{"a":3,"b":1}"#, r"sort_by(. + 100)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "object ({\"a\":3,\"b\":1}) and array ([[103],[101]]) cannot be sorted, as they are not both arrays"
                );
            }
        );
        // Scalar input keeps the pre-existing, already-correct wording.
        query!(br"5", r"group_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over number (5)");
            }
        );
        query!(br"5", r"sort_by(.)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over number (5)");
            }
        );
        // `?` suppresses the pairing error, and an error `f` still
        // propagates through the suppression.
        assert_eq!(
            outputs(br#"{"a":1}"#, r"group_by(.)?"),
            Vec::<String>::new()
        );
        assert_eq!(outputs(br#"{"a":1}"#, r"sort_by(.)?"), Vec::<String>::new());
        query!(br#"{"a":1}"#, r#"group_by(error("boom"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "boom");
            }
        );
        query!(br#"{"a":1}"#, r#"sort_by(error("boom"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "boom");
            }
        );
    }

    /// #995 review: bare `unique` (real jq defines it as `unique_by(.)`) has
    /// the identical object-input pairing bug, missed by both #929's
    /// grep-based audit and this issue's own initial scope because `unique`
    /// takes no `f` argument at all. Confirmed against jq 1.7.1.
    #[test]
    fn test_unique_object_wording_995() {
        query!(br#"{"a":3,"b":1}"#, r"unique",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "object ({\"a\":3,\"b\":1}) and array ([[3],[1]]) cannot be sorted, as they are not both arrays"
                );
            }
        );
        // Scalar input keeps the pre-existing, already-correct wording.
        query!(br"5", r"unique",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over number (5)");
            }
        );
        assert_eq!(outputs(br#"{"a":1}"#, r"unique?"), Vec::<String>::new());
    }

    #[test]
    fn test_builtin_indices() {
        query!(br#""abcabc""#, r#"indices("bc")"#,
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 2);
                assert_eq!(arr[0], OwnedValue::Int(1));
                assert_eq!(arr[1], OwnedValue::Int(4));
            }
        );
    }

    #[test]
    fn test_builtin_index() {
        query!(br#""hello world""#, r#"index("world")"#,
            QueryResult::Owned(OwnedValue::Int(n)) => {
                assert_eq!(n, 6);
            }
        );

        query!(br#""hello world""#, r#"index("xyz")"#,
            QueryResult::Owned(OwnedValue::Null) => {}
        );
    }

    #[test]
    fn test_builtin_rindex() {
        query!(br#""abcabc""#, r#"rindex("bc")"#,
            QueryResult::Owned(OwnedValue::Int(n)) => {
                assert_eq!(n, 4);
            }
        );
    }

    /// #950 review: `index`/`indices`/`rindex` internally use equality to
    /// find matching array elements, and must agree with `==`'s own
    /// yq-mode strict Int/Float distinction rather than the always-widening
    /// `PartialEq` (verified against jq semantics for the jq-mode case;
    /// mikefarah/yq's own grammar doesn't accept `index(2.0)` the same way
    /// to cross-check yq mode directly, so this pins internal consistency
    /// with the now-fixed `==`/`contains` instead).
    #[test]
    fn test_builtin_index_family_respects_strict_numeric_equality_950() {
        // jq mode: widening, 2.0 matches 2 (unaffected by #950).
        query!(br"[2,3]", "index(2.0)",
            QueryResult::Owned(OwnedValue::Int(n)) => { assert_eq!(n, 0); }
        );

        // yq mode: strict, 2.0 does not match 2.
        yq_query!(br"[2,3]", "index(2.0)",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
        yq_query!(br"[2.0,3,2.0]", "indices(2.0)",
            QueryResult::Owned(OwnedValue::Array(v)) => {
                assert_eq!(v, vec![OwnedValue::Int(0), OwnedValue::Int(2)]);
            }
        );
        yq_query!(br"[2.0,3,2]", "rindex(2)",
            QueryResult::Owned(OwnedValue::Int(n)) => { assert_eq!(n, 2); }
        );
    }

    /// #950 review: `IN(s)` (single-arg) internally uses equality and must
    /// agree with `==`'s own yq-mode strict Int/Float distinction, per its
    /// own doc comment stating it matches jq's `any(s == .; .)`.
    #[test]
    fn test_builtin_upper_in_respects_strict_numeric_equality_950() {
        // jq mode: widening, unaffected by #950.
        query!(br"2.0", "IN(2)",
            QueryResult::Owned(OwnedValue::Bool(b)) => { assert!(b); }
        );
        // yq mode: strict.
        yq_query!(br"2.0", "IN(2)",
            QueryResult::Owned(OwnedValue::Bool(b)) => { assert!(!b); }
        );
    }

    #[test]
    fn test_builtin_upper_in_single_arg() {
        query!(br"5", "IN(1,2,3,5)",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
        query!(br"7", "IN(1,2,3,5)",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );
    }

    #[test]
    fn test_builtin_upper_in_src_two_arg() {
        // Verified against the real jq-1.7.1 oracle (issue #722): `IN(src; s)`
        // is a cartesian equality check between src's and s's outputs, both
        // run against the *original* current value — not the naive
        // `any(src|s == .; .)` reading, whose pipe rebinds `.` before `s`
        // (and the trailing `.`) ever see it, so it can never actually
        // depend on the original input. `5 | IN(10,20,30; .)` pins that: the
        // naive reading is always `true` regardless of input, but real jq
        // (and this implementation) says `false` here since 5 is not among
        // 10,20,30.
        query!(br"5", "IN(10,20,30; .)",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );
        query!(br"10", "IN(10,20,30; .)",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
    }

