    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_non_string_pattern_wording_matches_jq_per_family_926() {
        // #926: jq itself uses two different sentences for a non-string
        // *pattern* argument depending on which builtin family raises it —
        // test/match/capture's "<type> not a string or array" (no value
        // preview) vs. scan/gsub/sub/splits/split(re;flags)'s "<v> is not a
        // string" (with a value preview). Both bare forms are already
        // pinned per-builtin, against both evaluators, by the oracle-driven
        // `jq_error_message_parity` test via `tests/data/jq-error-probes.tsv`
        // (test_arg_non_string, scan_arg_non_string, etc.) — this test only
        // covers what that corpus can't: a flagged sibling sharing its bare
        // form's wording, and the object/array value-preview rendering.
        // Verified live against jq 1.7.1.

        // The flagged sibling shares its bare form's wording.
        query!(br#""x""#, r#"scan(1; "i")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (1) is not a string");
            }
        );

        // Object/array previews render the same way `describe()` renders
        // them elsewhere in this file (truncated JSON dump).
        query!(br#""x""#, r#"scan({"a":1})"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"object ({"a":1}) is not a string"#);
            }
        );
        query!(br#""x""#, r"scan([1,2])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "array ([1,2]) is not a string");
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_non_string_flags_wording_matches_jq_per_family_928() {
        // #928: the *flags* argument (not the pattern) splits into the same
        // two families as #926's pattern-argument fix, plus a third
        // wording scan/gsub/split/splits share: jq builds their internal
        // global-flag string via concatenation (flags + "g" or "g" +
        // flags) *before* type-checking, so a non-string flags value hits
        // jq's own `+` operator error instead of a string-type error.
        // Every case verified live against jq 1.7.1.

        // test/match/capture/sub: same "is not a string" wording as the
        // pattern argument.
        for filter in [r#"test("a"; 1)"#, r#"sub("a"; "b"; 1)"#] {
            query!(br#""x""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "number (1) is not a string", "filter: {filter}");
                }
            );
        }

        // gsub: flags + "g" (append) — flags value on the left, matching
        // #730's append-vs-prepend split for valid flags strings.
        query!(br#""x""#, r#"gsub("a"; "b"; 1)"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (1) and string (\"g\") cannot be added");
            }
        );

        // scan/split/splits: "g" + flags (prepend) — "g" on the left.
        for filter in [r#"scan("a"; 1)"#, r#"split("a"; 1)"#, r#"splits("a"; 1)"#] {
            query!(br#""x""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(
                        e.message,
                        "string (\"g\") and number (1) cannot be added",
                        "filter: {filter}"
                    );
                }
            );
        }

        // ? still suppresses a non-string flags value, for every builtin
        // whose flags-eval this PR touched (not just gsub). The suppression
        // happens one level up, in the ancestor `eval_try` that a bare `?`
        // installs (#693) — these builtins' own flags/pattern-eval match
        // arms have no local `optional`-guarded case to take instead (see
        // the "No `Ok(_) if optional` guard" comments in `builtin_match`
        // and `builtin_gsub_with_flags`), so this is pinning the
        // end-to-end behavior, not a specific branch.
        for filter in [
            r#"[match("a"; 1)?]"#,
            r#"[capture("(?<a>a)"; 1)?]"#,
            r#"[sub("a"; "b"; 1)?]"#,
            r#"[test("a"; 1)?]"#,
            r#"[gsub("a"; "b"; 1)?]"#,
            r#"[gsub(1; "b"; "i")?]"#,
        ] {
            query!(br#""x""#, filter,
                QueryResult::Owned(OwnedValue::Array(vs)) => {
                    assert!(vs.is_empty(), "filter: {filter}");
                }
            );
        }

        // null is still treated as no flags (untouched by this fix).
        //
        // `Owned`, not `ManyOwned([_])`: since #1279 routed `scan(re; flags)`
        // through `fanout_regex_pattern_and_concat_flags`, its result passes
        // through `owned_vec_to_result`, which normalizes a one-element run to
        // the canonical single-value shape (`collapse_vec`). Not user-visible
        // -- `scan("a"; null)` on `"abc"` prints `"a"` either way, matching
        // jq -- so this asserts the match itself rather than the variant it
        // arrives in.
        query!(br#""abc""#, r#"scan("a"; null)"#,
            QueryResult::Owned(OwnedValue::String(matched)) => {
                assert_eq!(matched, "a");
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_pattern_error_wording_switches_on_flags_arity_937() {
        // #937: test/match/capture's pattern-argument error wording depends
        // on which arity was actually called, not just the pattern's own
        // type — the bare 1-arg form says "<type> not a string or array"
        // (#926), but the 2-arg form switches to "<v> is not a string" even
        // when the flags value itself is fine (a valid, empty, or `null`
        // flags string). `sub` has no such split — its bare-vs-flagged
        // wording is identical in real jq, so #926 already gave it
        // `is_not_a_string` unconditionally and this fix doesn't touch it.
        // Every case verified live against jq 1.7.1.

        // Bare form: unchanged from #926 (not_string_or_array, no preview).
        for filter in [r"test(1)", r"match(1)", r"capture(1)"] {
            query!(br#""x""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "number not a string or array", "filter: {filter}");
                }
            );
        }

        // Flagged form with a *valid* flags value still switches wording —
        // it's the arity, not the flags value's own validity, that matters.
        for filter in [
            r#"test(1; "")"#,
            r#"match(1; "")"#,
            r#"capture(1; "")"#,
            r"test(1; null)",
            r"match(1; null)",
            r"capture(1; null)",
        ] {
            query!(br#""x""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "number (1) is not a string", "filter: {filter}");
                }
            );
        }

        // The both-arguments-invalid case (`test(1; 2)` etc.) is already
        // covered by `test_regex_pattern_vs_flags_error_precedence_928_942`,
        // which asserts the same flagged-form wording this test pins
        // above — not repeated here.
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_pattern_vs_flags_error_precedence_928_942() {
        // #928/#942: when both the pattern and flags arguments are
        // invalid, which one's error surfaces depends on *what kind* of
        // invalid each is, not a single fixed "pattern always wins" rule.
        //
        // For ordinary type mismatches (no `error()` call, just a wrong-
        // typed value), pattern's error always wins once both values are
        // known — confirmed live: `test(1;2)` -> "number (1) is not a
        // string", naming the pattern (1), not the flags (2); same for
        // match/capture/sub.
        //
        // But which argument is forced *first* — and so whose `error()`
        // call, if any, actually runs and propagates — differs by family
        // (confirmed live via `debug()` side-effect probes, since the
        // error-wins outcome alone can't distinguish the two orderings
        // when only one side raises):
        // - test/match/capture force FLAGS first: `test(debug("x");
        //   error("F"))` never prints "x" (pattern never evaluated once
        //   flags raises); `test(error("P"); debug("x"))` does print "x"
        //   before "P" (flags' side effect runs, then pattern's error
        //   propagates).
        // - sub forces PATTERN first (the reverse): `sub(debug("x"); "b";
        //   error("F"))` prints "x" before "F"; `sub(error("P"); "b";
        //   debug("x"))` never prints "x".
        // - gsub/scan/split/splits are excluded here: this test only
        //   covers the #928/#942 (evaluate-flags-then-pattern) shape.
        //   They had a differently-shaped divergence — pattern is forced
        //   *first* for them (not flags), which #938 fixes separately in
        //   `eval_regex_pattern_and_concat_flags`, pinned by its own test.
        //
        // Net effect: a flags-side `error()` always wins over a pattern-
        // side *type mismatch* (not itself an `error()` call) for all four
        // builtins here, since the type-check phase only runs after both
        // arguments have already been forced without raising — see
        // `eval_regex_pattern_and_flags`'s doc comment for the full model.
        for filter in ["test(1; 2)", "match(1; 2)", "capture(1; 2)"] {
            query!(br#""abc""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(
                        e.message, "number (1) is not a string",
                        "filter: {filter}"
                    );
                }
            );
        }
        query!(br#""abc""#, r#"sub(1; "b"; 2)"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (1) is not a string");
            }
        );

        // A side-effecting pattern expression's error() must propagate,
        // not get silently skipped in favor of the flags check — true for
        // all four regardless of which argument is forced first, since
        // the *other* argument's own type is never even inspected once
        // either one has genuinely raised.
        query!(br#""abc""#, r#"sub(error("PATTERN_ERR"); "b"; 2)"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "PATTERN_ERR");
            }
        );
        query!(br#""abc""#, r#"test(1; error("FLAGS_ERR"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "FLAGS_ERR");
            }
        );

        // Both sides raise: whichever argument is forced first wins,
        // regardless of message content — flags for test/match/capture,
        // pattern for sub.
        for filter in ["test", "match", "capture"] {
            query!(br#""abc""#, &format!(r#"{filter}(error("PATTERN_ERR"); error("FLAGS_ERR"))"#),
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "FLAGS_ERR", "filter: {filter}");
                }
            );
        }
        query!(br#""abc""#, r#"sub(error("PATTERN_ERR"); "b"; error("FLAGS_ERR"))"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "PATTERN_ERR");
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_gsub_family_forces_pattern_before_flags_938() {
        // #938: gsub/scan/split/splits force the *pattern* expression
        // first (propagating a genuine error(), but not yet checking its
        // type), then evaluate+type-check flags via jq's internal
        // `flags + "g"`/`"g" + flags` concatenation, and only afterward
        // check pattern's own type. This is the reverse of the pre-fix
        // behavior, which evaluated (and type-checked) flags first,
        // silently skipping a side-effecting pattern expression whenever
        // flags itself raised. Confirmed live via `debug()`-based probes
        // in the doc comment on `eval_regex_pattern_and_concat_flags` —
        // "which error wins" alone can't distinguish evaluation order
        // when only one side ever raises (both orderings predict the same
        // winner for e.g. `gsub(1;"b";2)`).

        // Ordinary type mismatch (neither side raises): flags' type error
        // still wins, unchanged from before this fix — matches jq's own
        // flags-then-pattern *type-check* order (independent of which
        // argument is evaluated first).
        for filter in [
            r#"gsub(1; "b"; 2)"#,
            r"scan(1; 2)",
            r"split(1; 2)",
            r"splits(1; 2)",
        ] {
            query!(br#""abc""#, filter,
                QueryResult::Error(e) => {
                    assert!(e.message.contains("cannot be added"), "filter: {filter}: {}", e.message);
                }
            );
        }

        // A side-effecting pattern expression's error() must propagate,
        // even though flags raises too — pattern is forced first and
        // flags is never touched once pattern itself raises.
        for filter in [
            r#"gsub(error("PATTERN_ERR"); "b"; error("FLAGS_ERR"))"#,
            r#"scan(error("PATTERN_ERR"); error("FLAGS_ERR"))"#,
            r#"split(error("PATTERN_ERR"); error("FLAGS_ERR"))"#,
            r#"splits(error("PATTERN_ERR"); error("FLAGS_ERR"))"#,
        ] {
            query!(br#""abc""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "PATTERN_ERR", "filter: {filter}");
                }
            );
        }

        // A side-effecting *flags* expression's error() still propagates
        // when the pattern is a plain, non-erroring valid string.
        for filter in [
            r#"gsub("a"; "b"; error("FLAGS_ERR"))"#,
            r#"scan("a"; error("FLAGS_ERR"))"#,
            r#"split("a"; error("FLAGS_ERR"))"#,
            r#"splits("a"; error("FLAGS_ERR"))"#,
        ] {
            query!(br#""abc""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "FLAGS_ERR", "filter: {filter}");
                }
            );
        }

        // `?` still suppresses a non-string flags value for every member
        // of this family (unaffected by the reorder).
        for filter in [
            r#"[gsub(1; "b"; 2)?]"#,
            r"[scan(1; 2)?]",
            r"[split(1; 2)?]",
            r"[splits(1; 2)?]",
        ] {
            query!(br#""abc""#, filter,
                QueryResult::Owned(OwnedValue::Array(vs)) => {
                    assert!(vs.is_empty(), "filter: {filter}");
                }
            );
        }

        // `?` also still suppresses a non-string *pattern* value on the
        // bare (no-flags-argument) forms — `builtin_scan_with_flags`/
        // `builtin_splits_with_flags`/`builtin_gsub_with_flags`'s own
        // pattern-eval blocks (`split` has no bare regex form to cover).
        for filter in [r#"[gsub(1; "b")?]"#, r"[scan(1)?]", r"[splits(1)?]"] {
            query!(br#""abc""#, filter,
                QueryResult::Owned(OwnedValue::Array(vs)) => {
                    assert!(vs.is_empty(), "filter: {filter}");
                }
            );
        }
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_bare_array_pattern_unpacks_as_regex_flags_943() {
        // #943: test/match/capture's *bare* form (no flags argument at
        // all) additionally accepts a non-empty array pattern, unpacking
        // it as [pattern, flags, ...ignored] -- undocumented but real jq
        // behavior. sub/gsub/scan/split/splits do NOT do this (a plain
        // non-string-pattern error, verified separately below), and an
        // array pattern combined with an explicit flags argument doesn't
        // unpack either -- the two ways of supplying flags don't combine.
        // Every case verified live against jq 1.7.1.

        // Successful unpacking: 2-element [string, string], content
        // verified against the equivalent 2-arg form's own known output.
        query!(br#""abc""#, r#"test(["a", "i"])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
        query!(br#""abc""#, r#"match(["a", "i"])"#,
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("string"), Some(&OwnedValue::String("a".to_string())));
                assert_eq!(obj.get("offset"), Some(&OwnedValue::Int(0)));
            }
        );
        query!(br#""abc""#, r#"capture(["(?<x>a)", "i"])"#,
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("x"), Some(&OwnedValue::String("a".to_string())));
            }
        );

        // The unpacked flags slot reaches the same "g" (global) handling a
        // real flags argument would -- multiple matches, not just one.
        query!(br#""aaa""#, r#"match(["a", "g"])"#,
            QueryResult::ManyOwned(matches) => {
                assert_eq!(matches.len(), 3);
                for m in &matches {
                    let OwnedValue::Object(obj) = m else { panic!("expected object, got {m:?}") };
                    assert_eq!(obj.get("string"), Some(&OwnedValue::String("a".to_string())));
                }
            }
        );

        // 1-element array: pattern only, missing flags slot behaves like
        // an explicit `null` flags (still succeeds).
        query!(br#""abc""#, r#"test(["a"])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        // Extra elements past index 1 are silently ignored, not an error.
        query!(br#""abc""#, r#"test(["a", "i", "extra", "junk"])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        // A genuinely empty array has no element 0 to unpack, so it falls
        // through to the plain non-string-pattern check on the array
        // itself -- the *bare*-form wording (no value preview), since
        // unpacking never happened.
        for filter in [r"test([])", r"match([])", r"capture([])"] {
            query!(br#""abc""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "array not a string or array", "filter: {filter}");
                }
            );
        }

        // Once unpacked, a bad pattern or flags value uses the *flagged*-
        // form wording (is_not_a_string, with a value preview) even
        // though this is syntactically the bare 1-arg call -- confirmed
        // live even for a 1-element array with no explicit flags slot:
        // `test([1])` -> "number (1) is not a string", not `test(1)`'s
        // own "number not a string or array".
        for filter in ["test([1])", "test([1, 2])", "test([\"a\", 2])"] {
            query!(br#""abc""#, filter,
                QueryResult::Error(e) => {
                    assert!(e.message.ends_with("is not a string"), "filter: {filter}: {}", e.message);
                }
            );
        }

        // An explicit flags argument suppresses unpacking entirely --
        // the array is just an ordinary bad pattern value then, using
        // the (already-established, #937) flagged-form wording.
        query!(br#""abc""#, r#"test(["a", "i"]; "x")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "array ([\"a\",\"i\"]) is not a string");
            }
        );

        // sub/gsub/scan/split/splits do not unpack array patterns at all.
        for filter in [
            r#"sub(["a", "i"]; "b")"#,
            r#"gsub(["a", "i"]; "b")"#,
            r#"scan(["a", "i"])"#,
        ] {
            query!(br#""abc""#, filter,
                QueryResult::Error(e) => {
                    assert!(e.message.starts_with("array ("), "filter: {filter}: {}", e.message);
                }
            );
        }
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_lookahead_unsupported() {
        // #703: jq's oniguruma backend supports lookahead (`(?=...)`), but
        // succinctly's `regex` crate does not implement lookaround at all —
        // this is a permanent constraint of the crate choice, not a bug to
        // fix here. Pinned so nobody "fixes" it later by attempting
        // lookahead support inside `build_regex`.
        query!(br#""aubub""#, r#"gsub("(?=u)"; "u")"#,
            QueryResult::Error(e) => {
                assert!(e.to_string().contains("invalid regex"));
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_flags_null_treated_as_no_flags() {
        // #804: jq treats a `null` flags argument identically to `""`/absent
        // flags across every regex builtin, rather than erroring.
        query!(br#""abc""#, r#"test("a"; null)"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        query!(br#""abc""#, r#"match("a"; null)"#,
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("string"), Some(&OwnedValue::String("a".to_string())));
            }
        );

        query!(br#""foo bar""#, r#"capture("(?P<first>\\w+) (?P<second>\\w+)"; null)"#,
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("first"), Some(&OwnedValue::String("foo".to_string())));
            }
        );

        query!(br#""abc""#, r#"sub("a"; "b"; null)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "bbc");
            }
        );

        query!(br#""abcabc""#, r#"gsub("a"; "b"; null)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "bbcbbc");
            }
        );

        query!(br#""test abc test""#, r#"scan("test"; null)"#,
            QueryResult::ManyOwned(matches) => {
                assert_eq!(matches.len(), 2);
            }
        );

        query!(br#""a1b2c3d""#, r#"split("[0-9]"; null)"#,
            QueryResult::Owned(OwnedValue::Array(parts)) => {
                assert_eq!(parts.len(), 4);
            }
        );

        query!(br#""a1b2c3d""#, r#"[splits("[0-9]"; null)]"#,
            QueryResult::Owned(OwnedValue::Array(parts)) => {
                assert_eq!(parts.len(), 4);
            }
        );

        // Non-string, non-null flags must still error — #928: jq's real
        // wording here ("<v> is not a string"), not the old placeholder
        // "expected string, got flags" this loosely matched before.
        query!(br#""abc""#, r#"test("a"; 5)"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (5) is not a string");
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_unknown_flags_rejected_730() {
        // #730: an unrecognized flag character must raise jq's own error
        // rather than silently doing nothing. Verified against jq 1.7.1:
        // the message names the *whole* flags string, not just the
        // offending character, and is identical whether the bad character
        // stands alone or sits next to a genuinely valid one.
        for (flags, expected) in [
            ("z", "z is not a valid modifier string"),
            ("zq", "zq is not a valid modifier string"),
            ("iz", "iz is not a valid modifier string"),
        ] {
            query!(br#""abc""#, &format!(r#"test("abc"; "{flags}")"#),
                QueryResult::Error(e) => {
                    assert_eq!(e.message, expected, "flags: {flags:?}");
                }
            );
        }

        // `n` (suppress empty matches, implemented below in
        // test_regex_n_flag_suppresses_empty_matches_730), `l` (POSIX
        // leftmost-longest, permanently unimplemented — #920, ADR-0019)
        // and `p` are all real jq flag characters — they must not be
        // rejected as unknown.
        for flags in ["n", "l", "p"] {
            query!(br#""abc""#, &format!(r#"test("abc"; "{flags}")"#),
                QueryResult::Owned(OwnedValue::Bool(b)) => {
                    assert!(b, "flags: {flags:?}");
                }
            );
        }
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_n_flag_suppresses_empty_matches_730() {
        // #730: `n` filters zero-length matches out of the global-match
        // iteration, and — for the first-match-only builtins — searches
        // forward past a leading empty match to find the first non-empty
        // one, rather than settling for offset 0. Every case here is
        // verified live against jq 1.7.1.

        // scan/gsub/split/splits (global by construction) keep only the
        // non-empty runs.
        query!(br#""a  b   c""#, r#"[scan(" *"; "n")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(
                    vs,
                    vec![
                        OwnedValue::String("  ".to_string()),
                        OwnedValue::String("   ".to_string()),
                    ]
                );
            }
        );
        query!(br#""a  b   c""#, r#"gsub(" *"; "_"; "n")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "a_b_c");
            }
        );
        query!(br#""a1b2""#, r#"[splits("[0-9]*"; "n")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(
                    vs,
                    vec![
                        OwnedValue::String("a".to_string()),
                        OwnedValue::String("b".to_string()),
                        OwnedValue::String(String::new()),
                    ]
                );
            }
        );

        // match(re;"g") / capture(re;"g") also route through the same
        // global_captures filtering.
        query!(br#""a  b   c""#, r#"[match(" *"; "gn")] | length"#,
            QueryResult::Owned(OwnedValue::Int(n)) => {
                assert_eq!(n, 2);
            }
        );

        // match/test/capture/sub without "g" search forward past a leading
        // empty match instead of settling for it.
        query!(br#""aaxaa""#, r#"match("x*"; "n") | .offset"#,
            QueryResult::Owned(OwnedValue::Int(offset)) => {
                assert_eq!(offset, 2);
            }
        );
        query!(br#""aaxaa""#, r#"test("x*"; "n")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
        query!(br#""aaxaa""#, r#"sub("x*"; "Y"; "n")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "aaYaa");
            }
        );

        // When no non-empty match exists anywhere, jq's generators produce
        // no output at all (not `null`), `test` is false, and `sub` leaves
        // the input unchanged since there is nothing to replace.
        query!(br#""a""#, r#"[match("x*"; "n")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert!(vs.is_empty());
            }
        );
        query!(br#""a""#, r#"test("x*"; "n")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );
        query!(br#""aaa""#, r#"sub("x*"; "Y"; "n")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "aaa");
            }
        );

        // `n` composes with other flags rather than overriding them.
        query!(br#""AAxAA""#, r#"match("x*"; "in") | .offset"#,
            QueryResult::Owned(OwnedValue::Int(offset)) => {
                assert_eq!(offset, 2);
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_n_flag_known_gap_lazy_quantifier_922() {
        // #922: `n`'s skip-forward search only finds a non-empty match
        // reachable by moving to a *later* position, not one reachable only
        // by backtracking to a different alternative at the *same*
        // position — which a lazy quantifier or an empty-preferring
        // alternation can require. Rust's non-backtracking `regex` crate
        // has no equivalent to oniguruma's `ONIG_OPTION_FIND_NOT_EMPTY`
        // (same root cause as #920's missing `MatchKind::LeftmostLongest`).
        // Accepted as a permanent, documented limitation — see ADR-0019.
        //
        // This pins the *current, known-divergent* behavior rather than
        // jq's — verified live against jq 1.7.1, which returns `true`/a
        // real match/`["x","a","b","b"]` for each case below.
        query!(br#""x\nabb""#, r#"test("a*?"; "n")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b, "jq says true here (offset 2, \"a\") — known gap, #922");
            }
        );
        query!(br#""x\nabb""#, r#"[match("a*?"; "n")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert!(vs.is_empty(), "jq finds a match at offset 2 — known gap, #922");
            }
        );
        query!(br#""x\nabb""#, r#"[scan(".*?"; "gn")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert!(vs.is_empty(), "jq returns [\"x\",\"a\",\"b\",\"b\"] — known gap, #922");
            }
        );

        // The equivalent alternation with branches reordered (non-empty
        // first) is unaffected — isolates the gap to which alternative the
        // engine's leftmost-first preference reaches, not to `n` broadly.
        query!(br#""xa""#, r#"[match("(?:a|)"; "gn")] | length"#,
            QueryResult::Owned(OwnedValue::Int(n)) => {
                assert_eq!(n, 1);
            }
        );
        query!(br#""xa""#, r#"[match("(?:|a)"; "gn")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert!(vs.is_empty(), "jq finds a match at offset 1 — known gap, #922");
            }
        );

        // #1502: the gap is not specific to test/match/scan — sub/gsub/
        // split/splits all route through the same first_captures/
        // global_captures choke point, so they miss the same lazy-
        // quantifier match and silently no-op instead of replacing/
        // splitting. Verified live against jq 1.7.1, which returns
        // "xXXb"/"xXab"/["x","","b"]/[["x","","b"]] for the four cases
        // below.
        query!(br#""xaab""#, r#"gsub("a*?"; "X"; "gn")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "xaab", "jq returns \"xXXb\" — known gap, #922");
            }
        );
        query!(br#""xaab""#, r#"sub("a*?"; "X"; "n")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "xaab", "jq returns \"xXab\" — known gap, #922");
            }
        );
        query!(br#""xaab""#, r#"[splits("a*?"; "gn")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(
                    vs,
                    vec![OwnedValue::String("xaab".to_string())],
                    "jq returns [\"x\",\"\",\"b\"] — known gap, #922"
                );
            }
        );
        query!(br#""xaab""#, r#"[split("a*?"; "gn")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(
                    vs,
                    vec![OwnedValue::Array(vec![OwnedValue::String("xaab".to_string())])],
                    "jq returns [[\"x\",\"\",\"b\"]] — known gap, #922"
                );
            }
        );

        // Boundary, greedy half: a greedy quantifier (no backtracking
        // needed to find the non-empty match) and a `[0-9]*` character
        // class are both unaffected and agree with jq — the gap is in
        // *reaching* a non-empty match via backtracking, not in `n`
        // itself. Complements the reordered-alternation boundary pinned
        // above.
        query!(br#""xaab""#, r#"[scan("a*"; "gn")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(vs, vec![OwnedValue::String("aa".to_string())]);
            }
        );
        query!(br#""a12b""#, r#"[match("[0-9]*"; "gn").string]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(vs, vec![OwnedValue::String("12".to_string())]);
            }
        );

        // #1502 review: `capture` is one of ADR-0019's eight regex builtin
        // families sharing this choke point, and was otherwise untested
        // under `n` anywhere in this file. It shares the exact no-match
        // outcome as match/test above: no non-empty match is reachable
        // without backtracking, so the generator produces no output at
        // all (not `null`, not an empty object) rather than jq's
        // `{"x":"a"}`.
        query!(br#""xaab""#, r#"[capture("(?<x>a*?)"; "n")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert!(vs.is_empty(), "jq returns [{{\"x\":\"a\"}}] — known gap, #922");
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_l_flag_known_gap_920() {
        // #920: jq's `l` flag switches from Perl-style leftmost-first to
        // POSIX leftmost-longest matching (real oniguruma), applied
        // recursively to every subexpression. Rust's `regex`/
        // `regex-automata` stack has no `MatchKind::LeftmostLongest`
        // implementation to switch to (the crate's own maintainers left
        // the door open but never built it), so succinctly accepts `l` as
        // valid flag syntax — see test_regex_unknown_flags_rejected_730 —
        // but it has no effect on match semantics. Accepted as a
        // permanent, documented limitation — see ADR-0019.
        //
        // This pins the *current, known-divergent* behavior rather than
        // jq's — verified live against jq 1.7.1, which returns "aaa"/"X"/
        // ["aaa"]/["aaa","a"] for the four cases below (`l` reorders a
        // top-level alternation to prefer the longest branch at each
        // position; succinctly keeps its own leftmost-first order and
        // stops at the first alternative that matches, "a").
        query!(br#""aaa""#, r#"match("a|aa|aaa"; "l").string"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "a", "jq returns \"aaa\" — known gap, #920");
            }
        );
        query!(br#""aaa""#, r#"sub("a|aa|aaa"; "X"; "l")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "Xaa", "jq returns \"X\" — known gap, #920");
            }
        );
        query!(br#""aaa""#, r#"[scan("a|aa|aaa"; "gl")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(
                    vs,
                    vec![
                        OwnedValue::String("a".to_string()),
                        OwnedValue::String("a".to_string()),
                        OwnedValue::String("a".to_string()),
                    ],
                    "jq returns [\"aaa\"] — known gap, #920"
                );
            }
        );
        query!(br#""aaaa""#, r#"[match("a|aa|aaa"; "gl").string]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(
                    vs,
                    vec![
                        OwnedValue::String("a".to_string()),
                        OwnedValue::String("a".to_string()),
                        OwnedValue::String("a".to_string()),
                        OwnedValue::String("a".to_string()),
                    ],
                    "jq returns [\"aaa\",\"a\"] — known gap, #920"
                );
            }
        );

        // #1502 review: `capture` shares the same no-op `l` arm as
        // match/sub above and was otherwise untested under `l` anywhere
        // in this file.
        query!(br#""aaa""#, r#"capture("(?<x>a|aa|aaa)"; "l")"#,
            QueryResult::Owned(OwnedValue::Object(o)) => {
                assert_eq!(
                    o.get("x"),
                    Some(&OwnedValue::String("a".to_string())),
                    "jq binds .x to \"aaa\" — known gap, #920"
                );
            }
        );

        // #1502 review: `l` and `n` are independent no-ops/approximations
        // (`build_regex`'s `'l' => {}` arm and `global_captures`'s
        // suppress-empty search are unrelated code paths), so combining
        // them composes into a third, still-silent divergence rather than
        // either flag masking the other. Verified live against jq 1.7.1,
        // which returns "aaa" for both flag orderings (order is
        // insignificant to jq's flag parsing).
        for flags in ["ln", "nl"] {
            query!(br#""aaa""#, &format!(r#"match("a|aa|aaa"; "{flags}").string"#),
                QueryResult::Owned(OwnedValue::String(s)) => {
                    assert_eq!(s, "a", "jq returns \"aaa\" — known gap, #920, flags: {flags:?}");
                }
            );
        }
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_scan_split_splits_prepend_g_before_validating_flags_730() {
        // scan/split/splits always operate in jq's "global" mode (they find
        // or split on every match), and jq's own bootstrap prepends `g` to
        // the flags string before validation for exactly that reason -- `g`
        // has no effect on `build_regex`'s compiled pattern, so this only
        // changes the wording of an invalid-flags error. Verified live
        // against jq 1.7.1: `scan("a"; "z")` reports "gz is not a valid
        // modifier string", not "z is not a valid modifier string" -- and
        // the same holds for split/splits. Found during #730's own review:
        // the first version of this fix passed the raw flags straight to
        // `build_regex` at these three sites, producing the wrong message.
        for (filter, expected) in [
            (r#"scan("a"; "z")"#, "gz is not a valid modifier string"),
            (r#"scan("a"; "iz")"#, "giz is not a valid modifier string"),
            (r#"split("a"; "z")"#, "gz is not a valid modifier string"),
            (r#"split("a"; "iz")"#, "giz is not a valid modifier string"),
            (r#"splits("a"; "z")"#, "gz is not a valid modifier string"),
            (r#"splits("a"; "iz")"#, "giz is not a valid modifier string"),
        ] {
            query!(br#""abc""#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, expected, "filter: {filter}");
                }
            );
        }

        // Valid flags must still work correctly at all three sites (the `g`
        // prefix must not leak into compiled-pattern behavior or output).
        query!(br#""ABC""#, r#"[scan("a"; "i")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(vs, vec![OwnedValue::String("A".to_string())]);
            }
        );
        query!(br#""a1b2""#, r#"split("[0-9]"; "")"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(vs.len(), 3);
            }
        );
        query!(br#""a1b2""#, r#"[splits("[0-9]"; "")]"#,
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(vs.len(), 3);
            }
        );
    }

    // =========================================================================
    // Phase 8 Tests: Variables and Advanced Control Flow
    // =========================================================================

    #[test]
    fn test_variable_binding_as() {
        // Simple variable binding: .foo as $x | .bar + $x
        query!(br#"{"foo": 10, "bar": 5}"#, r".foo as $x | .bar + $x",
            QueryResult::Owned(OwnedValue::Int(15)) => {}
        );

        // Variable with object construction
        query!(br#"{"name": "Alice", "age": 30}"#, r#".name as $n | {name: $n, greeting: "Hello"}"#,
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("name"), Some(&OwnedValue::String("Alice".to_string())));
                assert_eq!(obj.get("greeting"), Some(&OwnedValue::String("Hello".to_string())));
            }
        );
    }

    #[test]
    fn test_variable_binding_preserves_streaming_through_a_multi_output_filter() {
        // A pipe stage after `as` binds a value is still a pipe: piping a
        // bound variable into a multi-output filter must keep streaming N
        // separate top-level outputs, the same as piping the document
        // itself would. `$doc | paths` used to collapse into one array
        // (`eval_owned_pipe` collapsed through `eval_owned_expr`, which is
        // correct for `reduce`/`foreach` but not for a plain pipe
        // continuation) where `paths` alone streams correctly.
        assert_eq!(
            outputs(br#"{"a":{"b":1}}"#, ". as $doc | $doc | paths"),
            outputs(br#"{"a":{"b":1}}"#, "paths")
        );
        assert_eq!(
            outputs(br#"{"a":{"b":1}}"#, ". as $doc | $doc | paths"),
            [r#"["a"]"#, r#"["a","b"]"#]
        );
    }

    #[test]
    fn test_reduce() {
        // Sum array elements
        query!(br"[1, 2, 3, 4, 5]", r"reduce .[] as $x (0; . + $x)",
            QueryResult::Owned(OwnedValue::Int(15)) => {}
        );

        // Count elements
        query!(br#"["a", "b", "c"]"#, r"reduce .[] as $x (0; . + 1)",
            QueryResult::Owned(OwnedValue::Int(3)) => {}
        );
    }

    #[test]
    fn test_foreach() {
        // Running sum
        query!(br"[1, 2, 3]", r"[foreach .[] as $x (0; . + $x)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 3);
                assert_eq!(arr[0], OwnedValue::Int(1));
                assert_eq!(arr[1], OwnedValue::Int(3));
                assert_eq!(arr[2], OwnedValue::Int(6));
            }
        );
    }

    /// #1201: `reduce`/`foreach`'s own `as` clause now accepts a full
    /// destructuring pattern (object or array), not just a bare `$var` --
    /// the parser now calls the same `parse_pattern` `. as PATTERN` uses,
    /// and the evaluator destructures each input element via
    /// `extract_pattern_bindings`, the same primitive `. as PATTERN` uses
    /// internally. Oracle-verified against jq 1.7.1.
    #[test]
    fn test_reduce_foreach_accept_a_full_pattern_1201() {
        query!(br#"[{"a":1},{"a":2}]"#, r"reduce .[] as {a: $a} (0; . + $a)",
            QueryResult::Owned(OwnedValue::Int(3)) => {}
        );
        query!(br"[[1,2],[3,4]]", r"reduce .[] as [$a,$b] (0; . + $a + $b)",
            QueryResult::Owned(OwnedValue::Int(10)) => {}
        );
        assert_eq!(
            outputs(
                br#"[{"a":1},{"a":2}]"#,
                r"foreach .[] as {a: $a} (0; . + $a; .)"
            ),
            ["1", "3"]
        );
        assert_eq!(
            outputs(
                br"[[1,2],[3,4]]",
                r"foreach .[] as [$a,$b] (0; . + $a + $b; .)"
            ),
            ["3", "10"]
        );
    }

    /// #1201: a pattern-match failure on one input element is a real,
    /// per-element error -- confirmed distinct from `reduce`/`foreach`'s
    /// other, already-tested error sources (INIT error, budget exceeded).
    /// `reduce` never streams partial output (only ever the final
    /// accumulator or nothing), so this is observably just an `Error`.
    #[test]
    fn test_reduce_pattern_match_failure_errors_1201() {
        query!(br#"[{"a":1},"not an object",{"a":4}]"#, r"reduce .[] as {a: $a} (0; . + $a)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("Cannot index"), "{}", e.message);
            }
        );
    }

    /// #1201: unlike `reduce`, `foreach` streams one output per step -- a
    /// pattern-match failure partway through the input must still leave
    /// every earlier step's already-produced output in place (the same
    /// "keep the prefix" contract `regression_issue_494_foreach_keeps_the_prefix_before_an_error`
    /// already pins for an ordinary per-step `UPDATE` error; #1201 needed
    /// the same guarantee to hold for this *new* per-element error source
    /// specifically, not just the pre-existing ones). Oracle-verified: real
    /// jq 1.7.1 also prints `1`, `3` before erroring on the third element.
    #[test]
    fn test_foreach_pattern_match_failure_keeps_prefix_1201() {
        query!(
            br#"[{"a":1},{"a":2},"bad",{"a":4}]"#,
            r"foreach .[] as {a: $a} (0; . + $a; .)",
            QueryResult::Partial(vs, Control::Error(e)) => {
                let strs: Vec<String> = vs.iter().map(OwnedValue::to_json).collect();
                assert_eq!(strs, ["1", "3"]);
                assert!(e.message.contains("Cannot index"), "{}", e.message);
            }
        );
    }

    /// #1201: a pattern-bound variable shadows an outer variable of the
    /// same name inside UPDATE/EXTRACT, mirroring `. as PATTERN`'s own
    /// shadowing rule (and the pre-#1201 bare-`$var` case, which already
    /// had this property via `substitute_var`'s `Expr::Reduce`/`Foreach`
    /// shadow check).
    #[test]
    fn test_reduce_pattern_shadows_outer_var_1201() {
        // If the pattern's own `$a` didn't shadow the outer `1 as $a`, this
        // would fold `0 + 1 + 1` (using the outer value both times) instead
        // of `0 + 10 + 20` (using each element's own destructured `.b`).
        query!(
            br#"[{"b":10},{"b":20}]"#,
            r"1 as $a | reduce .[] as {b: $a} (0; . + $a)",
            QueryResult::Owned(OwnedValue::Int(30)) => {}
        );

        // `substitute_var`'s `Expr::Foreach` shadow branch is a separate arm
        // from `Expr::Reduce`'s, so it needs its own case: EXTRACT must see
        // the element's own `$a` too, not the outer `1`.
        assert_eq!(
            outputs(
                br#"[{"b":10},{"b":20}]"#,
                r"1 as $a | foreach .[] as {b: $a} (0; . + $a; $a)"
            ),
            ["10", "20"]
        );
    }

    /// #1201: the two AST passes that rewrite *function* bodies --
    /// `expand_func_calls` (inlining a `def` whose body contains a
    /// `reduce`/`foreach`) and `substitute_func_param` (threading a
    /// parameter into one) -- both carry the binding `Pattern` through, and
    /// `substitute_func_param` has to make the same shadow decision
    /// `substitute_var` does. Four distinct arms, none reachable from the
    /// plain `reduce .[] as PATTERN (…)` cases above. All oracle-verified
    /// against jq 1.7.1.
    #[test]
    fn test_reduce_foreach_pattern_through_function_passes_1201() {
        // expand_func_calls: the construct is inside the inlined body.
        query!(br#"[{"a":1},{"a":2}]"#, r"def s: reduce .[] as {a:$a} (0; .+$a); s",
            QueryResult::Owned(OwnedValue::Int(3)) => {}
        );
        assert_eq!(
            outputs(
                br#"[{"a":1},{"a":2}]"#,
                r"def s: foreach .[] as {a:$a} (0; .+$a; .); s"
            ),
            ["1", "3"]
        );

        // substitute_func_param, non-shadowing: a filter parameter is
        // substituted *into* UPDATE, which the pattern's own vars don't
        // shadow (`g` is not a name the pattern binds).
        query!(br#"[{"a":1},{"a":2}]"#, r"def f(g): reduce .[] as {a:$a} (0; . + ($a|g)); f(.*2)",
            QueryResult::Owned(OwnedValue::Int(6)) => {}
        );
        assert_eq!(
            outputs(
                br#"[{"a":1},{"a":2}]"#,
                r"def f(g): foreach .[] as {a:$a} (0; . + ($a|g); .); f(.*2)"
            ),
            ["2", "6"]
        );

        // substitute_func_param, shadowing: `def f($a)` also declares the
        // filter parameter `a`, which the pattern rebinds -- so UPDATE keeps
        // the element's `$a` (9), never the argument's (100).
        query!(br#"[{"a":9}]"#, r"def f($a): reduce .[] as {a:$a} (0; .+$a); f(100)",
            QueryResult::Owned(OwnedValue::Int(9)) => {}
        );
        assert_eq!(
            outputs(
                br#"[{"a":9}]"#,
                r"def f($a): foreach .[] as {a:$a} (0; .+$a; [.,$a]); f(100)"
            ),
            ["[9,9]"]
        );
    }

    /// #1365: `reduce`/`foreach`'s `as` clause now accepts `?//`-separated
    /// pattern alternatives, matching `. as PATTERN ?// ...`'s own grammar.
    /// All four cases here are oracle-verified against jq 1.7.1.
    #[test]
    fn test_reduce_foreach_pattern_alternatives_1365() {
        // Basic fallthrough: alt1 matches but the body errors on it
        // (`$x` truthy), so alt2's bindings win instead. jq: `[null,1]`.
        query!(br#"[{"a":1}]"#, r#"reduce .[] as {a:$x} ?// {a:$y} (0; if $x then error("boom") else [$x,$y] end)"#,
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "[null,1]");
            }
        );

        // Cross-alternative null-fill: alt1 (`[$x,$y]`, an array pattern)
        // wins outright (no error), so `$y` -- only bound by alt2 -- reads
        // as `null` in the body. jq: `[1,null]`.
        query!(br#"[{"a":1}]"#, r"reduce .[] as [$x,$y] ?// {a:$x} (0; [$x,$y])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "[1,null]");
            }
        );

        // A pattern-match failure (not a body error) falls through too --
        // and, distinctly, leaves the accumulator untouched for the next
        // alternative, since UPDATE never even ran. jq: `[99,null,5]`.
        query!(b"null", r"reduce (5) as {a:$x} ?// $y (99; [., $x, $y])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "[99,null,5]");
            }
        );

        // foreach: the issue's own multi-element repro. Element 1 (`a:1`)
        // makes alt1 error, so alt2 wins (state resets to `null` first,
        // per the body-error accumulator rule); element 2 (`a:2`) matches
        // alt1 directly, continuing from element 1's real output. jq:
        // `[null,null,1]`, `[[null,null,1],2,null]`.
        assert_eq!(
            outputs(
                br#"[{"a":1},{"a":2}]"#,
                r#"foreach .[] as {a:$x} ?// {a:$y} (0; if $x==1 then error("boom") else [.,$x,$y] end; .)"#
            ),
            ["[null,null,1]", "[[null,null,1],2,null]"]
        );
    }

    /// `reduce`'s INIT/UPDATE slots now accept a top-level comma (#534): the
    /// parser previously rejected these outright, so this pins the
    /// evaluator's actual fanout/fold behavior now that it's reachable.
    #[test]
    fn test_reduce_comma_slots() {
        // UPDATE-comma: only the last output of each step becomes the next
        // accumulator (verified against jq 1.7.1: `0`).
        assert_eq!(outputs(b"[1,2,3]", "reduce .[] as $x (0; .+$x, .)"), ["0"]);

        // INIT-comma: each INIT output independently forks the whole
        // reduce, re-running over the *same* source stream. Real jq 1.7.1
        // diverges here for a reason unrelated to this evaluator: its own
        // bytecode re-enters `SOURCE` on the second INIT fork with `.`
        // already clobbered by the first fork's own iteration (`jq -n
        // 'reduce .[] as $x (0,1; .+$x)' <<<'[1,2,3]'` prints `6` then
        // errors "Cannot iterate over null"). This codebase's INIT-forking
        // doesn't share that quirk — pinning succinctly's own consistent
        // value here, not jq's, so a future refactor doesn't silently
        // change it either way without a failing test to flag it.
        assert_eq!(
            outputs(b"[1,2,3]", "reduce .[] as $x (0,1; .+$x)"),
            ["6", "7"]
        );
    }

    /// `foreach`'s INIT/UPDATE/EXTRACT slots now accept a top-level comma
    /// (#534) — same parser widening as `reduce` above.
    #[test]
    fn test_foreach_comma_slots() {
        // UPDATE-comma, no EXTRACT: every UPDATE output is emitted (not
        // folded), and the *last* one carries forward as the next state
        // (verified against jq 1.7.1: `1,0,2,0,3,0`).
        assert_eq!(
            outputs(b"[1,2,3]", "foreach .[] as $x (0; .+$x, .)"),
            ["1", "0", "2", "0", "3", "0"]
        );

        // EXTRACT-comma: EXTRACT's own outputs fan out per step (verified
        // against jq 1.7.1: `1,2,3,6,6,12`).
        assert_eq!(
            outputs(b"[1,2,3]", "foreach .[] as $x (0; .+$x; ., .*2)"),
            ["1", "2", "3", "6", "6", "12"]
        );

        // INIT-comma: same jq-engine-quirk divergence as `reduce` above
        // (jq prints `1,3,6` then errors; pinning succinctly's own value).
        assert_eq!(
            outputs(b"[1,2,3]", "foreach .[] as $x (0,1; .+$x)"),
            ["1", "3", "6", "2", "4", "7"]
        );
    }

    #[test]
    fn test_range() {
        // range(n) - generates 0 to n-1
        query!(br"null", r"[range(5)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(0),
                    OwnedValue::Int(1),
                    OwnedValue::Int(2),
                    OwnedValue::Int(3),
                    OwnedValue::Int(4),
                ]);
            }
        );

        // range(a;b) - generates a to b-1
        query!(br"null", r"[range(2;5)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(2),
                    OwnedValue::Int(3),
                    OwnedValue::Int(4),
                ]);
            }
        );

        // range(a;b;step)
        query!(br"null", r"[range(0;10;2)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(0),
                    OwnedValue::Int(2),
                    OwnedValue::Int(4),
                    OwnedValue::Int(6),
                    OwnedValue::Int(8),
                ]);
            }
        );
    }

    #[test]
    fn test_limit() {
        // limit(n; expr) - take first n outputs
        query!(br"null", r"[limit(3; range(10))]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(0),
                    OwnedValue::Int(1),
                    OwnedValue::Int(2),
                ]);
            }
        );
    }

    /// `limit`'s `expr` argument now accepts a top-level comma-generator
    /// (#155): `[limit(2;1,2,3,4)]` == `[1,2]`, matching real jq. The
    /// generator here is finite, so the existing eager
    /// evaluate-then-`take(n)` implementation already produces the correct
    /// answer without needing true short-circuiting.
    #[test]
    fn test_limit_comma_generator_argument() {
        query!(br"null", r"[limit(2;1,2,3,4)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![OwnedValue::Int(1), OwnedValue::Int(2)]);
            }
        );
    }

    #[test]
    fn test_first_last_expr() {
        // first(expr) - returns a reference to first element
        query!(br"[1, 2, 3]", r"first(.[])",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 1);
            }
        );

        // last(expr) - returns a reference to last element
        query!(br"[1, 2, 3]", r"last(.[])",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 3);
            }
        );
    }

    /// `first`/`last`'s argument now accepts a top-level comma-generator
    /// (#155): `first(1,2,3)` == `1`, `last(1,2,3)` == `3`.
    #[test]
    fn test_first_last_expr_comma_generator_argument() {
        query!(br"null", r"first(1,2,3)",
            QueryResult::Owned(
                OwnedValue::Int(n) | OwnedValue::NumberLiteral(NumberRepr::Int(n), _)
            ) => {
                assert_eq!(n, 1);
            }
        );

        query!(br"null", r"last(1,2,3)",
            QueryResult::Owned(
                OwnedValue::Int(n) | OwnedValue::NumberLiteral(NumberRepr::Int(n), _)
            ) => {
                assert_eq!(n, 3);
            }
        );
    }

    /// A single-parameter user-defined function called with a
    /// comma-generator argument (#155): `def f(x): x; f(1,2)` fans out to
    /// two outputs, matching real jq's call-by-name substitution semantics.
    #[test]
    fn test_user_function_call_with_comma_generator_argument() {
        assert_eq!(
            outputs(b"null", "def f(x): x; f(1,2)"),
            vec!["1".to_string(), "2".to_string()]
        );
    }

    #[test]
    fn test_until() {
        // until(cond; update) - iterate until condition is true
        query!(br"1", r"until(. >= 10; . * 2)",
            QueryResult::Owned(OwnedValue::Int(16)) => {}
        );
    }

    #[test]
    fn test_while() {
        // while(cond; update) - output while condition is true
        query!(br"1", r"[while(. < 10; . * 2)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(1),
                    OwnedValue::Int(2),
                    OwnedValue::Int(4),
                    OwnedValue::Int(8),
                ]);
            }
        );
    }

    /// `until`'s COND/UPDATE slots now accept a top-level comma (#534) —
    /// each additional `cond`/`update` output forks the rest of the
    /// backtracking search, verified against jq 1.7.1.
    #[test]
    fn test_until_comma_slots() {
        // UPDATE-comma: a 2-output UPDATE forks the remaining search once
        // per output (verified against jq 1.7.1: `1,10`).
        assert_eq!(outputs(b"0", "until(.>=1; .+1,.+10)"), ["1", "10"]);

        // COND-comma: a 2-output COND runs each output as its own
        // independent branch against the same state — both are truthy at
        // every state visited here, and each duplicates the branches below
        // it, so the final state (`1`) is emitted 4 times (verified against
        // jq 1.7.1).
        assert_eq!(
            outputs(b"0", "until((.>=1,.>=1); .+1)"),
            ["1", "1", "1", "1"]
        );
    }

    // The #534/#692 fork-control rewrite added several branches — INIT/INPUT
    // materialization arms in `eval_reduce`/`eval_foreach`, `eval_owned_expr_fork`,
    // `finish_fork`, and the `until_step`/`while_step` budget cap and forking-branch
    // control propagation — that the golden-file suite exercises (they run the CLI
    // binary as a subprocess, invisible to `cargo llvm-cov`'s instrumentation) but no
    // in-process unit test reaches. These pin the exact same scenarios directly
    // through `eval()` so they count.
    //
    // `$nope` (an unresolved variable) is the key to several of these: unlike
    // `error(...)`/arithmetic/type errors, `Expr::Var`'s undefined-variable arm
    // doesn't consult the ambient `optional` flag, so it's one of the few ways to
    // get a genuine `QueryResult::Error` out of `eval_single` while `optional` is
    // still `true` — everything else this codebase raises checks `optional` at its
    // own raise site and resolves straight to `None` instead (#693/#694 track this
    // ambient-`optional` architecture more broadly).

    #[test]
    fn test_reduce_update_empty_step_yields_unbound_null() {
        // `eval_owned_expr_fork`'s `QueryResult::None` arm: a zero-output UPDATE
        // step leaves the accumulator unbound, read back as `null` on the next
        // step (same scenario as the `reduce_update_unbound_null` golden case).
        assert_eq!(
            outputs(
                b"null",
                "reduce (1,2) as $x (0; if $x==2 then empty else .+$x end)"
            ),
            ["null"]
        );
    }

    #[test]
    fn eval_owned_expr_fork_empty_update_yields_no_outputs_directly() {
        let expr = parse("empty").unwrap();
        let (vals, control) = eval_owned_expr_fork::<JqSemantics>(&expr, &OwnedValue::Null, false);
        assert_eq!(vals, Vec::<OwnedValue>::new());
        assert!(control.is_none());
    }

    #[test]
    fn test_reduce_optional_swallows_update_error() {
        // `finish_fork`'s `Some(Control::Error(_)) if optional` arm: the UPDATE
        // step errors via `$nope`, and the whole `reduce` being wrapped in `?`
        // swallows it rather than letting it escape.
        assert_eq!(
            outputs(b"[1,2,3]", "(reduce .[] as $x (0; $nope))?"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_reduce_init_many_borrowed_refs() {
        // INIT `(.a,.b)` resolves to two borrowed document refs — exercises the
        // `QueryResult::Many` (not `ManyOwned`) arm of INIT materialization.
        assert_eq!(
            outputs(br#"{"a":1,"b":2}"#, "reduce range(2) as $x ((.a,.b); .+$x)"),
            ["2", "3"]
        );
    }

    #[test]
    fn test_reduce_init_empty_yields_no_output() {
        // Zero INIT outputs fork zero times, so the whole reduce produces
        // nothing at all.
        assert_eq!(
            outputs(b"[1,2,3]", "reduce .[] as $x (empty; .+$x)"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_reduce_init_error_swallowed_when_optional() {
        assert_eq!(
            outputs(b"[1,2,3]", "(reduce .[] as $x ($nope; .+$x))?"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_reduce_init_error_propagates() {
        query!(b"[1,2,3]", r"reduce .[] as $x ($nope; .+$x)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("undefined variable"));
            }
        );
    }

    #[test]
    fn test_reduce_init_break_propagates() {
        // A bare (non-`Partial`) `Break` out of INIT propagates directly out of
        // `reduce`, caught here by the enclosing `label`.
        assert_eq!(
            outputs(
                b"[1,2,3]",
                "label $lbl | reduce .[] as $x (break $lbl; .+$x)"
            ),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_reduce_init_partial_error_still_runs_the_fork_from_its_prefix_value() {
        // Corrected by #693 (was asserted the other way, unverified — see
        // below): INIT `(1,$nope)` produces `Partial([1], Control::Error(_))`
        // — under `?` only the trailing error is swallowed; the `1` INIT
        // already validly produced still forks and runs to completion,
        // matching this codebase's own "outputs already produced don't
        // vanish" contract (`partial()`/`prepend()`/`finish_fork`'s doc
        // comments) and jq's actual behavior. `$nope` (an undefined
        // variable) is a *compile*-time error in real jq, so it can't be
        // run directly there to check; re-verified the identical shape with
        // a *runtime* error instead immediately before writing this
        // assertion: `jq -n '[1,2,3] | (reduce .[] as $x ((1,error("boom"));
        // .+$x))?'` prints `7` — i.e. the fork from INIT's `1` runs
        // `1+1=2, 2+2=4, 4+3=7` to completion, exactly like this test now
        // expects. This test previously asserted the whole prefix was
        // discarded — an assumption that went unverified because, pre-#693,
        // this codebase's `Expr::Optional` self-suppressed every leaf error
        // it wrapped (including `$nope`'s—see the `$nope` explainer above),
        // so the (wrong) expectation and the (buggy) implementation
        // happened to agree.
        assert_eq!(
            outputs(b"[1,2,3]", "(reduce .[] as $x ((1,$nope); .+$x))?"),
            ["7"]
        );
    }

    #[test]
    fn test_reduce_init_partial_break_keeps_prefix() {
        // INIT `(1, break $lbl)` produces `Partial([1], Control::Break(_))` —
        // the fallback arm keeps the prefix (`1`) as the one INIT fork, and the
        // trailing break is caught by the enclosing label after that fork runs.
        assert_eq!(
            outputs(
                b"[1,2,3]",
                "label $lbl | reduce .[] as $x ((1, break $lbl); .+$x)"
            ),
            ["7"]
        );
    }

    #[test]
    fn test_foreach_input_error_swallowed_when_optional() {
        // Mirrors `eval_reduce`'s equivalent guard on the INPUT stream: an
        // immediate (non-`Partial`) error there has no prefix to salvage, so
        // `?` suppresses it.
        assert_eq!(
            outputs(b"null", "(foreach ($nope) as $x (0; .+$x))?"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_foreach_init_many_borrowed_refs() {
        assert_eq!(
            outputs(
                br#"{"a":1,"b":2}"#,
                "foreach range(2) as $x ((.a,.b); .+$x)"
            ),
            ["1", "2", "2", "3"]
        );
    }

    #[test]
    fn test_foreach_init_empty_yields_no_output() {
        assert_eq!(
            outputs(b"[1,2,3]", "foreach .[] as $x (empty; .+$x)"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_foreach_init_error_swallowed_when_optional() {
        assert_eq!(
            outputs(b"[1,2,3]", "(foreach .[] as $x ($nope; .+$x))?"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_foreach_init_error_propagates() {
        query!(b"[1,2,3]", r"foreach .[] as $x ($nope; .+$x)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("undefined variable"));
            }
        );
    }

    #[test]
    fn test_foreach_init_break_propagates() {
        assert_eq!(
            outputs(
                b"[1,2,3]",
                "label $lbl | foreach .[] as $x (break $lbl; .+$x)"
            ),
            Vec::<String>::new()
        );
    }

    // #693: `$nope` (above) is the *one* leaf that never self-suppressed via
    // the old ambient-`optional` bug, so the tests above never actually
    // exercised the failure mode from the issue — a `?`-wrapped fork
    // construct whose UPDATE/COND step raises via `error(...)` (the
    // realistic case). These pin that directly, against pinned `jq 1.7.1`
    // output.

    #[test]
    fn test_693_reduce_update_error_swallowed_by_optional() {
        // Before the fix: UPDATE's `error("boom")` self-suppressed to `None`
        // at the leaf (ambient `optional = true`), so `eval_reduce` never saw
        // an `Error`/`Partial` to abort on, and `.` (the unbound accumulator)
        // read back as `null` — `(reduce (1) as $x (0; error("boom")))?`
        // wrongly produced `null` instead of stopping with no output.
        assert_eq!(
            outputs(b"null", r#"(reduce (1) as $x (0; error("boom")))?"#),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_693_foreach_update_error_aborts_every_fork_not_just_the_current_one() {
        // Multi-output INIT `(10,20)` forks foreach over two accumulators.
        // Before the fix, fork 1's masked error "recovered" to a bound
        // `null` instead of aborting, and fork 2 — which real jq's `?` never
        // attempts once fork 1 errors — ran anyway, wrongly producing
        // `[2,21,23]`.
        assert_eq!(
            outputs(
                b"null",
                r#"(foreach (1,2) as $x ((10,20); if .==10 then error("boom") else .+$x end))?"#
            ),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_693_while_stops_at_the_masked_error_instead_of_burning_the_step_budget() {
        // Before the fix, the masked error inside `while`'s UPDATE never
        // reached `until_step`/`while_step`'s abort check, so the loop spun
        // through `0..12` repeatedly until `WHILE_UNTIL_MAX_STEPS` tripped.
        assert_eq!(
            outputs(
                b"null",
                "(10|while(. < 30; if . == 12 then error(\"boom\"), 0 else .+1 end))?"
            ),
            ["10", "11", "12"]
        );
    }

    #[test]
    fn test_693_optional_around_a_fork_construct_also_catches_an_escaping_break() {
        // `finish_fork` deliberately never special-cases `Break` (see its doc
        // comment) — catching one is the wrapping `?`/`try` boundary's job.
        // Before this fix, `Expr::Optional`'s dispatch had no such boundary
        // logic, so the `break $out` inside the `reduce` escaped straight
        // past the `?` and was caught by `label $out` one step too early,
        // wrongly producing `[1]` instead of jq's `[1,4]`.
        assert_eq!(
            outputs(
                b"null",
                "label $out | (1, (reduce (1,2) as $x (0; break $out))?, 4)"
            ),
            ["1", "4"]
        );
    }

    #[test]
    fn test_2079_reduce_ordinary_linear_fold_over_10001_elements_succeeds() {
        // #2079: a single INIT fork walking an 11,000+ element source
        // stream is an ordinary linear fold, not the multiplicative
        // fanout REDUCE_FOREACH_MAX_STEPS exists to bound — before the
        // fix, this refused with "reduce: maximum iterations exceeded"
        // where real jq (1.7.1) answers 50005000. Value confirmed live
        // against the pinned oracle.
        assert_eq!(
            outputs(b"null", r"reduce range(10001) as $x (0; .+$x)"),
            ["50005000"]
        );
    }

    #[test]
    fn test_2079_foreach_ordinary_linear_fold_over_10001_elements_succeeds() {
        // #2079: `foreach`'s two-argument form (no EXTRACT) has the same
        // single-fork linear shape as the `reduce` case above and must
        // not be capped at REDUCE_FOREACH_MAX_STEPS's old 10000 either —
        // real jq's own `[foreach range(10001) as $x (0; .+$x)] | length`
        // is `10001`.
        assert_eq!(
            outputs(b"null", r"[foreach range(10001) as $x (0; .+$x)] | length"),
            ["10001"]
        );
    }

    #[test]
    fn test_2079_foreach_with_extract_over_5001_elements_succeeds() {
        // #2079: three-argument `foreach` (explicit EXTRACT) used to cap
        // at *half* the two-argument ceiling, since EXTRACT charges the
        // same shared budget a second time per element -- a filter's
        // effective element limit should not depend on whether it passes
        // two or three arguments. Real jq's
        // `[foreach range(5001) as $x (0; .+$x; .)] | length` is `5001`.
        assert_eq!(
            outputs(
                b"null",
                r"[foreach range(5001) as $x (0; .+$x; .)] | length"
            ),
            ["5001"]
        );
    }

    #[test]
    fn test_2086_bare_arithmetic_fast_path_matches_general_evaluator() {
        // #2086: `. + <literal>` (the shape `substitute_vars` reduces a
        // fold's `$x`-bound UPDATE body to) now answers directly against
        // the `OwnedValue` tree in `eval_owned_fast_path`, instead of
        // round-tripping the whole accumulator through
        // `to_json_for_reindex` + `JsonIndex::build` every step -- see
        // that function's own doc comment. Every arm here is confirmed
        // live against jq 1.7.1 to still agree byte-for-byte with the
        // general evaluator's answer, not just internally consistent.
        assert_eq!(
            outputs(b"null", r#"reduce range(5) as $x (""; . + "a")"#),
            [r#""aaaaa""#]
        );
        assert_eq!(outputs(b"null", r"reduce range(5) as $x (0; . + 1)"), ["5"]);
        assert_eq!(
            outputs(b"null", r"reduce range(5) as $x (10; . - 1)"),
            ["5"]
        );
        assert_eq!(
            outputs(b"null", r"reduce range(5) as $x (2; . * 2)"),
            ["64"]
        );
        assert_eq!(
            outputs(b"null", r"reduce range(3) as $x (100; . / 10)"),
            ["0.1"]
        );
        assert_eq!(
            outputs(b"null", r"reduce range(3) as $x (10; . % 3)"),
            ["1"]
        );
    }

    #[test]
    fn test_2086_bare_arithmetic_fast_path_type_error_respects_optional() {
        // #2086: a type error from this arm propagates normally (exercising
        // the arm's `Err(e) => Some(Err(e))` branch) and, per #693, a `?`
        // wrapping the *whole* `reduce` doesn't set `optional: true` for the
        // fold's own per-step evaluation -- it's caught after the fact by
        // the outer `eval_try`, same as `eval_arithmetic`'s general path.
        // Both confirmed live against jq 1.7.1: unsuppressed errors,
        // suppressed emits nothing (exit 0, no output).
        query!(b"1", r#"reduce range(3) as $x (1; . + "a")"#,
            QueryResult::Error(e) => {
                assert!(e.message.contains("cannot be added"));
            }
        );
        assert_eq!(
            outputs(b"null", r#"(reduce range(3) as $x (1; . + "a"))?"#),
            Vec::<&str>::new()
        );
    }

    #[test]
    fn test_reduce_budget_exceeded_errors() {
        // #2079: genuine fanout -- 2 INIT forks (`(0,1)`), each walking
        // the same 50,001-element source stream, 100,002 UPDATE evals
        // total -- is exactly the resource-exhaustion shape #695
        // introduced this budget to bound (its own motivating example was
        // a 100,000-fork x 100,000-element reduce, 1e10 round trips).
        // Neither dimension alone exceeds the 100,000 budget (50,001 <
        // 100,000), only their product does. The first fork completes
        // (50,001 charges) and its result survives as the `Partial`
        // prefix; the second fork burns the remaining 49,999 charges
        // before erroring partway through, contributing nothing.
        query!(b"null", r"reduce range(50001) as $x ((0,1); .+$x)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix, [OwnedValue::Int(1_250_025_000)]);
                assert!(e.message.contains("reduce: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_foreach_budget_exceeded_errors() {
        // #2079: same genuine-fanout shape as the `reduce` case above --
        // 2 INIT forks over the same 50,001-element stream, no EXTRACT,
        // so only the per-input-element UPDATE charge fires. `foreach`
        // emits progressively rather than per-fork, so exactly `budget`
        // outputs survive as the `Partial` prefix regardless of which
        // fork was mid-flight when it ran out.
        query!(b"null", r"foreach range(50001) as $x ((0,1); .+1)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix.len(), REDUCE_FOREACH_MAX_STEPS);
                assert!(e.message.contains("foreach: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_foreach_extract_fanout_charged_independently_of_input_length() {
        // Two input elements (far fewer than the budget) whose UPDATE
        // each fans out to 50,001 outputs; each output gets its own
        // EXTRACT eval (#695). Pins that EXTRACT fanout is charged
        // independently of input-element count -- a design charging only
        // once per input element would never trip here, since there are
        // only two. 2 UPDATE charges (one per element) precede the
        // EXTRACT fan-out, so `REDUCE_FOREACH_MAX_STEPS - 2` outputs
        // survive before the budget is exhausted mid-fanout.
        query!(b"null", r"foreach (1,2) as $x (0; range(50001); .)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix.len(), REDUCE_FOREACH_MAX_STEPS - 2);
                assert!(e.message.contains("foreach: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_foreach_hoisted_extract_substitution_stays_aligned_per_input_val() {
        // Regression test for the #695 substitute_var hoist: EXTRACT must
        // see the *matching* input_val's substitution at each position
        // (via the idx-based lookup into the precomputed side array), not
        // a neighboring one.
        assert_eq!(
            outputs(b"null", "foreach (10,20,30) as $x (0; .+$x; [$x, .])"),
            ["[10,10]", "[20,30]", "[30,60]"]
        );
    }

    // The 11 tests below were introduced by #2077 to pin down its
    // alpha-renaming fix (`capturing_pattern_renames` and friends). #2096
    // found that mechanism was dead -- `Expr::Shared`'s opacity plus
    // `substitute_var_impl`'s eager, whole-scope `$name` resolution before
    // any downstream call is ever `Shared`-wrapped means none of these
    // constructions could actually reach a capturing binder, with or
    // without the rename (see `substitute_func_param`'s own doc comment)
    // -- and removed it. Kept here as plain regression tests: they still
    // pin the *observable* no-capture behavior jq itself guarantees, now
    // enforced structurally rather than by an explicit rename pass.
    #[test]
    fn test_func_arg_as_binder_does_not_capture_caller_var_2077() {
        // #2077 defect A: substituting `g -> $n` (the caller's own `$n`)
        // into `add`'s body must not let `add`'s own `100 as $n | ...`
        // recapture it -- confirmed against jq 1.7.1: `101`, not `200`.
        assert_eq!(
            outputs(b"null", "def add(g): 100 as $n | g + $n; 1 as $n | add($n)"),
            ["101"]
        );
    }

    #[test]
    fn test_func_arg_reduce_pattern_does_not_capture_caller_var_2077() {
        // #2077 defect A, `reduce`'s own pattern variable (not just `as`)
        // -- confirmed against jq 1.7.1: `14`, not `1`.
        assert_eq!(
            outputs(
                b"null",
                "def f(g): reduce range(2) as $x (0; . + g); 7 as $x | f($x)"
            ),
            ["14"]
        );
    }

    #[test]
    fn test_func_arg_foreach_pattern_and_extract_do_not_capture_caller_var_2077() {
        // #2077 defect A extended to `foreach`: both `update` and `extract`
        // see the pattern's binding, so both must be renamed when the
        // pattern's own name shadows a substituted-in caller variable.
        assert_eq!(
            outputs(
                b"null",
                "def f(g): [foreach (1,2) as $x (0; .; g)]; 5 as $x | f($x)"
            ),
            ["[5,5]"]
        );
    }

    #[test]
    fn test_func_arg_nested_def_dollar_param_does_not_capture_caller_var_2077() {
        // #2077 defect A, "scope note": a nested `def`'s own `$`-parameter
        // is a binder too, not just `as`/`reduce`/`foreach`/`?//` patterns.
        assert_eq!(
            outputs(
                b"null",
                "def f(g): def h($n): g + $n; h(100); 1 as $n | f($n)"
            ),
            ["101"]
        );
    }

    #[test]
    fn test_func_arg_nested_def_same_name_and_arity_shadows_param_2077() {
        // #2077 defect B: a nested `def` of the same name *and* arity as
        // the outer parameter must shadow it -- confirmed against jq
        // 1.7.1: `99`, not `1`. `expand_func_calls` leaves the reference
        // in `then` alone so the evaluator's own innermost-first def
        // lookup resolves it to the nested `def g`.
        assert_eq!(outputs(b"null", "def f(g): def g: 99; g; f(1)"), ["99"]);
    }

    #[test]
    fn test_func_arg_nested_def_different_arity_does_not_shadow_param_2077() {
        // #2077 defect B control: a nested def of a *different* arity
        // must not shadow a bare (zero-arity) parameter reference --
        // confirmed against jq 1.7.1: `1`.
        assert_eq!(outputs(b"null", "def f(g): def g(x): x; g; f(1)"), ["1"]);
    }

    #[test]
    fn test_func_arg_value_param_shadowed_by_later_as_is_not_renamed_2077() {
        // #2077 control: ordinary lexical shadowing (a *later*, unrelated
        // same-named binder in the body) is not capture and must not be
        // alpha-renamed -- confirmed against jq 1.7.1: `9`.
        assert_eq!(
            outputs(b"null", "def f($v): 9 as $v | $v; 1 as $q | f($q)"),
            ["9"]
        );
    }

    #[test]
    fn test_func_arg_array_destructure_pattern_does_not_capture_caller_var_2077() {
        // #2077 defect A, array-destructuring pattern: `$b` doesn't collide
        // with the substituted-in `$a`, only `$a` does -- confirmed against
        // jq 1.7.1: `5`, not `1`.
        assert_eq!(
            outputs(
                b"null",
                "def f(g): reduce ([1,2]) as [$a,$b] (0; . + g); 5 as $a | f($a)"
            ),
            ["5"]
        );
    }

    #[test]
    fn test_func_arg_object_destructure_pattern_does_not_capture_caller_var_2077() {
        // #2077 defect A, object-destructuring pattern -- confirmed against
        // jq 1.7.1: `5`, not the destructured `1`.
        assert_eq!(
            outputs(
                b"null",
                r#"def f(g): {"a":1,"b":2} as {a: $x, b: $y} | g; 5 as $x | f($x)"#
            ),
            ["5"]
        );
    }

    #[test]
    fn test_func_arg_as_pattern_shadowed_by_param_name_leaves_body_untouched_2077() {
        // #2077 control: an `as`-pattern that binds a name identical to the
        // outer parameter shadows it, so `body` must not be substituted at
        // all (the pre-existing `pattern_binds_var` shadow check, now on
        // the restructured `if`/`else` in the `AsPattern` arm) -- confirmed
        // against jq 1.7.1: `3` (the pattern's own $g=1, $y=2 summed),
        // regardless of what `f` was called with.
        assert_eq!(
            outputs(b"null", "def f(g): [1,2] as [$g, $y] | $g + $y; f(99)"),
            ["3"]
        );
    }

    #[test]
    fn test_func_arg_nested_def_own_param_shadows_outer_param_in_body_2077() {
        // #2077 control: a nested `def`'s own parameter of the same name
        // as the outer parameter shadows it within the nested def's own
        // `body` (the pre-existing `body_shadowed` check) -- confirmed
        // against jq 1.7.1: `1` (h's own g=1), not `2` (f's outer g).
        assert_eq!(outputs(b"null", "def f(g): def h(g): g; h(1); f(2)"), ["1"]);
    }

    #[test]
    fn test_func_arg_double_indirection_through_wrapper_still_reaches_caller_var_2096() {
        // #2096: `arg` here is already once-`Shared`-wrapped (from `wrap`'s
        // own substitution of `h -> $n`) by the time it becomes `f`'s own
        // `g`, so this exercises `Expr::Shared`'s opacity through two levels
        // of bare-parameter indirection, not just one -- confirmed against
        // jq 1.7.1: `101`, not `200`.
        assert_eq!(
            outputs(
                b"null",
                "def wrap(h): h; def f(g): 100 as $n | g + $n; 1 as $n | f(wrap($n))"
            ),
            ["101"]
        );
    }

    #[test]
    fn test_func_arg_label_break_does_not_capture_caller_var_2096() {
        // #2096: a `label`/`break` wrapped around the capturing `as` binder
        // doesn't change the Shared-opacity argument -- confirmed against
        // jq 1.7.1: `2`, not `5`.
        assert_eq!(
            outputs(
                b"null",
                "def f(g): label $out | (1,2,3) as $x | \
                 (if $x == 2 then g, break $out else empty end); \
                 5 as $x | 2 as $x | f($x)"
            ),
            ["2"]
        );
    }

    #[test]
    fn test_func_arg_nested_def_dollar_param_under_generator_does_not_capture_caller_var_2096() {
        // #2096: the capturing binder (`h`'s own `$x` parameter) sits inside
        // a generator (`(1,2,3) as $x`) that forks the body three times, so
        // the substituted-in caller `$x` must survive all three forks
        // unrenamed and uncaptured -- confirmed against jq 1.7.1: `[99,2]`
        // three times, not `[99,1]`/`[99,2]`/`[99,3]`.
        assert_eq!(
            outputs(
                b"null",
                "def f(g): (1,2,3) as $x | def h($x): [x, g]; h(99); 2 as $x | f($x)"
            ),
            ["[99,2]", "[99,2]", "[99,2]"]
        );
    }

    #[test]
    fn test_until_budget_exceeded_errors() {
        // `cond` is always falsy, so `until_step`'s single-output fast path
        // never emits anything before the `WHILE_UNTIL_MAX_STEPS` cap trips.
        query!(b"1", r"until(false; .)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("until: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_until_forking_cond_propagates_update_error() {
        // A 2-output COND forces `until_step`'s forking (non-fast-path) branch;
        // the falsy output's UPDATE errors via `$nope`, which must propagate
        // immediately rather than being dropped once the loop over `cond_vals`
        // moves on.
        query!(b"1", r"until((true,false); $nope)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix, vec![OwnedValue::Int(1)]);
                assert!(e.message.contains("undefined variable"));
            }
        );
    }

    #[test]
    fn test_while_budget_exceeded_errors() {
        // `cond` is always truthy, so `while_step`'s single-output fast path
        // emits every step before the cap trips.
        query!(b"1", r"while(true; .)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix.len(), WHILE_UNTIL_MAX_STEPS);
                assert!(prefix.iter().all(|v| *v == OwnedValue::Int(1)));
                assert!(e.message.contains("while: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_2087_until_ordinary_loop_over_50000_iterations_succeeds() {
        // #2087: a single-output, non-forking `until` loop is ordinary
        // iteration, not the backtracking fanout WHILE_UNTIL_MAX_STEPS
        // exists to bound -- before the fix, this refused with "until:
        // maximum iterations exceeded" where real jq (1.7.1) answers
        // 50000 (confirmed live against the pinned oracle).
        assert_eq!(outputs(b"null", r"0 | until(. >= 50000; . + 1)"), ["50000"]);
    }

    #[test]
    fn test_2087_while_ordinary_loop_over_50000_iterations_succeeds() {
        // #2087: `while`'s own non-forking shape has the identical bug --
        // real jq's `[0 | while(. < 50000; . + 1)] | length` is `50000`.
        assert_eq!(
            outputs(b"null", r"[0 | while(. < 50000; . + 1)] | length"),
            ["50000"]
        );
    }

    #[test]
    fn test_while_forking_cond_propagates_update_error() {
        // A 2-output COND forces `while_step`'s forking (non-fast-path) branch;
        // the first (truthy) output's UPDATE errors via `$nope`, which must
        // propagate immediately rather than being dropped once the loop over
        // `cond_vals` moves on.
        query!(b"1", r"while((true,true); $nope)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix, vec![OwnedValue::Int(1)]);
                assert!(e.message.contains("undefined variable"));
            }
        );
    }

    /// `while`'s COND/UPDATE slots now accept a top-level comma (#534) —
    /// same fanout rule as `until` above.
    #[test]
    fn test_while_comma_slots() {
        // UPDATE-comma: forks the rest of the loop per output (verified
        // against jq 1.7.1: `0,1` — the `.+10` branch immediately fails
        // `cond` and contributes nothing further).
        assert_eq!(outputs(b"0", "while(.<2; .+1,.+10)"), ["0", "1"]);

        // COND-comma: matches the already-pinned `while_cond_forks` golden
        // case's shape (`tests/data/jq-golden/cases/while_cond_forks`), kept
        // here too as a fast, in-tree eval-level regression alongside it.
        assert_eq!(
            outputs(b"null", "[while((.<3,.<1); .+1)]"),
            [r"[null,1,2,null,1,2]"]
        );
    }

    #[test]
    fn test_repeat() {
        // repeat(expr) - repeatedly evaluate expr with original input
        // jq behavior: repeat(. * 2) on input 1 produces 2, 2, 2, ...
        query!(br"1", r"[limit(5; repeat(. * 2))]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(2),
                    OwnedValue::Int(2),
                    OwnedValue::Int(2),
                    OwnedValue::Int(2),
                    OwnedValue::Int(2),
                ]);
            }
        );
    }

    #[test]
    fn test_repeat_identity() {
        // repeat(.) produces the same value infinitely
        query!(br#""hello""#, r"[limit(3; repeat(.))]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::String("hello".into()),
                    OwnedValue::String("hello".into()),
                    OwnedValue::String("hello".into()),
                ]);
            }
        );
    }

    #[test]
    fn test_recurse() {
        // Basic recurse with filter - collect all values recursively
        query!(br#"{"a": 1, "b": {"c": 2}}"#, r"[recurse | .a? // .c? // empty]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                // Should contain the values 1 and 2
                assert!(arr.len() >= 2);
            }
        );
    }

    #[test]
    fn test_isvalid() {
        // isvalid returns true for valid expressions
        query!(br#"{"a": 1}"#, r"isvalid(.a)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        // isvalid returns true for missing field (returns null, not error)
        query!(br#"{"a": 1}"#, r"isvalid(.b)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        // isvalid returns false for actual error-producing expressions
        query!(br"123", r"isvalid(.foo)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // #881 review: a genuinely empty result (zero outputs, no error --
        // `QueryResult::None`) is a distinct case from an error, and is
        // `isvalid`'s own domain to digest into `Bool(false)` directly, not
        // something `QueryResult::is_error` (checked first, see
        // `builtin_isvalid`'s own doc comment) recognizes. No existing test
        // exercised this arm in isolation before this PR -- every other
        // `isvalid` test that used to reach it did so only incidentally,
        // via a builtin's own `_ if optional => None` arm nested under
        // isvalid's old forced broadcast, and those now short-circuit
        // through `is_error()` instead (they error under the ambient,
        // unforced evaluation this PR introduced) before ever reaching
        // this arm.
        query!(br"null", r"isvalid(empty)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[test]
    fn test_isvalid_reaches_every_builtins_own_optional_guard() {
        // #881: `isvalid(EXPR)` used to evaluate `EXPR` with `optional`
        // forced `true` for the *whole* subtree, specifically so a fork
        // construct (comma/reduce/foreach) that errors partway through would
        // degrade to a detectable `None`/`Owned` shape instead of a
        // `Partial(_, Control::Error(_))` isvalid's match didn't special-case.
        // That forcing had an unintended side effect: a *later* comma
        // sibling's genuine error got silently swallowed by an *earlier*
        // sibling's already-produced output (`isvalid(1, error("x"))`
        // wrongly answered `true` — see
        // `test_isvalid_comma_sibling_error_not_masked_881` below). Fixed by
        // evaluating `EXPR` with its own ambient (unforced) `optional`,
        // matching every other builtin post-#693, and catching the
        // `Partial(_, Control::Error(_))` shape a fork construct naturally
        // produces when an unforced error interrupts it after some output —
        // exactly the shape `eval_comma` (`src/jq/eval.rs`) already builds
        // via `partial(...)`, just previously never reached because the
        // forced `optional` made the erroring leaf self-suppress to `None`
        // before `eval_comma`'s own match ever saw an `Error`.
        //
        // Every case below still reports `false` for a genuinely
        // error-producing expression — unaffected by the fix, since
        // `eval_single`'s own `QueryResult::Error`/`Partial(_,
        // Control::Error(_))` variants are caught directly, without needing
        // any builtin's own `_ if optional` guard to convert the error into
        // `None` first.
        for expr in [
            "isvalid(.[])",
            "isvalid(keys)",
            "isvalid(keys_unsorted)",
            r#"isvalid(contains("a"))"#,
            r#"isvalid(inside("a"))"#,
            "isvalid(bsearch(2))",
            // `error(...)` itself.
            r#"isvalid(error("x"))"#,
        ] {
            query!(br"1", expr,
                QueryResult::Owned(OwnedValue::Bool(false)) => {}
            );
        }

        // #881 review: real jq has no `isvalid` builtin to diff against
        // directly, but its own doc comment ("check if expr succeeds
        // without errors") matches the standard community desugaring
        // `def isvalid(f): try (f|true) catch false;` — checked live
        // against jq 1.8.2. Under that reference, `isvalid(@base64d)` on a
        // non-string input is `false` (`try @base64d catch false`:
        // `@base64d` genuinely errors on bad input in real jq, with no
        // optional-dependent "renders as empty string" behavior at all).
        // Before this fix, the `@format` builtins' own `_ if optional =>
        // Ok(String::new())` arm (`format_urid`/`format_csv`/etc,
        // `src/jq/eval.rs`) was reachable *only* through `isvalid`'s forced
        // broadcast — a succinctly-only quirk, not modeled on any real jq
        // behavior, that made `isvalid(@urid)` on bad input wrongly report
        // `true`. Now that `isvalid` no longer forces `optional`, this arm
        // is unreachable via `isvalid` (still reachable the same way every
        // other builtin's `_ if optional` arm is: a literal `?` written
        // directly after the format, e.g. `@urid?`) and these correctly
        // report `false`, matching the real-jq-verified reference semantics.
        for expr in [
            "isvalid(@urid)",
            "isvalid(@csv)",
            "isvalid(@tsv)",
            r#"isvalid(@dsv("|"))"#,
            "isvalid(@base64d)",
        ] {
            query!(br"1", expr,
                QueryResult::Owned(OwnedValue::Bool(false)) => {}
            );
        }

        // `@base64` (encode) is the odd one out here: #1096 fixed it to
        // convert a scalar to its display string first, same as `@uri`/
        // `@html` already did (`1 | @base64` => `"MQ=="`, confirmed against
        // real jq 1.7.1) -- so encoding `1` no longer errors at all, and
        // `isvalid(@base64)` on it is genuinely `true`, not `false`.
        query!(br"1", "isvalid(@base64)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        // Assignment/update/del: the write-time path traversal fails one
        // level down (`.a` is `1`, not an object, so `.b` can't be written
        // into it) — a genuine `Error`, caught directly without needing
        // `set_path`/`update_path`/`delete_at_path`'s ambient `optional`
        // forced.
        for expr in [
            "isvalid(.a.b = 5)",
            r#"isvalid(.a |= error("x"))"#,
            "isvalid(del(.a.b))",
        ] {
            query!(br#"{"a":1}"#, expr,
                QueryResult::Owned(OwnedValue::Bool(false)) => {}
            );
        }

        // reduce/foreach: `error("x")` errors unconditionally, propagating
        // as a genuine `Error`/`Partial(_, Control::Error(_))` from
        // `eval_reduce`/`eval_foreach`'s own INIT/SOURCE/fork-loop sites —
        // caught directly by `isvalid`'s match without needing any
        // optional-forcing.
        //
        // (Originally used `limit(-1;1)` as the guaranteed-to-error vehicle
        // expression here; #983 corrected `limit`'s negative-count handling
        // to match jq's own semantics -- unlimited passthrough, not an
        // error -- which stopped it erroring at all, so it no longer fits
        // this fixture's purpose. Swapped for `error("x")`, which still
        // exercises the exact same isvalid/reduce/foreach code paths.)
        for expr in [
            "isvalid(reduce (1,2) as $x (0; error(\"x\")))",
            "isvalid(reduce (1,2) as $x (error(\"x\"); .+$x))",
            "isvalid(reduce (1,2) as $x ((1,error(\"x\")); .+$x))",
            "isvalid(foreach error(\"x\") as $x (0; .+$x))",
            "isvalid(foreach (1,2) as $x (error(\"x\"); .+$x))",
        ] {
            query!(br"1", expr,
                QueryResult::Owned(OwnedValue::Bool(false)) => {}
            );
        }
    }

    /// #881: the actual bug this issue was filed for. `isvalid(1,
    /// error("x"))` and its variants used to wrongly answer `true` because
    /// `isvalid`'s forced `optional=true` made `error("x")` self-suppress to
    /// `None` before `eval_comma` ever saw the escape, and `eval_comma`
    /// treats a `None` sibling as a pure no-op — silently discarding the
    /// evidence that anything went wrong, leaving only the earlier `1`
    /// sibling's real output behind. Fixed by evaluating with ambient
    /// (unforced) `optional`, so `error("x")` now genuinely errors and
    /// `eval_comma` correctly threads it through as `Partial(vec![1],
    /// Control::Error(_))`, which `isvalid`'s match now catches. `isvalid`
    /// has no real jq to diff against, but the reference desugaring `def
    /// isvalid(f): try (f|true) catch false;` (checked live against jq
    /// 1.8.2) agrees: `isvalid(1, error("x"))` is `false` there too — real
    /// jq's `try`/`catch` stops the whole generator at the first error
    /// (confirmed separately: `(error("a"), 99)?` is empty in jq 1.8.2, `99`
    /// is never reached), matching `eval_comma`'s own "stop at the first
    /// escape" behavior once it isn't preempted by forced suppression.
    #[test]
    fn test_isvalid_comma_sibling_error_not_masked_881() {
        for expr in [
            r#"isvalid(1, error("x"))"#,
            "isvalid(1, (1|explode))",
            "isvalid(1, (1/0))",
        ] {
            query!(br"null", expr,
                QueryResult::Owned(OwnedValue::Bool(false)) => {}
            );
        }
        // A single-value argument (no comma sibling to mask anything) is
        // unaffected by the fix — still `false` when it genuinely errors.
        query!(br"null", "isvalid((1|explode))",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    /// #881 review: the same masking bug class applied equally to every
    /// other fork/multi-output site that builds a `Partial(_,
    /// Control::Error(_))` via the shared `partial(...)`/`finish_fork`
    /// machinery, not just `eval_comma` — `eval_assign`'s write-value fork,
    /// object construction's per-field fork, and `builtin_in`'s
    /// per-candidate fork (#880) all shared the identical "forced optional
    /// makes a later output's error self-suppress to `None` before the
    /// fork site ever sees it" mechanism, and are fixed by the same
    /// `isvalid` change with no changes of their own needed.
    #[test]
    // `"isvalid(in({b:1}, error(\"x\")))"` is a jq filter literal, not a
    // formatting string; clippy cannot tell the two apart from the brace
    // shape alone.
    #[allow(clippy::literal_string_with_formatting_args)]
    fn test_isvalid_other_fork_sites_error_not_masked_881() {
        // eval_assign: the write-value expression `(1, error("x"))` forks,
        // and `1` would otherwise be a real (if never-observed) write
        // before the later sibling errors.
        query!(br"null", r#"isvalid(.a = (1, error("x")))"#,
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        // Object construction: one field's value forks and a later output
        // errors after the field's earlier value would have been used.
        query!(br"null", r#"isvalid({a:1, b:("x", error("z"))})"#,
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
        // `in(xs)`: `xs`'s own generator forks, and an earlier candidate
        // already producing a real comparison result must not mask a later
        // candidate's error (mirrors `builtin_in`'s own #880 fix, checked
        // here specifically through `isvalid`'s lens).
        query!(br#""a""#, r#"isvalid(in({b:1}, error("x")))"#,
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    /// #773 established that `builtin_paths_filter`'s per-node `node_filter`
    /// evaluation must receive whatever `optional` is ambient around
    /// `isvalid`, not a hardcoded `false` — a real fix at the time, since
    /// pre-#773 code silently dropped `optional` entirely on this specific
    /// path. #881 review: with `isvalid` no longer forcing `optional=true`
    /// broadcast (see `test_isvalid_reaches_every_builtins_own_optional_guard`
    /// above), `.foo` on a scalar node here now genuinely errors instead of
    /// being swallowed — matching real jq exactly:
    /// `{"a":1,"b":2} | [paths(.foo, true)]` itself errors in real jq 1.8.2
    /// ("Cannot index number with string (\"foo\")"), and under the
    /// reference `def isvalid(f): try (f|true) catch false;` desugaring
    /// (checked live against jq 1.8.2), `isvalid(paths(.foo, true))` there
    /// is `false`, not `true`. The pre-#881 test pinned `true` — a
    /// succinctly-only divergence from real jq that #773's own (correct)
    /// optional-threading fix made *reachable* without being its cause;
    /// #881's broader fix (no longer forcing `optional` at all) corrects it.
    #[test]
    fn test_isvalid_paths_filter_node_error_not_swallowed_881() {
        query!(br#"{"a":1,"b":2}"#, r"isvalid(paths(.foo, true))",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    /// #1559: `each_paths_filter`'s root `node_filter` pre-check
    /// (`eval_owned_expr_ctrl`) silently swallowed a trailing error for any
    /// root with *no* non-root paths -- a scalar or an empty container --
    /// since only a non-root path gets independently re-checked by the
    /// per-node fan-out loop below the pre-check. Live-verified against jq
    /// 1.7.1: both shapes raise `boom` there; this pinned `[]`/`0` (no
    /// output, exit 0) instead.
    #[test]
    fn test_paths_filter_root_pre_check_raises_trailing_error_scalar_and_empty_root_1559() {
        query!(b"1", r#"[paths(true, error("boom"))]"#,
            QueryResult::Error(e) => { assert_eq!(e.message, "boom"); }
        );
        query!(b"{}", r#"[paths(true, error("boom"))]"#,
            QueryResult::Error(e) => { assert_eq!(e.message, "boom"); }
        );
        // Regression guard: a root with a non-root path still raises too
        // (this shape already worked before #1559's fix to this call site).
        query!(b"[1]", r#"[paths(true, error("boom"))]"#,
            QueryResult::Error(e) => { assert_eq!(e.message, "boom"); }
        );
    }

    // =========================================================================
    // Phase 9 Tests: Destructuring and Function Definitions
    // =========================================================================

    #[test]
    fn test_destructuring_object_pattern() {
        // Object destructuring: . as {name: $n, age: $a} | ...
        query!(br#"{"name": "Alice", "age": 30}"#, r#". as {name: $n, age: $a} | "\($n) is \($a)""#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "Alice is 30");
            }
        );
    }

    #[test]
    fn test_destructuring_array_pattern() {
        // Array destructuring: . as [$first, $second] | ...
        query!(br"[1, 2, 3]", r". as [$a, $b] | $a + $b",
            QueryResult::Owned(OwnedValue::Int(3)) => {}
        );
    }

    #[test]
    fn test_destructuring_nested_pattern() {
        // Nested destructuring
        query!(br#"{"user": {"name": "Bob", "id": 42}}"#, r". as {user: {name: $n}} | $n",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "Bob");
            }
        );
    }

    #[test]
    fn test_destructuring_var_and_pattern_1204() {
        // `{$x: Pattern}` (#1204): binds $x to the whole value AND
        // destructures the same value again via Pattern.
        query!(br#"{"x":5,"a":1}"#, r". as {$x: $y} | [$x,$y]",
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(vs, vec![OwnedValue::Int(5), OwnedValue::Int(5)]);
            }
        );
    }

    #[test]
    fn test_destructuring_object_pattern_null_propagates_through_nested_object_1239() {
        // `.x` is absent (-> null); real jq lets that null absorb the
        // nested `{y: $y}` destructuring instead of erroring (#1239).
        query!(br#"{"a":1}"#, r". as {x: {y: $y}} | $y",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
    }

    #[test]
    fn test_destructuring_object_pattern_null_propagates_through_nested_array_1239() {
        query!(br#"{"a":1}"#, r". as {x: [$y]} | $y",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
    }

    #[test]
    fn test_destructuring_object_pattern_null_binds_every_nested_var_1239() {
        // A multi-level, multi-var nested pattern under an absent field --
        // every variable it would have bound resolves to null, not just the
        // first one reached.
        query!(br#"{"a":1}"#, r". as {x: {y: $y, z: [$p, $q]}} | [$y, $p, $q]",
            QueryResult::Owned(OwnedValue::Array(vs)) => {
                assert_eq!(vs, vec![OwnedValue::Null, OwnedValue::Null, OwnedValue::Null]);
            }
        );
    }

    #[test]
    fn test_destructuring_object_pattern_non_null_non_object_still_errors_1239() {
        // Control: null-tolerance doesn't widen into general leniency -- a
        // genuinely wrong-typed value (not null, not an object) still hard-
        // errors, same as before this fix.
        query!(br#"{"x":"notobj"}"#, r". as {x: {y: $y}} | $y",
            QueryResult::Error(_) => {}
        );
    }

    #[test]
    fn test_function_def_simple() {
        // Simple function definition without parameters
        query!(br"5", r"def double: . * 2; double",
            QueryResult::Owned(OwnedValue::Int(10)) => {}
        );
    }

    #[test]
    fn test_function_def_with_params() {
        // Function with parameters (using 'addtwo' to avoid conflict with builtin 'add')
        query!(br"null", r"def addtwo(a; b): a + b; addtwo(3; 4)",
            QueryResult::Owned(OwnedValue::Int(7)) => {}
        );
    }

    #[test]
    fn test_function_def_chained() {
        // Single def, then use in pipe
        query!(br"5", r"def inc: . + 1; . | inc",
            QueryResult::Owned(OwnedValue::Int(6)) => {}
        );

        // Two defs, use only second - this exercises nested func def
        query!(br"5", r"def double: . * 2; def inc: . + 1; inc",
            QueryResult::Owned(OwnedValue::Int(6)) => {}
        );

        // Two defs, use only first
        query!(br"5", r"def double: . * 2; def inc: . + 1; double",
            QueryResult::Owned(OwnedValue::Int(10)) => {}
        );

        // This should work: use both in a pipe, but inc is defined first
        // (so inc isn't nested inside double's scope)
        query!(br"5", r"def inc: . + 1; def double: . * 2; double | inc",
            QueryResult::Owned(OwnedValue::Int(11)) => {}
        );
    }

    #[test]
    fn test_function_uses_input() {
        // Function that uses the input value
        query!(br#"{"x": 10}"#, r"def getx: .x; getx",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 10);
            }
        );
    }

    #[test]
    fn test_function_with_filter_param() {
        // Function with filter parameter (jq-style)
        query!(br"[1, 2, 3]", r"def apply(f): map(f); apply(. * 2)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(2),
                    OwnedValue::Int(4),
                    OwnedValue::Int(6),
                ]);
            }
        );
    }

    // Phase 10 tests

    #[test]
    fn test_floor() {
        query!(b"3.7", "floor", QueryResult::Owned(OwnedValue::Int(n)) => {
            assert_eq!(n, 3);
        });
        query!(b"-3.2", "floor", QueryResult::Owned(OwnedValue::Int(n)) => {
            assert_eq!(n, -4);
        });
    }

    #[test]
    fn test_ceil() {
        query!(b"3.2", "ceil", QueryResult::Owned(OwnedValue::Int(n)) => {
            assert_eq!(n, 4);
        });
        query!(b"-3.7", "ceil", QueryResult::Owned(OwnedValue::Int(n)) => {
            assert_eq!(n, -3);
        });
    }

    #[test]
    fn test_round() {
        query!(b"3.4", "round", QueryResult::Owned(OwnedValue::Int(n)) => {
            assert_eq!(n, 3);
        });
        query!(b"3.5", "round", QueryResult::Owned(OwnedValue::Int(n)) => {
            assert_eq!(n, 4);
        });
    }

    #[test]
    fn test_trunc() {
        // Truncation toward zero — distinct from floor at negative values,
        // where floor(-2.7) == -3 but trunc(-2.7) == -2.
        query!(b"2.7", "trunc", QueryResult::Owned(OwnedValue::Int(n)) => {
            assert_eq!(n, 2);
        });
        query!(b"-2.7", "trunc", QueryResult::Owned(OwnedValue::Int(n)) => {
            assert_eq!(n, -2);
        });
    }

    #[test]
    fn test_sqrt() {
        query!(b"9", "sqrt", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 3.0).abs() < f64::EPSILON);
        });
        query!(b"2", "sqrt", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - core::f64::consts::SQRT_2).abs() < 1e-10);
        });
    }

    #[test]
    fn test_fabs() {
        query!(b"-5", "fabs", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 5.0).abs() < f64::EPSILON);
        });
        query!(b"5", "fabs", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 5.0).abs() < f64::EPSILON);
        });
    }

    #[test]
    fn test_log() {
        query!(b"2.718281828459045", "log", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 1.0).abs() < 1e-10);
        });
    }

    #[test]
    fn test_exp() {
        query!(b"1", "exp", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - core::f64::consts::E).abs() < 1e-10);
        });
    }

    #[test]
    fn test_pow() {
        query!(b"2", "pow(.; 3)", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 8.0).abs() < f64::EPSILON);
        });
    }

    #[test]
    fn test_sin_cos_tan() {
        query!(b"0", "sin", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!(n.abs() < f64::EPSILON);
        });
        query!(b"0", "cos", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 1.0).abs() < f64::EPSILON);
        });
        query!(b"0", "tan", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!(n.abs() < f64::EPSILON);
        });
    }

    #[test]
    fn test_infinite_nan() {
        query!(b"null", "infinite", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!(n.is_infinite() && n > 0.0);
        });
        query!(b"null", "nan", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!(n.is_nan());
        });
    }

    #[test]
    fn test_nan_survives_reindex_bridge_472() {
        // `nan` alone is a native `OwnedValue::Float(NaN)` (`test_infinite_nan`
        // above), but every filter here pipes that result through at least one
        // `to_json_for_reindex`/reparse hop before the next stage runs. Before
        // #472's fix that hop lost the NaN-ness (JSON has no NaN literal, and
        // the bridge fell back to `"null"`), so these all disagreed with real
        // jq. Every expected value is jq-1.7.1's own output for the same query.
        query!(b"null", "nan | isnan", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(b);
        });
        query!(b"null", "nan | tonumber | isnan", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(b);
        });
        query!(b"null", "nan | length | isnan", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(b);
        });
        query!(b"null", "[nan] | sort | .[0] | isnan", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(b);
        });
        query!(b"null", "[nan,1] | bsearch(nan)", QueryResult::Owned(OwnedValue::Int(idx)) => {
            assert_eq!(idx, -2);
        });
        query!(b"null", "[nan,nan] | bsearch(nan)", QueryResult::Owned(OwnedValue::Int(idx)) => {
            assert_eq!(idx, -3);
        });
        query!(b"null", "[nan,nan,nan] | bsearch(nan)", QueryResult::Owned(OwnedValue::Int(idx)) => {
            assert_eq!(idx, -4);
        });
    }

    #[test]
    fn test_bsearch_single_nan_haystack_known_divergence_472() {
        // Discovered while fixing #472, but a separate, narrower bug: not
        // fixed by NaN-survival, and not a reindex-bridge problem at all.
        //
        // `compare_values` (shared with `sort`/`unique`/`group_by`, #421)
        // treats every NaN as strictly less than every other value,
        // including another NaN, so `builtin_bsearch`'s binary search always
        // walks *past* a NaN run without ever reporting it "found" -- and
        // for every haystack tested except a single-element one, that
        // matches jq's own answer exactly: `[nan,nan]|bsearch(nan)` is `-3`
        // in both, `[nan,nan,nan]|bsearch(nan)` is `-4` in both (see
        // `test_nan_survives_reindex_bridge_472`).
        //
        // `[nan]|bsearch(nan)` alone is jq's `-1`, not `-2`. A single probe
        // can only take one branch, so matching jq here would require
        // `compare_values(NaN, NaN)` to answer `Greater` for a one-element
        // haystack and `Less` for every longer one -- impossible for any
        // comparator that doesn't see the surrounding array. This means
        // jq's own answer isn't a coherent "insertion point" under any
        // total order either; it's an artifact of whatever raw-double
        // comparisons jq's particular C probe sequence happens to hit for a
        // "sorted" array that (containing NaN) isn't actually well-ordered
        // to begin with -- exactly the not-a-strict-weak-order territory
        // `compare_values`'s own doc comment already flags. Not worth
        // chasing bug-for-bug; pinning succinctly's current, consistent
        // answer here rather than leaving it silently uncovered.
        query!(b"null", "[nan] | bsearch(nan)", QueryResult::Owned(OwnedValue::Int(idx)) => {
            assert_eq!(idx, -2);
        });
    }

    #[test]
    fn test_nan_math_builtins_survive_reindex_bridge_613() {
        // Companion to `test_nan_survives_reindex_bridge_472`: that fix covered
        // `to_owned_lossy`/`length`/`tonumber`/`isnan`, but `get_float_value` and
        // `get_number_from_result` -- which back the whole math-builtin family --
        // still read `n.as_f64()` directly with no sentinel check, so a bridged
        // NaN through any of these errored ("invalid number") instead of
        // propagating. Every expected value is jq-1.7.1's own output for the
        // same query.
        for filter in [
            "nan | floor | isnan",
            "nan | ceil | isnan",
            "nan | round | isnan",
            "nan | trunc | isnan",
            "nan | sqrt | isnan",
            "nan | fabs | isnan",
            "nan | log | isnan",
            "nan | log10 | isnan",
            "nan | log2 | isnan",
            "nan | exp | isnan",
            "nan | exp10 | isnan",
            "nan | exp2 | isnan",
            "pow(nan; 2) | isnan",
            "pow(2; nan) | isnan",
            "nan | sin | isnan", // trig shares get_float_value; fixed for free
        ] {
            query!(b"null", filter, QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b, "expected {filter:?} to be NaN");
            });
        }

        // floor/ceil/round/trunc wrap their result as `OwnedValue::Int`, and
        // `NaN as i64` saturates to 0 -- confirm the NaN case is special-cased
        // before that cast so `type` stays "number", not silently coerced.
        query!(b"null", "nan | floor | type", QueryResult::Owned(OwnedValue::String(s)) => {
            assert_eq!(s, "number");
        });
    }

    #[test]
    fn test_nan_normals_isinfinite_isnormal_already_correct_613() {
        // Unlike the math builtins above, `normals`/`isinfinite`/`isnormal`
        // already match real jq for a bridged NaN today (verified against
        // jq-1.7.1): the missing sentinel check makes `n.as_f64()` fail, and
        // each of these three happens to treat that failure the same way jq
        // treats NaN itself. Pinned here so it can't silently regress while
        // nearby code is being touched for #613.
        query!(b"null", "nan | normals", QueryResult::None => {});
        query!(b"null", "nan | isinfinite", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(!b);
        });
        query!(b"null", "nan | isnormal", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(!b);
        });
    }

    #[test]
    fn test_nan_sentinel_collision_with_real_document_is_well_defined() {
        // #472's design tradeoff, made explicit: `NAN_SENTINEL` is reserved
        // and unparseable by construction
        // (`test_nan_sentinel_is_unparseable_as_a_real_number`), but it's
        // still just number-shaped text, not a value that only the reindex
        // bridge can produce -- a *real* document containing this exact byte
        // sequence is affected too. Pin that this is well-defined (treated
        // as NaN, consistently across builtins) rather than a panic or a
        // silently different fallback per call site.
        query!(br"9e999e999", "isnan", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(b);
        });
        query!(br"9e999e999", "length", QueryResult::Owned(OwnedValue::Float(f)) => {
            assert!(f.is_nan());
        });
    }

    #[test]
    fn test_isinfinite_isnan_isnormal() {
        query!(b"1.0", "isinfinite", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(!b);
        });
        query!(b"1.0", "isnan", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(!b);
        });
        query!(b"1.0", "isnormal", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(b);
        });
        query!(b"1.0", "isfinite", QueryResult::Owned(OwnedValue::Bool(b)) => {
            assert!(b);
        });
    }

    #[test]
    fn test_trim() {
        query!(br#""  hello world  ""#, "trim", QueryResult::Owned(OwnedValue::String(s)) => {
            assert_eq!(s, "hello world");
        });

        // Interior whitespace is preserved; only leading/trailing is stripped.
        query!(br#""  a  b  ""#, "trim", QueryResult::Owned(OwnedValue::String(s)) => {
            assert_eq!(s, "a  b");
        });

        // Already-trimmed input is a no-op.
        query!(br#""hello""#, "trim", QueryResult::Owned(OwnedValue::String(s)) => {
            assert_eq!(s, "hello");
        });

        // Non-string input errors.
        query!(b"1", "trim",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "trim requires string");
            }
        );
    }

