    #[test]
    fn test_localtime_structure() {
        // localtime is timezone-dependent, so assert only the 8-field structure.
        // This still exercises the hour/minute/second/weekday computation
        // regardless of the host's $TZ.
        query!(b"0", r"localtime",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 8);
            }
        );
    }

    #[test]
    fn test_gmtime() {
        // Unix epoch (Jan 1, 1970 00:00:00 UTC)
        query!(b"0", r"gmtime",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 8);
                assert_eq!(arr[0], OwnedValue::Int(1970)); // year
                assert_eq!(arr[1], OwnedValue::Int(0));    // month (0-indexed)
                assert_eq!(arr[2], OwnedValue::Int(1));    // day
                assert_eq!(arr[3], OwnedValue::Int(0));    // hour
                assert_eq!(arr[4], OwnedValue::Int(0));    // minute
                assert_eq!(arr[5], OwnedValue::Int(0));    // second
                assert_eq!(arr[6], OwnedValue::Int(4));    // weekday (Thursday)
                assert_eq!(arr[7], OwnedValue::Int(0));    // yearday
            }
        );
    }

    #[test]
    fn test_datetime_builtins_optional_true_suppresses_extreme_magnitude_error() {
        // `?` alone can't reach these builtins' own `optional`-guarded
        // arms: `E?` (`eval_try`) catches `E`'s *result* from the outside,
        // evaluated with whatever `optional` was already ambient — it does
        // not force `optional = true` down into a bare builtin call (#693)
        // — so this exercises the guards directly the same way this file
        // already tests other builtins' `optional` arms elsewhere (see
        // `eval_single::<Vec<u64>, JqSemantics>(&expr, cursor.value(),
        // true)` a few tests up). `local_offset` defaults to 0 in this
        // test environment (no `TZ` set), so `localtime`'s own
        // `checked_add` overflow guard isn't reachable this way — that arm
        // only matters with a non-default `TZ` and a timestamp within
        // `local_offset` of `i64::MIN`, not practically triggerable
        // through the public jq CLI/query surface.
        let json: &[u8] = b"-1e300";
        let index = JsonIndex::build(json);
        let cursor = index.root(json);

        assert!(matches!(
            builtin_gmtime::<Vec<u64>>(cursor.value(), true),
            QueryResult::None
        ));
        assert!(matches!(
            builtin_localtime::<Vec<u64>>(cursor.value(), true),
            QueryResult::None
        ));
        assert!(matches!(
            builtin_todate::<Vec<u64>>(cursor.value(), true),
            QueryResult::None
        ));

        let fmt_expr = parse(r#""%Y-%m-%d""#).unwrap();
        assert!(matches!(
            builtin_strftime::<Vec<u64>, JqSemantics>(&fmt_expr, cursor.value(), true),
            QueryResult::None
        ));

        let zone_expr = parse(r#""UTC""#).unwrap();
        assert!(matches!(
            builtin_tz::<Vec<u64>, JqSemantics>(&zone_expr, cursor.value(), true),
            QueryResult::None
        ));
    }

    #[test]
    fn test_datetime_extreme_magnitude_errors_instead_of_panicking() {
        // Before #869's fix, an extreme-magnitude timestamp made
        // `broken_down_time_from_unix_secs`'s `secs - 86399` underflow
        // `i64` — a debug-build panic, or (release, overflow-checks off) a
        // silently wrong result. Verified against real jq (jq-1.7.1): jq
        // itself cleanly errors on these inputs with this exact message.
        const MSG: &str = "error converting number of seconds since epoch to datetime";

        query!(b"-1e300", r"gmtime", QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"1e300", r"gmtime", QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"-1e300", r"localtime", QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"-1e300", r"todate", QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"-1e300", r#"tz("UTC")"#, QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"-1e300", r#"strftime("%Y-%m-%d")"#, QueryResult::Error(e) => assert_eq!(e.message, MSG));

        // `?` suppresses it, same as any other builtin error.
        query!(b"-1e300", r"gmtime?", QueryResult::None => {});
        query!(b"-1e300", r#"strftime("%Y-%m-%d")?"#, QueryResult::None => {});
    }

    #[test]
    fn test_datetime_year_out_of_i32_range_errors_cleanly() {
        // Empirically bisected against real jq (jq-1.7.1) in this range:
        // `6e16`/`-6e16` succeed in jq (and produce this exact date,
        // confirmed byte-for-byte against `jq`), `7e16`/`-7e16` error, in
        // both directions — real jq's *exact* cutoff is not this clean
        // (see the divergence test below and `broken_down_time_from_unix_secs`'s
        // doc comment), but the two agree closely here.
        const MSG: &str = "error converting number of seconds since epoch to datetime";

        query!(b"6e16", r"gmtime",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr[0], OwnedValue::Int(1_901_326_280));
            }
        );
        query!(b"-6e16", r"gmtime",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr[0], OwnedValue::Int(-1_901_322_341));
            }
        );
        query!(b"7e16", r"gmtime", QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"-7e16", r"gmtime", QueryResult::Error(e) => assert_eq!(e.message, MSG));
    }

    #[test]
    fn test_datetime_i32_boundary_deliberately_diverges_from_jqs_own_wraparound_quirk() {
        // Real jq's own boundary is an asymmetric C-implementation
        // artifact, not a clean "year fits i32" rule — confirmed directly
        // against jq-1.7.1, in both directions:
        //   `67767976233532800 | gmtime` (a would-be year of i32::MAX + 1)
        //   *succeeds* in real jq, silently wrapping to `year: i32::MIN`.
        //   Reproducing that wraparound would reintroduce exactly the
        //   "silently wrong value" failure mode #869 exists to eliminate,
        //   so it's intentionally not replicated — this errors instead.
        //   `-67768100536262402 | gmtime` conversely *errors* in real jq,
        //   despite its computed year (`-2147483647`) fitting `i32` —
        //   jq's cutoff sits at a different, smaller magnitude than i32's
        //   own range on the negative side. This succeeds here instead,
        //   under-erroring relative to jq rather than over-erroring; a
        //   documented, deliberate simplification, not a bug.
        const MSG: &str = "error converting number of seconds since epoch to datetime";

        query!(b"67767976233532800", r"gmtime", QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"-67768100536262402", r"gmtime",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr[0], OwnedValue::Int(-2_147_483_647));
            }
        );
    }

    #[test]
    fn test_datetime_nan_and_subsecond_negative_already_match_jq() {
        // #869 suspected these were also bugs, but checking the pinned jq
        // oracle (jq-1.7.1) directly showed both already match real jq
        // exactly — do not "fix" either into diverging from jq:
        //  - NaN silently maps to the Unix epoch (not an error) in jq too.
        //  - A sub-second-negative timestamp truncates toward zero in jq
        //    (not floor semantics — `-0.5` maps to `secs=0`, not `-1`).
        query!(b"null", r#"(nan) | strftime("%Y-%m-%d")"#,
            QueryResult::Owned(OwnedValue::String(s)) => assert_eq!(s, "1970-01-01")
        );
        query!(b"null", r#"(-0.5) | strftime("%Y-%m-%dT%H:%M:%SZ")"#,
            QueryResult::Owned(OwnedValue::String(s)) => assert_eq!(s, "1970-01-01T00:00:00Z")
        );
    }

    #[test]
    fn test_mktime_and_strftime_s_error_instead_of_panicking_on_overflow_893() {
        // #893: unix_secs_from_broken_down_time's era/day/hour/minute/second
        // arithmetic panicked on overflow for a user-controlled
        // broken-down-time array element — the mirror-image bug of #869 on
        // the opposite (broken-down-time -> seconds) conversion direction.
        // Every field independently reachable through this exact panic
        // before the fix (confirmed by hand, one field at a time, against
        // the pre-fix code): year, month, day, hour, minute, and second.
        // Deliberately a different message than #869's own tests use
        // (`datetime_out_of_range`, the opposite conversion direction) —
        // real jq has no equivalent error for *this* direction at all (it
        // silently computes a wrapped/nonsensical result instead), so
        // there's no oracle text to match; see
        // `EvalError::broken_down_time_out_of_range`'s doc comment.
        const MSG: &str = "mktime/strftime: broken-down time value out of representable range";

        query!(b"null", r"[9223372036854775807,0,1,0,0,0,0,0] | mktime",
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[9223372036854775807,0,1,0,0,0,0,0] | strftime("%s")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        // Extreme *negative* year: takes `era`'s negative-`y` branch (the
        // positive cases above never do), whose own `y.checked_sub(399)`
        // overflows for a `y` this close to `i64::MIN`.
        query!(b"null", r"[-9223372036854775808,6,1,0,0,0,0,0] | mktime",
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r"[2020,9223372036854775807,1,0,0,0,0,0] | mktime",
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r"[2020,0,9223372036854775807,0,0,0,0,0] | mktime",
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r"[2020,0,1,9223372036854775807,0,0,0,0] | mktime",
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r"[2020,0,1,0,9223372036854775807,0,0,0] | mktime",
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r"[2020,0,1,0,0,9223372036854775807,0,0] | mktime",
            QueryResult::Error(e) => assert_eq!(e.message, MSG));

        // `?` suppresses it, same as #869's precedent.
        query!(b"null", r"[9223372036854775807,0,1,0,0,0,0,0] | mktime?", QueryResult::None => {});
        query!(b"null", r#"[9223372036854775807,0,1,0,0,0,0,0] | strftime("%s")?"#, QueryResult::None => {});

        // Ordinary dates still round-trip correctly (regression guard).
        query!(b"null", r"[2024,5,15,10,30,0,0,0] | mktime",
            QueryResult::Owned(OwnedValue::Float(f)) => assert_eq!(f, 1_718_447_400.0));

        // `strftime`'s array branch computes `month` (its own `get_int(1) +
        // 1` step) eagerly for every format string, not just `%s` — an
        // extreme month here panicked independently of
        // unix_secs_from_broken_down_time, before this same overflow ever
        // reaches that function.
        query!(b"null", r#"[2020,9223372036854775807,1,0,0,0,0,0] | strftime("%Y")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        // `?` suppresses the array branch's own month-overflow error too
        // (distinct site from the `%s`-via-unix_secs_from_broken_down_time
        // case above — both now share `checked_month_index`, #912).
        query!(b"null", r#"[2020,9223372036854775807,1,0,0,0,0,0] | strftime("%Y")?"#,
            QueryResult::None => {});
    }

    #[test]
    fn test_strftime_week_and_yearday_specifiers_error_instead_of_panicking_on_overflow_911() {
        // #911 review round: the initial #893 fix hardened
        // unix_secs_from_broken_down_time and the two `month + 1` sites,
        // but format_strftime's %j/%U/%W/%V/%G/%g specifiers each do their
        // own independent unchecked arithmetic on the same user-controlled
        // `weekday`/`yearday`/`year` array fields (indices 6/7/0) and
        // panicked just the same. `iso_week_date`/`weeks_in_iso_year`
        // (backing %V/%G/%g) needed the identical treatment.
        const MSG: &str = "mktime/strftime: broken-down time value out of representable range";

        query!(b"null", r#"[2020,0,1,0,0,0,0,9223372036854775807] | strftime("%j")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[2020,0,1,0,0,0,-9223372036854775808,0] | strftime("%U")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[2020,0,1,0,0,0,9223372036854775807,0] | strftime("%W")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[2020,0,1,0,0,0,0,-9223372036854775808] | strftime("%W")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[9223372036854775807,0,1,0,0,0,0,0] | strftime("%V")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[-9223372036854775808,0,1,0,0,0,0,0] | strftime("%V")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[2020,0,1,0,0,0,0,9223372036854775807] | strftime("%V")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[9223372036854775807,0,1,0,0,0,0,0] | strftime("%G")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));
        query!(b"null", r#"[9223372036854775807,0,1,0,0,0,0,0] | strftime("%g")"#,
            QueryResult::Error(e) => assert_eq!(e.message, MSG));

        // `?` suppresses it, same as every other overflow site in this file.
        query!(b"null", r#"[2020,0,1,0,0,0,0,9223372036854775807] | strftime("%j")?"#, QueryResult::None => {});

        // Ordinary dates still produce the exact same output as real jq
        // (byte-for-byte verified against the pinned jq-1.7.1 oracle).
        query!(b"null", r#"[2024,5,15,10,30,0,6,166] | strftime("%j %U %W %V %G %g")"#,
            QueryResult::Owned(OwnedValue::String(s)) => assert_eq!(s, "167 23 24 24 2024 24"));
    }

    // `#[cfg(feature = "std")]`: `parse_simple_tz_offset` itself is
    // `std`-only (it exists solely to parse `std::env::var("TZ")`), so
    // this test cannot compile under `no_std` at all.
    #[test]
    #[cfg(feature = "std")]
    fn test_parse_simple_tz_offset_errors_gracefully_on_overflow_894() {
        // #894: `hours * 3600`/`minutes * 60`/the final sign multiply were
        // unchecked, panicking on a malformed/adversarial `TZ` env var
        // (reachable independently of the timestamp being converted, since
        // `TZ` parsing happens before any timestamp arithmetic runs). Tested
        // directly against the private helper rather than through the `TZ`
        // env var + `localtime` builtin, since mutating process-global env
        // vars in a parallel test binary is inherently racy.
        assert_eq!(parse_simple_tz_offset("EST9999999999999999"), None); // hours overflow
        assert_eq!(parse_simple_tz_offset("EST-9999999999999999"), None); // hours overflow, negative
        assert_eq!(
            parse_simple_tz_offset("EST1:999999999999999999"),
            None // minutes overflow (hours alone is in range)
        );

        // Normal input still resolves correctly (positive TZ = west of UTC
        // = negative offset applied, per this function's own doc comment).
        assert_eq!(parse_simple_tz_offset("EST5EDT"), Some(-5 * 3600));
        assert_eq!(parse_simple_tz_offset("EST-5EDT"), Some(5 * 3600));
    }

    #[test]
    fn test_dst_heuristics_use_floor_not_truncating_division_pre_1970_895() {
        // #895: each of is_dst_us_eastern/is_dst_europe/is_dst_australia
        // hand-duplicated the pre-#889 truncating `secs / 86400` instead of
        // the shared, floor-corrected broken_down_time_from_unix_secs — so
        // a pre-1970 timestamp not exactly on a day boundary could resolve
        // to the *next* day's civil date, giving the wrong DST answer right
        // at a transition boundary.
        //
        // -25833601.0 is one second before 1969-03-08T00:00:00Z (verified
        // via gmtime: [1969,2,7,23,59,59,...], 0-indexed month=2 is March,
        // day=7). The old truncating division computed day=8 here (the
        // *next* day) instead of day=7, wrongly reporting US-Eastern DST
        // (which starts "day >= 8" in March) a full second early.
        assert!(!is_dst_us_eastern(-25_833_601.0)); // Mar 7 23:59:59 -> day 7, not yet DST
        assert!(is_dst_us_eastern(-25_833_600.0)); // Mar 8 00:00:00 -> day 8, DST starts

        // Same mechanism, Europe's "day >= 25" March boundary.
        // 1969-03-25T00:00:00Z: gmtime confirms [1969,2,25,0,0,0,...].
        query!(b"-24364800", r"gmtime",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr[1], OwnedValue::Int(2));
                assert_eq!(arr[2], OwnedValue::Int(25));
            }
        );
        assert!(!is_dst_europe(-24_364_801.0)); // Mar 24 23:59:59 -> day 24, not yet DST
        assert!(is_dst_europe(-24_364_800.0)); // Mar 25 00:00:00 -> day 25, DST starts

        // Same mechanism, Australia's "day >= 7" October boundary (1969-10-07T00:00:00Z).
        assert!(!is_dst_australia(-7_430_401.0)); // Oct 6 23:59:59 -> day 6, not yet DST
        assert!(is_dst_australia(-7_430_400.0)); // Oct 7 00:00:00 -> day 7, DST starts

        // Every other match arm each function has, plus the `Err` (timestamp
        // too extreme to convert) fallback all three now share — all
        // timestamps below verified against `gmtime` first.
        const JAN_1_1970: f64 = 0.0; // [1970,0,1,...] (0-indexed month 0)
        const JUN_15_2024: f64 = 1_718_445_000.0; // [2024,5,15,...]
        const OCT_15_2024: f64 = 1_728_950_400.0; // [2024,9,15,...]
        const NOV_15_2024: f64 = 1_731_628_800.0; // [2024,10,15,...]
        const DEC_15_2024: f64 = 1_734_220_800.0; // [2024,11,15,...]
        const APR_15_2024: f64 = 1_713_139_200.0; // [2024,3,15,...]
        const TOO_EXTREME: f64 = 1e300; // same magnitude #869's own test uses

        assert!(is_dst_us_eastern(JUN_15_2024)); // June -> April..=October, true
        assert!(!is_dst_us_eastern(NOV_15_2024)); // Nov 15 -> day < 7 is false
        assert!(!is_dst_us_eastern(DEC_15_2024)); // Dec -> catch-all false
        assert!(!is_dst_us_eastern(TOO_EXTREME)); // Err -> false fallback

        assert!(is_dst_europe(JUN_15_2024)); // June -> April..=September, true
        assert!(is_dst_europe(OCT_15_2024)); // Oct 15 -> day < 25 is true
        assert!(!is_dst_europe(DEC_15_2024)); // Dec -> catch-all false
        assert!(!is_dst_europe(TOO_EXTREME)); // Err -> false fallback

        assert!(is_dst_australia(OCT_15_2024)); // Oct 15 -> day >= 7 is true
        assert!(is_dst_australia(NOV_15_2024)); // Nov -> Nov..=March, true
        assert!(is_dst_australia(DEC_15_2024)); // Dec -> Nov..=March, true
        assert!(is_dst_australia(JAN_1_1970)); // Jan -> Nov..=March, true
        assert!(!is_dst_australia(APR_15_2024)); // Apr 15 -> day < 7 is false
        assert!(!is_dst_australia(JUN_15_2024)); // June -> catch-all false
        assert!(!is_dst_australia(TOO_EXTREME)); // Err -> false fallback
    }

    #[test]
    fn test_mktime() {
        // Round-trip: gmtime | mktime should return original timestamp
        query!(b"[1970,0,1,0,0,0,4,0]", r"mktime",
            QueryResult::Owned(OwnedValue::Float(n)) => {
                assert_eq!(n, 0.0);
            }
        );

        // Jan 15, 2024 10:30:00 UTC
        query!(b"[2024,0,15,10,30,0,1,14]", r"mktime",
            QueryResult::Owned(OwnedValue::Float(n)) => {
                assert_eq!(n, 1705314600.0);
            }
        );
    }

    #[test]
    fn test_strftime() {
        query!(b"[2024,0,15,10,30,0,1,14]", r#"strftime("%Y-%m-%d")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "2024-01-15");
            }
        );

        query!(b"[2024,0,15,10,30,0,1,14]", r#"strftime("%Y-%m-%dT%H:%M:%SZ")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "2024-01-15T10:30:00Z");
            }
        );
    }

    #[test]
    fn test_strftime_week_year_specifiers() {
        // Verified against the pinned jq oracle (#760).
        query!(b"1435677542", r#"gmtime | strftime("%s %U %V %W %G %g")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1435677542 26 27 26 2015 15");
            }
        );

        // ISO week/year boundary: a Monday in late December belongs to ISO
        // week 1 of the *following* year.
        query!(b"1577664000", r#"gmtime | strftime("%U %V %W %G %g")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "52 01 52 2020 20");
            }
        );

        // ISO week/year boundary the other way: Jan 1 on a Friday belongs
        // to ISO week 53 of the *previous* year.
        query!(b"1609459200", r#"gmtime | strftime("%U %V %W %G %g")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "00 53 00 2020 20");
            }
        );

        // %s recomputes from the broken-down fields (portable), matching
        // mktime exactly, rather than round-tripping through a TZ-dependent
        // reinterpretation.
        query!(b"[2024,0,15,10,30,0,1,14]", r#"strftime("%s")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1705314600");
            }
        );

        // Real jq requires the full 8-element array (weekday and yearday
        // included), not just the 6 fields mktime needs — verified against
        // the pinned oracle for every length 1-7. Before this fix, a
        // 6-element array silently defaulted weekday/yearday to 0 instead
        // of erroring, which %U/%V/%W/%G/%g would then silently compute a
        // wrong answer from.
        query!(b"[2024,0,15,0,0,0]", r#"strftime("%Y")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "strftime/1 requires parsed datetime inputs");
            }
        );

        // %W's weekday-to-Monday-first remap uses rem_euclid, matching
        // %U's div_euclid discipline rather than plain `%` (which would
        // give a different, wrong answer for a hand-constructed array with
        // an out-of-range weekday).
        query!(b"[2024,0,1,0,0,0,-7,0]", r#"strftime("%U %W")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "02 00");
            }
        );
    }

    #[test]
    fn test_strftime_raw_number_input() {
        // A raw Unix timestamp number is auto-converted the same way
        // `gmtime` converts one, matching real jq (#759).
        query!(b"0", r#"strftime("%Y-%m-%dT%H:%M:%SZ")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1970-01-01T00:00:00Z");
            }
        );

        // Fractional timestamp, truncated to whole seconds.
        query!(b"1435677542.822351", r#"strftime("%A, %B %e, %Y")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "Tuesday, June 30, 2015");
            }
        );

        // Neither array nor number: real jq's own wording, not a generic
        // type error.
        query!(br#""not a date""#, r#"strftime("%Y")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "strftime/1 requires parsed datetime inputs");
            }
        );

        // `?` suppresses the error for an input that's neither array nor
        // number, same as any other builtin.
        query!(br#""not a date""#, r#"strftime("%Y")?"#,
            QueryResult::None => {}
        );

        // A too-short array gets the same wording real jq uses — it has no
        // distinct "at least 6 elements" message.
        query!(b"[2024,0,15]", r#"strftime("%Y")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "strftime/1 requires parsed datetime inputs");
            }
        );
        query!(b"[2024,0,15]", r#"strftime("%Y")?"#,
            QueryResult::None => {}
        );

        // A non-numeric array element falls back to 0, matching
        // get_int's existing catch-all for array-input strftime.
        query!(br#"["x",0,1,0,0,0,4,0]"#, r#"strftime("%Y")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "0000");
            }
        );

        // Array elements built from arithmetic (OwnedValue::Int), not
        // literal JSON numbers (OwnedValue::NumberLiteral) — exercises
        // get_int's other numeric-variant arm.
        query!(b"[2024,0,15,10,30,0,1,14]", r#"map(.+0) | strftime("%Y-%m-%d")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "2024-01-15");
            }
        );
    }

    #[test]
    fn test_strptime() {
        query!(br#""2024-01-15T10:30:00Z""#, r#"strptime("%Y-%m-%dT%H:%M:%SZ")"#,
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 8);
                assert_eq!(arr[0], OwnedValue::Int(2024)); // year
                assert_eq!(arr[1], OwnedValue::Int(0));    // month (0-indexed)
                assert_eq!(arr[2], OwnedValue::Int(15));   // day
                assert_eq!(arr[3], OwnedValue::Int(10));   // hour
                assert_eq!(arr[4], OwnedValue::Int(30));   // minute
                assert_eq!(arr[5], OwnedValue::Int(0));    // second
            }
        );
    }

    /// #970: `strptime`'s weekday (`checked_days_from_civil`, #912's shared
    /// Howard Hinnant `days_from_civil` formula) is astronomically correct
    /// for every century-non-leap year (1900, 2100, 2200, 2300, ...) —
    /// verified against macOS's own `date -j` command and independently
    /// cross-checked by hand via Zeller's congruence.
    ///
    /// This is a deliberate divergence from jq's own **macOS/BSD** build,
    /// not a succinctly bug: jq's `src/builtin.c` `set_tm_wday()` (a
    /// hand-rolled Gauss's-algorithm fallback) carries its own doc comment
    /// admitting it "produces the wrong day-of-the-week number for dates
    /// in the range 1900-01-01..1900-02-28, and for 2100-01-01..2100-02-28"
    /// — and jq's macOS build *always* uses this fallback (unlike Linux,
    /// which only falls back to it if glibc's own `strptime()` left
    /// `tm_wday` unset, which it doesn't). So jq's own weekday output for
    /// this date range is platform-dependent, and the macOS build is the
    /// one jq's own maintainers call wrong — confirmed by diffing jq's
    /// output against this test's dates: jq-on-macOS gives one day
    /// earlier for every date below except the two `-03-01` boundary
    /// dates, where the bug self-corrects (matching jq's own comment
    /// exactly). Decision (John Ky, issue #970): keep succinctly's
    /// correct behavior rather than reproduce jq's platform-specific bug.
    #[test]
    fn test_strptime_weekday_correct_for_century_non_leap_years_970() {
        for (date, expected_weekday) in [
            ("1900-01-01", 1), // Monday; jq-macOS wrongly gives 0 (Sunday)
            ("1900-02-28", 3), // Wednesday; jq-macOS wrongly gives 2 (Tuesday)
            ("1900-03-01", 4), // Thursday; bug self-corrects here
            ("2100-01-01", 5), // Friday; jq-macOS wrongly gives 4 (Thursday)
            ("2100-02-28", 0), // Sunday; jq-macOS wrongly gives 6 (Saturday)
            ("2100-03-01", 1), // Monday; bug self-corrects here
            ("2200-02-15", 6), // Saturday; jq-macOS wrongly gives 5 (Friday)
            ("2300-02-15", 4), // Thursday; jq-macOS wrongly gives 3 (Wednesday)
        ] {
            let input = format!("\"{date}\"");
            query!(input.as_bytes(), r#"strptime("%Y-%m-%d")[6]"#,
                QueryResult::Owned(OwnedValue::Int(weekday)) => {
                    assert_eq!(weekday, expected_weekday, "date: {date}");
                }
            );
        }
    }

