    #[test]
    fn test_compound_assign_references_root() {
        // Regression test for #159: the RHS of `.a += .b` must be evaluated
        // against the root, not against the sub-value at `.a`.
        query!(br#"{"a": 1, "b": 2}"#, r".a += .b",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(*obj.get("a").unwrap(), OwnedValue::Int(3));
                assert_eq!(*obj.get("b").unwrap(), OwnedValue::Int(2));
            }
        );
    }

    #[test]
    fn test_alternative_assign_references_root() {
        // Regression test for #159: the RHS of `.a //= .b` must be evaluated
        // against the root, not against the sub-value at `.a`.
        query!(br#"{"a": null, "b": 5}"#, r".a //= .b",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(*obj.get("a").unwrap(), OwnedValue::Int(5));
                assert_eq!(*obj.get("b").unwrap(), OwnedValue::Int(5));
            }
        );
    }

    #[test]
    fn test_compound_assign_multi_path_freezes_rhs() {
        // Regression test for #159: the RHS is evaluated once against the
        // pristine root before any path is updated, then reused for every
        // element `.a[]` resolves to -- not re-evaluated per element against
        // the already-updated root. Confirmed against real jq (jq-1.7.1):
        // `{"a":[1,2,3]} | .a[] += .a[0]` yields `{"a":[2,3,4]}` (every
        // element gets the original `.a[0]` == 1 added), not `[2,4,6]` (which
        // is what re-reading a progressively-updated `.a[0]` would produce).
        query!(br#"{"a": [1, 2, 3]}"#, r".a[] += .a[0]",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                let arr = obj.get("a").unwrap();
                assert_eq!(*arr, OwnedValue::Array(vec![
                    OwnedValue::Int(2),
                    OwnedValue::Int(3),
                    OwnedValue::Int(4),
                ]));
            }
        );
    }

    /// #1778: `+=`'s RHS forks once per output in jq mode, matching real
    /// jq (confirmed live, jq 1.7.1): `.x += (10,20,30)` on `{"x":1}` is
    /// three documents, not one with the RHS collapsed to its first
    /// output the way `eval_rhs_once` used to.
    #[test]
    fn test_compound_assign_multi_output_rhs_forks_once_per_output_1778() {
        assert_eq!(
            outputs(br#"{"x":1}"#, ".x += (10,20,30)"),
            vec![r#"{"x":11}"#, r#"{"x":21}"#, r#"{"x":31}"#],
        );
    }

    /// #1778: real yq takes only the *last* RHS output, with no fork
    /// (confirmed live, yq v4.53.3): `.x += (10,20,30)` on `{"x":1}` is
    /// one document, `{"x":31}` -- the same #1430 rule `eval_assign`
    /// already applies to plain `=`.
    #[test]
    fn test_yq_compound_assign_multi_output_rhs_takes_last_value_1778() {
        // `-=`/`*=` verified live too (yq v4.53.3): `.x -= (1,2,3)` on
        // `{"x":10}` is `{"x":7}` (10-3); `.x *= (2,3,4)` is `{"x":40}`
        // (10*4) -- both take only the last output, same as `+=`.
        assert_eq!(
            outputs_yq(br#"{"x":10}"#, ".x -= (1,2,3)"),
            vec![r#"{"x":7}"#]
        );
        assert_eq!(
            outputs_yq(br#"{"x":10}"#, ".x *= (2,3,4)"),
            vec![r#"{"x":40}"#]
        );
        assert_eq!(
            outputs_yq(br#"{"x":1}"#, ".x += (10,20,30)"),
            vec![r#"{"x":31}"#]
        );
    }

    /// #1778: a single-output RHS is completely unaffected by the fork/
    /// last-value logic, in both modes.
    #[test]
    fn test_compound_assign_single_output_rhs_unaffected_1778() {
        assert_eq!(outputs(br#"{"x":1}"#, ".x += 10"), vec![r#"{"x":11}"#]);
        assert_eq!(outputs_yq(br#"{"x":1}"#, ".x += 10"), vec![r#"{"x":11}"#]);
    }

    /// #1778: a genuinely zero-output RHS (`empty`) makes the whole
    /// compound assignment produce zero output (#1313's rule, still
    /// correct after this fix's restructure) -- not a document with the
    /// path set to `null`.
    #[test]
    fn test_compound_assign_empty_rhs_produces_no_output_1778() {
        query!(br#"{"x":1}"#, ".x += empty",
            QueryResult::None => {}
        );
    }

    /// #1778: `//=`'s RHS forks the same way `+=`'s does in jq mode.
    #[test]
    fn test_alternative_assign_multi_output_rhs_forks_once_per_output_1778() {
        assert_eq!(
            outputs(br#"{"x":null}"#, ".x //= (10,20)"),
            vec![r#"{"x":10}"#, r#"{"x":20}"#],
        );
    }

    /// #1778: `//=` has no real yq syntax to compare against (see this
    /// function's own doc comment), so the yq-mode "take the last value"
    /// rule is judged by internal consistency with `|=` alone -- still
    /// worth pinning that the collapse actually happens.
    #[test]
    fn test_yq_alternative_assign_multi_output_rhs_takes_last_value_1778() {
        assert_eq!(
            outputs_yq(br#"{"x":null}"#, ".x //= (10,20)"),
            vec![r#"{"x":20}"#]
        );
    }

    /// #1778: an RHS that errors partway through still keeps the
    /// documents already forked before it, matching #400's "already-piped
    /// output survives a downstream error" policy `eval_assign` already
    /// follows for `=`.
    #[test]
    fn test_compound_assign_multi_output_rhs_errors_after_partial_output_1778() {
        query!(br#"{"x":1}"#, r#".x += (10, error("boom"), 30)"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), vec![r#"{"x":11}"#]);
                assert_eq!(e.message, "boom");
            }
        );
    }

    /// #1778: `collect_rhs_outputs`'s `Many(vs)` success arm -- a
    /// genuinely cursor-backed multi-output RHS (`.a[]`'s own iteration,
    /// not a comma of owned literals, which materializes straight to
    /// `ManyOwned` instead), all of whose outputs decode cleanly.
    #[test]
    fn test_compound_assign_cursor_backed_many_rhs_forks_1778() {
        assert_eq!(
            outputs(br#"{"x":1,"a":[10,20]}"#, ".x += .a[]"),
            vec![r#"{"x":11,"a":[10,20]}"#, r#"{"x":21,"a":[10,20]}"#],
        );
    }

    /// #1778: `collect_rhs_outputs`'s bare `Error`/`Break`/`Halt` arms
    /// (zero RHS output, not a `Partial` with some output first). The
    /// outer `?` on `(.x += error("boom"))?` swallows the error before
    /// `eval_compound_assign` is ever called with `optional: true` --
    /// confirmed live (temporarily instrumented both this function and
    /// `eval_assign`'s identical branch): both always see `optional:
    /// false` here even under an outer `?`. What exactly drives this
    /// parameter to `true` at this specific call site is not
    /// characterized by either function's own existing comments and is
    /// unrelated to this PR's fork/last-value fix -- this test only pins
    /// the bare `Error`/`Break`/`Halt` match arms themselves, not the
    /// `if optional` guard beside them.
    #[test]
    fn test_compound_assign_bare_rhs_error_break_and_halt_1778() {
        query!(br#"{"x":1}"#, r#".x += error("boom")"#,
            QueryResult::Error(e) => { assert_eq!(e.message, "boom"); }
        );
        query!(br#"{"x":1}"#, r#"(.x += error("boom"))?"#,
            QueryResult::None => {}
        );
        query!(br#"{"x":1}"#, "label $out | .x += (break $out)",
            QueryResult::None => {}
        );
        query!(br#"{"x":1}"#, ".x += halt_error(3)",
            QueryResult::Halt(3) => {}
        );
    }

    /// #1778: a multi-output RHS still forks once *per output*, not once
    /// per (output, resolved path) pair, when the LHS path itself resolves
    /// to more than one location -- matching `eval_assign`'s own
    /// `test_compound_assign_multi_path_freezes_rhs`-adjacent behavior
    /// (each output is applied to every resolved path within its own
    /// single document copy).
    #[test]
    fn test_compound_assign_multi_path_with_multi_output_rhs_forks_per_output_not_per_path_1778() {
        // Confirmed against real jq 1.7.1: `(.a,.b) += (10,20)` on
        // `{"a":1,"b":2}` is two documents (one per RHS output), each with
        // *both* paths updated by that same output -- not four documents
        // (one per (path, output) pair).
        assert_eq!(
            outputs(br#"{"a":1,"b":2}"#, "(.a,.b) += (10,20)"),
            vec![r#"{"a":11,"b":12}"#, r#"{"a":21,"b":22}"#],
        );
    }

    #[test]
    fn test_assign_autovivifies_through_null_and_missing_fields() {
        // #486: a write through a missing or `null` intermediate builds the
        // container the path implies, exactly as `setpath()` already does,
        // instead of erroring `Cannot index null with string "..."`.
        assert_outcomes(&[
            (b"null", ".a = 1", Ok(r#"{"a":1}"#)),
            (b"{}", ".a.b = 9", Ok(r#"{"a":{"b":9}}"#)),
            (br#"{"a":null}"#, ".a.b.c = 9", Ok(r#"{"a":{"b":{"c":9}}}"#)),
            (b"{}", ".a[0] = 9", Ok(r#"{"a":[9]}"#)),
        ]);
    }

    #[test]
    fn test_assign_autovivifies_and_pads_through_null_index() {
        // Sibling of the field case above, for a numeric index: `null`
        // becomes an array, and an index past the end pads with `null`s
        // rather than erroring — matching `setpath([5]; 9)`.
        assert_outcomes(&[
            (b"null", ".[0] = 9", Ok("[9]")),
            (b"[1,2]", ".[5] = 9", Ok("[1,2,null,null,null,9]")),
            (br#"{"a":[]}"#, ".a[0] = 9", Ok(r#"{"a":[9]}"#)),
        ]);
    }

    #[test]
    fn test_assign_through_parenthesized_pipe_target_names_the_type_mismatch() {
        // #1287: a static (no computed key) parenthesized pipe target, like
        // `(.a|.c)`, never goes through `resolve_dynamic_indexes`'s
        // flattening pass (`needs_path_prepass` says no -- nothing here is
        // computed), so `set_path`'s `Expr::Pipe` arm handed `get_path_mut`
        // an un-flattened `Expr::Pipe([Field("a"), Field("c")])` as a single
        // path component. `get_path_mut` didn't know how to walk a `Pipe`,
        // so it fell to its catch-all's generic "invalid path component"
        // instead of the type-naming message its `Field`/`Index` arms
        // already produce once actually reached. All three confirmed
        // against real jq 1.7.1.
        assert_outcomes(&[
            (
                br#"{"a":{"c":1}}"#,
                "((.a|.c)[0]) = 9",
                Err("Cannot index number with number"),
            ),
            (
                br#"{"a":{"c":1}}"#,
                r#"((.a|.c)["c"]) = 9"#,
                Err(r#"Cannot index number with string "c""#),
            ),
            (
                br#"{"a":{"c":1}}"#,
                "((.a|.c)[0:1]) = 9",
                Err("Cannot index number with object"),
            ),
            // Nesting depth beyond two levels still flattens correctly.
            (
                br#"{"a":{"b":{"c":1}}}"#,
                "((.a|.b|.c)[0]) = 9",
                Err("Cannot index number with number"),
            ),
        ]);
    }

    #[test]
    fn test_assign_optional_group_scopes_suppression_to_the_group_only() {
        // #1287 review round: the first fix's splice loop computed each
        // spliced-in component's own `?` via `unwrap_path_component` but
        // never consulted it, so `(.a|.c)?` -- `try (.a|.c)` in jq terms --
        // stopped suppressing navigation failures inside the group it
        // wraps. All four cases confirmed against real jq 1.7.1.
        assert_outcomes(&[
            // The group's own navigation fails on its first component --
            // `?` suppresses it, so the whole assignment no-ops.
            (
                br#"{"a":"notobj"}"#,
                "((.a|.c)? | .y) = 9",
                Ok(r#"{"a":"notobj"}"#),
            ),
            // Same, but the group fails on its *second* component --
            // `try (.a|.c)` catches a failure from either half, not just
            // the first.
            (br#"{"a":5}"#, "((.a|.c)? | .y) = 9", Ok(r#"{"a":5}"#)),
            // Dot-chain spelling of the same group, no explicit `|`.
            (
                br#"{"a":"notobj"}"#,
                "((.a.b)? | .y) = 9",
                Ok(r#"{"a":"notobj"}"#),
            ),
            // Boundary the naive fix over-suppressed: once `.a|.c` itself
            // *succeeds*, `?` no longer covers what comes after the closing
            // paren -- `.y` failing here must still raise, not no-op. This
            // is the one real jq draws that a single carried-forward
            // `optional` flag (mirroring `update_path`'s own `Expr::Pipe`
            // arm) does not: that arm's own `|=` equivalent incorrectly
            // no-ops this exact shape (a pre-existing, separate bug, filed
            // rather than fixed here).
            (
                br#"{"a":{"c":5}}"#,
                "((.a|.c)? | .y) = 9",
                Err(r#"Cannot index number with string "y""#),
            ),
        ]);
    }

    #[test]
    fn test_update_and_del_optional_group_scopes_suppression_to_the_group_only_1294() {
        // #1294: `update_path`'s (`|=`) and `delete_at_path`'s (`del()`)
        // sibling `Expr::Pipe(inner)` splice arms threaded `here` (which
        // folds in the group's own `?`) as the blanket `optional` for the
        // *entire* spliced continuation, over-suppressing whatever follows
        // the group too -- the same bug #1287's review round found and
        // fixed for `=`'s `get_path_mut`, independently present here. All
        // confirmed against real jq 1.7.1.
        query!(br#"{"a":{"c":5}}"#, "((.a|.c)? | .y) |= 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with string \"y\"");
            }
        );
        query!(br#"{"a":{"c":5}}"#, "del((.a|.c)? | .y)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with string \"y\"");
            }
        );
        // Boundary: the group's own failure is still correctly suppressed
        // -- only what comes *after* it must stop being covered.
        query!(br#"{"a":"notobj"}"#, "((.a|.c)? | .y) |= 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":"notobj"}"#);
            }
        );
        query!(br#"{"a":"notobj"}"#, "del((.a|.c)? | .y)",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":"notobj"}"#);
            }
        );
        // The splice arm's non-optional path (no `?` anywhere, `here` is
        // `false`): `(.a|.c)[0]` reaches `update_path`/`delete_at_path`'s
        // `Expr::Pipe` arm the same un-flattened way `set_path` used to
        // before #1287, and was already handled correctly pre-#1294 -- this
        // pins that pre-existing behavior rather than a new fix.
        query!(br#"{"a":{"c":1}}"#, "(.a|.c)[0] |= 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with number");
            }
        );
        query!(br#"{"a":{"c":1}}"#, "del((.a|.c)[0])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with number");
            }
        );
        // yq mode shares this exact arm (`S`-generic, no `S::TAG` branch in
        // it) -- confirmed with a live yq v4.53.3 comparison. A *scalar*
        // intermediate (`.c: 5`, mirroring the jq cases above) would not
        // actually exercise the fix here: `is_yq_field_index_noop_scalar`
        // makes `|=`'s own `Field`/`Index` arms no-op unconditionally on a
        // scalar target, before this arm's `?`-scoping ever matters, and
        // would pass identically whether this fix existed or not. An array
        // intermediate keeps the failure genuine (`Cannot index array with
        // string "y"`, matching real yq's own container-vs-container
        // mismatch, which is not covered by the scalar no-op).
        yq_query!(br#"{"a":{"c":[1,2,3]}}"#, "((.a|.c)? | .y) |= 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index array with string \"y\"");
            }
        );
        yq_query!(br#"{"a":"notobj"}"#, "((.a|.c)? | .y) |= 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":"notobj"}"#);
            }
        );
    }

    #[test]
    fn test_assign_slice_nested_in_a_parenthesized_non_terminal_component_1292() {
        // #1292: `split_at_slice` only scanned the *top-level* `exprs` list
        // `set_path`'s `Expr::Pipe` arm was called with -- a slice nested
        // inside a parenthesized sub-path that is itself only one of
        // several top-level components (`(.a[0:1])[0] = 9`, where
        // `(.a[0:1])` arrives as a single `Expr::Pipe([Field("a"),
        // Slice{..}])` slot) was invisible to that scan, so the slice never
        // reached `through_slice` and the write fell to the generic
        // "invalid path component" catch-all instead. `|=`/`del()` already
        // handled this shape correctly, isolating the gap to `=`. All
        // confirmed against real jq 1.7.1.
        assert_outcomes(&[
            (
                br#"{"a":[1,2,3]}"#,
                "(.a[0:1])[0] = 9",
                Ok(r#"{"a":[9,2,3]}"#),
            ),
            // A plain top-level slice (no nesting) is unaffected.
            (br#"{"a":[1,2,3]}"#, ".a[0:1] = [9]", Ok(r#"{"a":[9,2,3]}"#)),
            // Nesting depth beyond one level of parens still flattens
            // correctly.
            (
                br#"{"a":{"b":[1,2,3]}}"#,
                "(((.a.b)[0:1]))[0] = 9",
                Ok(r#"{"a":{"b":[9,2,3]}}"#),
            ),
        ]);
    }

    #[test]
    fn test_assign_optional_slice_1303() {
        // #1303: two independent gaps around a `?`-marked slice in an
        // assignment path, both confirmed against real jq 1.7.1.
        assert_outcomes(&[
            // Gap 1: a write-time *application* error (the RHS isn't an
            // array, or the target is a string) was wrongly swallowed by
            // `set_path`'s `Expr::Optional` arm -- real jq's inline `?`
            // suppresses a failure to *reach* a target, not a mismatch in
            // what gets written once one is found (the same class
            // `is_write_time_application_error` already carved out for
            // `Expr::Index`, #498).
            (
                br#"{"a":[1,2,3]}"#,
                ".a[0:1]? = 9",
                Err("A slice of an array can only be assigned another array"),
            ),
            (
                br#"{"a":"hello"}"#,
                r#".a[0:1]? = "x""#,
                Err("Cannot update string slices"),
            ),
            // Contrast: a genuinely non-sliceable target *is* a navigation
            // failure, and stays suppressed.
            (br#"{"a":true}"#, ".a[0:1]? = 9", Ok(r#"{"a":true}"#)),
            // The pre-existing carve-out is unaffected.
            (
                br#"{"a":[1,2,3]}"#,
                ".a[-5]? = 9",
                Err("Out of bounds negative array index"),
            ),
            // Gap 2: `split_at_slice`'s scan didn't see through `Expr::Optional`
            // at all, so a `?`-marked slice followed by more path -- nested
            // in parens or not -- fell to "invalid path component" instead
            // of reaching `through_slice`.
            (
                br#"{"a":[1,2,3]}"#,
                "(.a[0:1]?)[0] = 9",
                Ok(r#"{"a":[9,2,3]}"#),
            ),
            (
                br#"{"a":[1,2,3]}"#,
                ".a[0:1]?[0] = 9",
                Ok(r#"{"a":[9,2,3]}"#),
            ),
            // A genuinely non-sliceable target under this same nested shape
            // is a navigation failure too, and stays suppressed.
            (br#"{"a":true}"#, ".a[0:1]?[0] = 9", Ok(r#"{"a":true}"#)),
        ]);
    }

    #[test]
    fn test_assign_optional_group_with_more_path_1311() {
        // #1311: `?` on a *whole multi-component group* ((.a[0:1])? | .[0]),
        // not directly on the slice itself the way #1303's Gap 2 covered --
        // `push_path_components` pushed the group as one opaque
        // `Optional(Paren(Pipe(...)))` element, which neither
        // `split_at_slice`'s slice scan nor `get_path_mut`'s own per-step
        // match could see through. All confirmed against real jq 1.7.1.
        assert_outcomes(&[
            (
                br#"{"a":[1,2,3]}"#,
                "((.a[0:1])? | .[0]) = 9",
                Ok(r#"{"a":[9,2,3]}"#),
            ),
            // A genuinely non-sliceable target under this same grouped
            // shape is a navigation failure, and stays suppressed.
            (
                br#"{"a":true}"#,
                "((.a[0:1])? | .[0]) = 9",
                Ok(r#"{"a":true}"#),
            ),
            // Multiple components inside the group, each individually
            // suppressible -- not just a bare slice.
            (
                br#"{"a":{"b":[1,2,3]}}"#,
                "((.a.b[0:1])? | .[0]) = 9",
                Ok(r#"{"a":{"b":[9,2,3]}}"#),
            ),
        ]);
    }

    /// #1429: whichever multi-slot construct comes *first* claims the walk.
    ///
    /// Before `set_path_steps`, this was an invariant maintained by hand:
    /// `split_at_iterate` bailed whenever a `Slice` appeared earlier in the
    /// chain, so that `split_at_slice` -- called *after* it -- got first
    /// crack, while `split_at_slice` carried no reciprocal bail of its own.
    /// Correctness therefore rested on the call-site ordering plus a doc
    /// comment; nothing failed if either drifted. Peeling one component at a
    /// time makes it structural instead: the first construct in the chain is
    /// simply the first arm the walk reaches. Both orderings pinned here, and
    /// both confirmed against real jq 1.7.1.
    #[test]
    fn test_assign_leftmost_multi_slot_construct_claims_the_walk_1429() {
        assert_outcomes(&[
            // Slice first: the iterate runs *inside* each sliced element.
            (
                br#"{"a":[[1,2],[3,4],[5,6]]}"#,
                ".a[0:2][] = 9",
                Ok(r#"{"a":[9,9,[5,6]]}"#),
            ),
            // Iterate first: the slice runs independently inside each
            // fanned-out element. Same two constructs, opposite order,
            // genuinely different answer -- which is why the ordering had to
            // be right rather than merely consistent.
            (
                br#"{"a":[[1,2,3],[4,5,6]]}"#,
                ".a[][0:2] = [9]",
                Ok(r#"{"a":[[9,3],[9,6]]}"#),
            ),
            // Three constructs deep, alternating, so no two-way precedence
            // rule could cover it.
            (
                br#"{"a":[[[1,2],[3,4]],[[5,6],[7,8]]]}"#,
                ".a[][0:1][] = 9",
                Ok(r#"{"a":[[9,[3,4]],[9,[7,8]]]}"#),
            ),
        ]);
    }

    /// #1429: a nested `Paren`/`Pipe` group with neither an iterate nor a
    /// slice in it is walked once, not scanned twice.
    ///
    /// Behaviourally this is #1287's case and is pinned above; what this adds
    /// is the shape that used to pay *both* `split_at_iterate`'s and
    /// `split_at_slice`'s full allocate-and-clone flatten before either
    /// concluded it had nothing to do. A regression here would most likely
    /// show as a wrong answer rather than a slow one, since re-introducing a
    /// pre-scan is what would make the group opaque again.
    #[test]
    fn test_assign_through_nested_group_without_iterate_or_slice_1429() {
        assert_outcomes(&[
            (
                br#"{"a":{"c":[1,2,3]}}"#,
                "(.a|.c)[0] = 9",
                Ok(r#"{"a":{"c":[9,2,3]}}"#),
            ),
            (
                br#"{"a":{"c":{}}}"#,
                "(.a|.c).d = 9",
                Ok(r#"{"a":{"c":{"d":9}}}"#),
            ),
            // A group nested inside another group -- the shape that
            // reaches `push_path_components`' own recursion, not just its
            // top-level splice. Parenthesised as a whole: a bare
            // `(.a|.b)|(.c) = 9` binds as a *pipe* of two expressions
            // (`|` is lower-precedence than `=`) and is `{"c":9}` in jq,
            // not a path at all.
            (
                br#"{"a":{"b":{"c":1}}}"#,
                "((.a|.b)|.c) = 9",
                Ok(r#"{"a":{"b":{"c":9}}}"#),
            ),
        ]);
    }

    /// #1429: an `Identity` inside a chain is a step to skip, not a shape to
    /// flatten around.
    ///
    /// `is_atomic_path_component` accepts `Identity` so `.a | . | .b` stays on
    /// the borrowed fast path, which makes `set_path_steps`' own `Identity`
    /// arm the thing that skips it; the flattener would have dropped it
    /// instead, at the cost of an allocate-and-clone pass. The two spellings
    /// therefore take genuinely different routes and are pinned together.
    /// All four confirmed against real jq 1.7.1.
    #[test]
    fn test_assign_identity_steps_inside_a_chain_1429() {
        assert_outcomes(&[
            // Borrowed path, `Identity` skipped mid-chain.
            (
                br#"{"a":{"b":1}}"#,
                "(.a | . | .b) = 9",
                Ok(r#"{"a":{"b":9}}"#),
            ),
            (
                br#"{"a":{"b":1}}"#,
                "(. | .a.b) = 9",
                Ok(r#"{"a":{"b":9}}"#),
            ),
            // Borrowed path, `Identity` as the *terminal* component: the
            // whole document is the write target.
            (br#"{"a":{"b":1}}"#, "(.|.) = 9", Ok("9")),
            // Still the borrowed path: `set_path`'s `Paren` arm unwraps the
            // outer parens before the list is ever classified.
            (br#"{"a":{"b":1}}"#, "((.|.)) = 9", Ok("9")),
            // A nested group *alongside* another component is what makes the
            // list non-atomic, so these two go through the flattener -- which
            // drops every `Identity` and leaves an empty step list, the one
            // route to `set_path_steps`' `[]` arm.
            (br#"{"a":{"b":1}}"#, "((.|.) | .) = 9", Ok("9")),
            (br#"{"a":{"b":1}}"#, "(.|(.|.)) = 9", Ok("9")),
        ]);
    }

    /// #1429: [`iterate_suffix_len`]'s O(1) answer agrees with the O(N) scan
    /// it replaced.
    ///
    /// This is the whole mechanism behind the stranded-write undo now, so it
    /// is pinned against the definition it has to match --
    /// `rest.iter().any(reaches_iterate)` -- rather than against hand-written
    /// expectations, over every suffix of a chain that mixes both kinds of
    /// component and both `Iterate` spellings.
    #[test]
    fn test_iterate_suffix_len_matches_a_direct_scan_1429() {
        let steps = [
            Expr::Field("a".to_string()),
            Expr::Iterate,
            Expr::index(0),
            Expr::Optional(Box::new(Expr::Iterate)),
            Expr::Field("b".to_string()),
            Expr::slice(None, None),
        ];
        let suffix = iterate_suffix_len(&steps);
        for cut in 0..=steps.len() {
            let rest = &steps[cut..];
            assert_eq!(
                rest.len() >= suffix,
                rest.iter().any(reaches_iterate),
                "disagreement on suffix starting at {cut}"
            );
        }

        // No `Iterate` anywhere: every suffix must answer `false`, which is
        // what `usize::MAX` buys -- a sentinel no `rest.len()` can reach.
        let none = [
            Expr::Field("a".to_string()),
            Expr::index(0),
            Expr::Field("b".to_string()),
        ];
        assert_eq!(iterate_suffix_len(&none), usize::MAX);
        for cut in 0..=none.len() {
            assert!(none[cut..].len() < iterate_suffix_len(&none));
        }
    }

    /// #1429: a long chain writes the same document under `=` as under `|=`.
    ///
    /// `=` briefly recursed per path component during this refactor, which
    /// review caught as a release-build stack-overflow regression; it now
    /// consumes any step that cannot strand without leaving a frame, so its
    /// stack use is bounded by the stranding-capable steps rather than by
    /// path length. The end-to-end proof of that is
    /// `test_deep_flat_assign_chain_exits_cleanly_not_stack_overflow_1429`
    /// in tests/jq_cli_tests.rs, at 200,000 components.
    ///
    /// `|=` was, at the time this test was written, recursive per component
    /// with no flattening of its own -- it aborted in a *debug* build
    /// (larger frames, 2 MiB test-thread stack) somewhere between 128 and
    /// 192 components, well short of `=`'s own 256-deep pin here, which is
    /// why the two operators used to be checked at *different* depths (256
    /// vs. 128) rather than a shared one that would have silently been
    /// `|=`'s lower ceiling.
    ///
    /// #2115 gave `update_path` the same treatment: `update_path_steps` now
    /// collects a maximal run of steps that must all autovivify together and
    /// applies the update filter once against a detached leaf, rather than
    /// recursing per component -- see
    /// `test_deep_flat_update_chain_exits_cleanly_not_stack_overflow_2115`
    /// (tests/jq_cli_tests.rs) for the end-to-end proof, at 1,000,000
    /// components in a *debug* build. Both operators now share the same
    /// depth here: `|=`'s old ceiling was a property of the removed
    /// per-component recursion, not of anything this agreement check itself
    /// needs to keep testing separately.
    #[test]
    fn test_assign_deep_chain_agrees_with_the_update_walker_1429() {
        fn chain(depth: usize) -> (String, String) {
            let path: String = (0..depth).map(|i| format!(".k{i}")).collect();
            let mut expected = String::from("9");
            for i in (0..depth).rev() {
                expected = format!("{{\"k{i}\":{expected}}}");
            }
            (path, expected)
        }

        let (path, expected) = chain(256);
        let set = format!("{path} = 9");
        let update = format!("{path} |= 9");
        assert_outcomes(&[
            (b"null", set.as_str(), Ok(expected.as_str())),
            (b"null", update.as_str(), Ok(expected.as_str())),
        ]);
    }

    #[test]
    fn test_yq_assign_through_parenthesized_pipe_target_noops_on_non_container_1287() {
        // The nested-`Expr::Pipe` flattening is shared by both evaluators
        // (`get_path_mut`'s in-walk splice when #1287 landed, the up-front
        // `flatten_path_components` since #1429) -- before it, yq mode hit
        // the exact same "invalid path component" internal error jq mode
        // did, in place of the no-op real yq gives
        // for writing through a scalar (`scalar_noop`/`container_noop`,
        // #1101/#1142). Live-verified against real yq v4.53.3: all three
        // shapes leave the document unchanged, exit 0.
        for filter in [
            "((.a|.c)[0]) = 9",
            r#"((.a|.c)["c"]) = 9"#,
            "((.a|.c)[0:1]) = 9",
        ] {
            let json: &[u8] = br#"{"a":{"c":1}}"#;
            let index = JsonIndex::build(json);
            let cursor = index.root(json);
            let expr = parse(filter).unwrap();
            let out: Vec<String> = eval::<Vec<u64>, YqSemantics>(&expr, cursor)
                .collect_owned()
                .iter()
                .map(OwnedValue::to_json)
                .collect();
            assert_eq!(out, vec![r#"{"a":{"c":1}}"#], "filter: {filter}");
        }
    }

    /// `delete_path_steps`'s (#2115) `Expr::Iterate` arm re-classifies `rest`
    /// against each element via `yq_del_slice_outcome`, per #1116/#1162/
    /// #1219 -- this exercises its `DropParent(ref target)` outcome
    /// specifically (a non-empty, slice-free residual prefix before the
    /// trailing slice-run, `.x` here), which drops that prefix's own key
    /// from each element via a nested `delete_at_path` call rather than
    /// removing the element itself (`DropParent(Expr::Identity)`, covered
    /// elsewhere) or recursing further (`NotApplicable`). Live-verified
    /// against real yq v4.53.3: `.a[].x[1:3]` on
    /// `{"a":[{"x":[1,2,3,4]},{"x":[5,6,7,8]}]}` drops `x` from both
    /// elements entirely, leaving `{"a":[{},{}]}`.
    #[test]
    fn test_yq_del_iterate_droparent_target_via_trailing_slice_run_2115() {
        let json: &[u8] = br#"{"a":[{"x":[1,2,3,4]},{"x":[5,6,7,8]}]}"#;
        let index = JsonIndex::build(json);
        let cursor = index.root(json);
        let expr = parse("del(.a[].x[1:3])").unwrap();
        let out: Vec<String> = eval::<Vec<u64>, YqSemantics>(&expr, cursor)
            .collect_owned()
            .iter()
            .map(OwnedValue::to_json)
            .collect();
        assert_eq!(out, vec![r#"{"a":[{},{}]}"#]);
    }

    #[test]
    fn test_update_compound_and_alternative_assign_autovivify_too() {
        // The same auto-vivification applies to every write operator that
        // funnels through `update_path`, not just plain `=`.
        assert_outcomes(&[
            (b"{}", ".a.b |= 9", Ok(r#"{"a":{"b":9}}"#)),
            (b"{}", ".a.b += 1", Ok(r#"{"a":{"b":1}}"#)),
            (b"{}", ".a.b //= 9", Ok(r#"{"a":{"b":9}}"#)),
            (b"[1,2]", ".[5] |= 9", Ok("[1,2,null,null,null,9]")),
            // `|=`/`+=`/etc. have their own mid-chain `Index` arm, distinct
            // from the terminal one, with its own autovivify_array +
            // write_index calls — exercised only by an `Index` step that
            // still has more path left after it. (`=` has the same split
            // since #1429 gave it a peel-and-recurse walker of its own; it
            // used to reach the same slot through `get_path_mut`'s loop.)
            (b"{}", ".a[0].b |= 9", Ok(r#"{"a":[{"b":9}]}"#)),
            (b"[{},{}]", ".[0].x += 1", Ok(r#"[{"x":1},{}]"#)),
        ]);
    }

    /// `update_path_steps`'s (#2115) own `Expr::Index` arm reaches its
    /// *fresh* branch (padding needed, more path after it) only when the
    /// `Index` step itself is dispatched from the main loop rather than
    /// swept up by an earlier `Field`'s own fresh-run collection --
    /// `.a[0].b |= 9` on `{}` above doesn't reach it, since `.a` is itself
    /// fresh and its collection greedily absorbs the `Index` step too
    /// (built by `wrap_fresh`, not by this arm). Here `.a` already exists,
    /// so it's peeled with no frame, and `.a[3]` is genuinely dispatched by
    /// the main loop against a real (already-existing) array that still
    /// needs padding.
    #[test]
    fn test_update_index_arm_fresh_branch_reached_after_existing_prefix_2115() {
        assert_outcomes(&[
            (
                br#"{"a":[1,2]}"#,
                ".a[3].b |= 9",
                Ok(r#"{"a":[1,2,null,{"b":9}]}"#),
            ),
            // #1877/#1894: the same `!wrote && undo_stranded` collapse
            // `update_path_steps`'s `Field` arm has, exercised through the
            // `Index` arm instead -- the padding this would have needed is
            // discarded entirely rather than left half-built.
            (br#"{"a":[1,2]}"#, ".a[3].b |= empty", Ok(r#"{"a":[1,2]}"#)),
            // A negative index still out of bounds after counting back from
            // the end (`-5` against a 2-element array) is a write-time
            // application error raised by `resolve_setpath_index` itself,
            // before `write_index`'s own padding would ever run -- unlike
            // `-1` against this same array, which resolves to the array's
            // *existing* last element and takes the "already exists" branch
            // instead (never reaching this arm's fresh path at all).
            (
                br#"{"a":[1,2]}"#,
                ".a[-5].b |= 9",
                Err("Out of bounds negative array index"),
            ),
        ]);
    }

    /// #2115 code review (PR #2238): the fresh-run collapse never calls
    /// `wrap_fresh` when the update filter produces no output, so a bad
    /// (out-of-range/negative) `Index` *inside* the run -- swept into an
    /// earlier fresh `Field`/`Index` step's collection, never dispatched by
    /// `update_path_steps`' own main loop -- is never bounds-checked at all,
    /// rather than erroring. Confirmed to be an *improvement*, not a
    /// regression: real jq (1.7.1) genuinely defers this exact check behind
    /// whether the update filter writes, for a freshly-autovivified index,
    /// the same way its own terminal `Expr::Index` arm already does
    /// (`update_path`'s #1916 doc comment) -- `null | .a[-1][1] |= empty` is
    /// `null` in real jq, live-verified, where the pre-#2115 recursive
    /// walker (which called `write_index` unconditionally for every `Index`
    /// component regardless of the eventual write outcome) raised "Out of
    /// bounds negative array index" instead. `wrap_fresh`'s own doc comment
    /// has the full mechanism and the one remaining case this fix does *not*
    /// close (a *leading* `Index`, with no preceding fresh step, still
    /// checks eagerly -- unaffected by this fix either way).
    ///
    /// yq mode is unaffected: `undo_stranded` (`S::TAG != EvalTag::Yq`) is
    /// `false` there, so yq mode always falls through to `wrap_fresh`,
    /// matching real yq's own stricter (always-eager) requirement.
    #[test]
    fn test_update_index_bounds_check_deferred_behind_fresh_run_collapse_2115() {
        assert_outcomes(&[
            // The confirmed improvement: no error, matching real jq.
            (b"null", ".a[-1][1] |= empty", Ok("null")),
            (b"null", ".a[-1][1] |= select(false)", Ok("null")),
            // The adjacent real-write case still validates -- the deferral
            // is specifically about *whether* to check, gated on `wrote`,
            // never about silently accepting a bad index that is actually
            // used.
            (
                b"null",
                ".a[-1][1] |= 9",
                Err("Out of bounds negative array index"),
            ),
        ]);
    }

    #[test]
    fn test_optional_assign_through_autovivified_null_no_longer_leaves_a_remnant() {
        // Before #486/#498, `?` swallowed the write failure but not before
        // `get_path_mut`'s `or_insert(Null)` had already created the key, so
        // `.a[.k]? = 5` and `.a.b? = 5` left `"a":null` behind instead of
        // either the full write or an untouched input. Now that the write
        // itself succeeds, there is nothing left for `?` to swallow.
        assert_outcomes(&[
            (
                br#"{"k":"z"}"#,
                ".a[.k]? = 5",
                Ok(r#"{"k":"z","a":{"z":5}}"#),
            ),
            (b"{}", ".a.b? = 5", Ok(r#"{"a":{"b":5}}"#)),
        ]);
    }

    #[test]
    fn test_optional_write_still_raises_on_negative_index_out_of_bounds() {
        // #498: `?` suppresses errors raised while *collecting* a path, but
        // not the write-time bounds check on a still-negative array index —
        // jq raises `.[-5]? = 9` even though the trailing `?` would swallow
        // any other indexing failure at that position.
        assert_outcomes(&[
            (
                b"[1,2]",
                ".[-5]? = 9",
                Err("Out of bounds negative array index"),
            ),
            (
                br#"{"a":[1,2]}"#,
                ".a[-5]? = 9",
                Err("Out of bounds negative array index"),
            ),
            // Unaffected: `?` on a genuine type mismatch (not an OOB index)
            // still suppresses, same as before.
            (b"5", ".a? = 1", Ok("5")),
        ]);
    }

    #[test]
    fn test_optional_write_does_not_protect_the_filter_or_the_whole_expression() {
        // #498's rule applies just as much to `|=`'s filter as to the write
        // itself: `?` on a path component prunes path *production*, and
        // running the filter at the resolved location is path *application*
        // — jq raises `boom` here rather than leaving `.a` untouched or
        // swallowing the error. (Before this fix, `update_path` threaded the
        // component's own `optional` into `eval_owned_expr` too, so the
        // filter's `error("boom")` was itself evaluated as if `?`-guarded and
        // silently produced `null`, corrupting `.a` to `{"a":null}` instead
        // of raising.)
        assert_outcomes(&[(br#"{"a":1}"#, ".a? |= error(\"boom\")", Err("boom"))]);
    }

    #[test]
    fn test_outer_optional_around_a_failing_write_produces_no_output() {
        // A `?` wrapping the *whole* `path op value` expression is ordinary
        // `try/catch`, unrelated to a `?` written on a path component —
        // jq's answer is no output at all, not the unchanged input and not a
        // raised error. `eval_assign`/`eval_update` catch every failure at
        // this boundary (mirroring `builtin_del`'s #537 fix) rather than
        // threading their own `optional` into `set_path`/`update_path` as a
        // starting flag, which is what let this either raise unconditionally
        // (`=`, never fixed before this change) or leak a corrupted partial
        // write (`|=`, once `?` also had to stop protecting the filter).
        assert_outcomes(&[
            (b"[1,2]", "(.[-5] = 9)?", Ok("")),
            (b"[1,2]", "(.[-5] |= 9)?", Ok("")),
            (b"[1,2]", "(.[-5] += 1)?", Ok("")),
            (br#"{"a":1}"#, "(.a |= error(\"boom\"))?", Ok("")),
        ]);
    }

    #[test]
    fn test_optional_midchain_walking_failure_stays_scoped_to_its_own_component() {
        // `get_path_mut` used to drop every inline `?` on a non-final path
        // component ("every path reaching a walker has already been
        // resolved" was only true of the computed-key pre-pass, which a
        // plain static chain like `.a?.b` never goes through), so
        // `"str" | .a?.b = 1` raised `Cannot index string with string "a"`
        // instead of leaving `"str"` untouched like jq.
        assert_outcomes(&[(br#""str""#, ".a?.b = 1", Ok(r#""str""#))]);

        // A component's own `?` protects only *that* component: `.a?`
        // resolves fine here (`.a` already holds `5`, reading an existing
        // object field never fails), so it is never exercised, and the
        // unprotected `.c` still raises on the number it lands on.
        assert_outcomes(&[(
            br#"{"a":{"b":5}}"#,
            ".a?.b.c |= 1",
            Err(r#"Cannot index number with string "c""#),
        )]);
    }

    #[test]
    fn test_optional_write_does_not_swallow_a_sibling_clobber_in_a_fan_out() {
        // #498's multi-branch case: `?` prunes path *production*, never
        // *application* — and that holds even for a path that resolved
        // cleanly, once it is one of several a fan-out applies in sequence.
        // `.. | objects` here visits the root and `.a`, both objects whose
        // own `.k` names an existing field, so `.[.k]?` on each resolves
        // fully against the *original* document (`path()` sees `["a"]` then
        // `["a","a"]`, no pruning). The first write (`.a = 7`) turns `.a`
        // from an object into a number; the second (`.a.a`) then needs `.a`
        // to still be an object and raises, matching jq. Before this fix,
        // the resolved path's leftover `Expr::Optional` marker (from
        // `resolve_index_expr`/`resolve_node`, meant only to record that a
        // `?` was involved in producing the branch) was still being
        // consulted by `set_path`/`update_path` at write time, so the raise
        // was swallowed and `.a` was left at `7` instead.
        let doc = br#"{"k":"a","a":{"k":"a","a":1}}"#;
        assert_outcomes(&[
            (
                doc,
                "(.. | objects | .[.k]?) = 7",
                Err(r#"Cannot index number with string "a""#),
            ),
            (
                doc,
                "(.. | objects | .[.k]?) |= 7",
                Err(r#"Cannot index number with string "a""#),
            ),
        ]);

        // The purely static flavour, reached without any computed key at
        // all: `resolve_seq`'s no-dynamic-component fast path splices a
        // chain like `.a.a?` straight through unresolved rather than routing
        // it through `resolve_node`, so it needed its own fix at
        // `resolve_dynamic_indexes`'s assembly point rather than only at the
        // two sites that build a resolved component from a computed key.
        assert_outcomes(&[(
            br#"{"a":{"a":1}}"#,
            "(.a, .a.a?) = 7",
            Err(r#"Cannot index number with string "a""#),
        )]);
    }

    /// #499: slice bounds accept any expression, evaluated with the same
    /// discipline as a computed index key (`resolve_index_expr`). Every case
    /// here was checked against jq 1.7.1 directly.
    #[test]
    fn test_computed_slice_bounds() {
        assert_outcomes(&[
            // The issue's own repro: a computed start bound, evaluated
            // against the root (not against `.a`).
            (
                br#"{"a":[1,2,3],"k":1}"#,
                r#".a[.k:2]? = ["x"]"#,
                Ok(r#"{"a":[1,"x",3],"k":1}"#),
            ),
            // A bound-evaluation failure is not covered by a trailing `?` —
            // `.x` on an array raises before the slice is ever applied.
            (
                b"[1,2,3]",
                r#".[(.x):2]? = ["y"]"#,
                Err(r#"Cannot index array with string "x""#),
            ),
            // Same rule on the end bound, and on a string target.
            (
                br#""str""#,
                ".[0:.k]? = 5",
                Err(r#"Cannot index string with string "k""#),
            ),
            // A bound that resolves successfully but isn't a number is also
            // not covered by `?` — unlike a computed key's `key_to_path_component`
            // type check, which `?` *does* cover.
            (
                b"null",
                r#".[("x"):2]? = 5"#,
                Err("Array/string slice indices must be integers"),
            ),
            // Only the final "target isn't sliceable" failure is what `?`
            // covers.
            (b"5", r#".[0:2]? = ["x"]"#, Ok("5")),
            // The target's own evaluation failure is not covered either.
            (
                br#""str""#,
                r#".a[0:2]? = ["x"]"#,
                Err(r#"Cannot index string with string "a""#),
            ),
            // An empty start (or end) bound stream short-circuits before the
            // next stage runs — including before the target is ever touched.
            (b"[1,2,3]", "[(error(\"boom\"))[0:empty]]", Ok("[]")),
            (b"[1,2,3]", "[(error(\"boom\"))[empty:2]]", Ok("[]")),
            // A `null` bound is "open on this side", same as an omitted one.
            (b"[1,2,3,4,5]", ".[(null):(3)]", Ok("[1,2,3]")),
            // A fractional dynamic bound still floors the start / ceils the
            // end, exactly like a literal one.
            (b"[1,2,3,4,5]", ".[(1.7):(2.9)]", Ok("[2,3]")),
            // Multi-value bounds fan out start-outer, end-middle,
            // target-inner — the same nesting order jq's `S as $s | T as $t
            // | E | .[$s:$t]` desugaring produces.
            (
                b"[1,2,3,4,5]",
                "[.[(0,1):(3,4)]]",
                Ok("[[1,2,3],[1,2,3,4],[2,3],[2,3,4]]"),
            ),
            // `path()`, `del()` and `|=` all round-trip through a computed
            // slice, the same as they do through a computed key.
            (
                br#"{"a":[1,2,3],"k1":0,"k2":2}"#,
                "path(.a[.k1:.k2])",
                Ok(r#"["a",{"start":0,"end":2}]"#),
            ),
            (
                br#"{"a":[1,2,3],"k1":0,"k2":2}"#,
                "del(.a[.k1:.k2])",
                Ok(r#"{"a":[3],"k1":0,"k2":2}"#),
            ),
            (
                br#"{"a":[1,2,3],"k1":0,"k2":2}"#,
                ".a[.k1:.k2] |= map(.*10)",
                Ok(r#"{"a":[10,20,3],"k1":0,"k2":2}"#),
            ),
            // A dynamic slice can be a mid-chain component, not just the
            // final one — including under `?`, which (unlike the fully
            // static `.a[1:2]?[0]` shape — a separate, pre-existing gap)
            // goes through the computed-key prepass and so has its
            // `Expr::Optional` wrapper stripped before `set_path` runs.
            (
                br#"{"a":[1,2,3,4],"k1":0,"k2":2}"#,
                ".a[.k1:.k2][0] = 9",
                Ok(r#"{"a":[9,2,3,4],"k1":0,"k2":2}"#),
            ),
            (
                br#"{"a":[1,2,3,4],"k1":0,"k2":2}"#,
                ".a[.k1:.k2]?[0] = 9",
                Ok(r#"{"a":[9,2,3,4],"k1":0,"k2":2}"#),
            ),
        ]);
    }

    /// #499: `needs_path_context` mirrors `IndexExpr`'s target/key check
    /// (#360) for a computed slice's target and both bounds — a `path`/
    /// `parent`/`key` builtin (yq's no-arg path-context extensions) hiding in
    /// any of the three must still be found, or `eval_pipe` would run the
    /// pipe without the path context those builtins read.
    #[test]
    fn test_needs_path_context_descends_into_slice_expr() {
        let path_ctx = Expr::Builtin(Builtin::PathNoArg);
        let plain = Expr::Literal(Literal::Int(0));

        // Hidden in the target.
        assert!(needs_path_context(&Expr::slice_by(
            path_ctx.clone(),
            Some(plain.clone()),
            Some(plain.clone()),
        )));
        // Hidden in the start bound (target and end plain).
        assert!(needs_path_context(&Expr::slice_by(
            Expr::Identity,
            Some(path_ctx.clone()),
            Some(plain.clone()),
        )));
        // Hidden in the end bound (target and start plain).
        assert!(needs_path_context(&Expr::slice_by(
            Expr::Identity,
            Some(plain.clone()),
            Some(path_ctx),
        )));
        // None of the three need it.
        assert!(!needs_path_context(&Expr::slice_by(
            Expr::Identity,
            Some(plain.clone()),
            Some(plain),
        )));
    }

    /// #499: `eval_slice_expr` (plain reads, no `=`/`|=`/`path()`/`del()`)
    /// covering the shapes `test_computed_slice_bounds` doesn't reach — every
    /// case there goes through path resolution (`resolve_slice_expr`), a
    /// separate function with its own copy of this logic, so none of it
    /// exercised the read-mode evaluator at all. `(0+0)`/`(2+0)` stand in for
    /// a bound that must stay dynamic; a bare `(0)`/`(2)` folds back to the
    /// literal `Expr::Slice` fast path (`test_slice_bounds_accept_the_same_
    /// spellings`) and would silently test the wrong code entirely. Every
    /// case was checked against jq 1.7.1 directly.
    #[test]
    fn test_computed_slice_bounds_read_mode() {
        assert_outcomes(&[
            // Fast path: a resolved `(0, None)` bound still returns the
            // target unchanged, same as the literal `.[0:]` shape.
            (b"[1,2,3,4,5]", ".[(0+0):]", Ok("[1,2,3,4,5]")),
            // A bound that's a plain field read, not an arithmetic
            // expression — unlike every `(n+0)` bound elsewhere in this
            // test, this resolves to a *borrowed* value straight from the
            // document rather than a freshly computed owned one.
            (
                br#"{"a":[1,2,3,4,5],"k1":1,"k2":3}"#,
                ".a[.k1:.k2]",
                Ok("[2,3]"),
            ),
            // A bound that fans out to more than one borrowed value.
            (
                br#"{"a":[1,2,3,4,5],"x":0,"y":1}"#,
                "[.a[(.x,.y):(3+0)]]",
                Ok("[[1,2,3],[2,3]]"),
            ),
            // A borrowed target that slices to `null` (slicing `null` is
            // always `null`) and one that fails to slice at all.
            (br#"{"a":null}"#, ".a[(0+0):(2+0)]", Ok("null")),
            (
                br#"{"a":5}"#,
                ".a[(0+0):(2+0)]",
                Err("Cannot index number with object"),
            ),
            // The same borrowed failure, but `?`-guarded: the slice attempt
            // is pruned rather than propagated — the borrowed-value
            // counterpart to the owned-boolean case below.
            (br#"{"a":5}"#, ".a[(0+0):(2+0)]?", Ok("")),
            // The target's own evaluation can fail before slicing is ever
            // attempted — distinct from the case above, where `.a` resolves
            // fine and it's the slice application that fails.
            (
                b"5",
                ".a[(0+0):(2+0)]",
                Err(r#"Cannot index number with string "a""#),
            ),
            // A target that fans out to more than one borrowed value.
            (
                br#"{"a":[1,2,3],"b":[4,5,6]}"#,
                "[(.a,.b)[(0+0):(2+0)]]",
                Ok("[[1,2],[4,5]]"),
            ),
            // An owned target (freshly constructed, not borrowed from the
            // document): single value, then a fan-out of several.
            (b"null", "([1,2,3])[(0+0):(2+0)]", Ok("[1,2]")),
            (
                b"null",
                "[([1,2,3],[4,5,6])[(0+0):(2+0)]]",
                Ok("[[1,2],[4,5]]"),
            ),
            // A target with no output at all.
            (b"null", "empty[(0+0):(2+0)]", Ok("")),
            // A target that breaks out of an enclosing label — the whole
            // slice contributes nothing, same as `IndexExpr`'s identically
            // conservative target handling (see `eval_index_expr`'s key
            // stream, which this mirrors).
            (b"null", "label $out | (break $out)[(0+0):(2+0)]", Ok("")),
            (
                b"null",
                "label $out | (1,2,break $out)[(0+0):(2+0)]",
                Ok(""),
            ),
            // A target whose stream errors part-way through: the error wins,
            // and (like the break case above) the values already produced
            // are not carried forward — the same conservative trade-off
            // `eval_index_expr` already makes for its key/target streams.
            (b"null", "(1,2,error(\"boom\"))[(0+0):(2+0)]", Err("boom")),
            // Owned targets of every slice-able kind, plus the two ways an
            // unsliceable one is refused.
            (b"null", "(null)[(0+0):(2+0)]", Ok("null")),
            (b"null", r#"("hello")[(0+0):(2+0)]"#, Ok(r#""he""#)),
            (b"null", "(true)[(0+0):(2+0)]?", Ok("")),
            (
                b"null",
                "(true)[(0+0):(2+0)]",
                Err("Cannot index boolean with object"),
            ),
            // A start-bound evaluation failure, and the same on the end
            // bound — each is its own call site in `eval_slice_expr`.
            (
                b"[1,2,3]",
                r".[(.x+0):(2+0)]",
                Err(r#"Cannot index array with string "x""#),
            ),
            (
                b"[1,2,3]",
                r".[(0+0):(.x+0)]",
                Err(r#"Cannot index array with string "x""#),
            ),
            // A `break` from inside a bound must reach the enclosing label
            // as a real break, not a synthetic "not in label" error — on
            // both the start and the end bound.
            (b"[1,2,3]", "label $out | .[(break $out):(2+0)]", Ok("")),
            (b"[1,2,3]", "label $out | .[(0+0):(break $out)]", Ok("")),
            // A bound whose stream breaks (or errors) after already
            // producing values: unlike the target case above, the bound
            // stream's own partial prefix is kept, not discarded (#1528) --
            // confirmed against jq 1.7.1: both cases print `[2]` then `[]`
            // (from `$s=1`/`$s=2` against the fixed end bound `2`) before the
            // break/error fires on `$s`'s third candidate. `outcome()`'s own
            // `Err` arm only matches a zero-prefix `QueryResult::Error`, so a
            // `Partial` terminating in an error is asserted here as `Ok` of
            // its already-collected prefix, same as the break case --
            // this test harness doesn't itself assert the trailing error.
            (
                b"[1,2,3]",
                "label $out | .[(1,2,break $out):(2+0)]",
                Ok("[2] []"),
            ),
            (b"[1,2,3]", r#".[(1,2,error("boom")):(2+0)]"#, Ok("[2] []")),
        ]);
    }

    /// #499: `resolve_slice_expr`/`resolve_slice_bound` (the path-mode
    /// evaluator behind `=`, `|=`, `path()`, `del()`) shapes
    /// `test_computed_slice_bounds` doesn't reach: every bound there either
    /// resolves to a number or fails to *evaluate* at all, so the
    /// empty-bound-stream short-circuit and the "resolved bounds don't apply
    /// to this target" refusal never ran. Checked against jq 1.7.1 directly.
    #[test]
    fn test_computed_slice_bounds_path_mode_edge_cases() {
        assert_outcomes(&[
            // An empty start (or end) bound stream in path mode is a no-op,
            // the same short-circuit `test_computed_slice_bounds` already
            // covers for read mode.
            (
                br#"{"a":[1,2,3]}"#,
                r#".a[empty:2] = ["x"]"#,
                Ok(r#"{"a":[1,2,3]}"#),
            ),
            (
                br#"{"a":[1,2,3]}"#,
                r#".a[0:empty] = ["x"]"#,
                Ok(r#"{"a":[1,2,3]}"#),
            ),
            // An omitted bound alongside a dynamic one on the other side —
            // "open on this side" in path mode, same as read mode.
            (
                br#"{"a":[1,2,3,4,5],"k2":3}"#,
                r#".a[:.k2] = ["x"]"#,
                Ok(r#"{"a":["x",4,5],"k2":3}"#),
            ),
            (
                br#"{"a":[1,2,3,4,5],"k1":2}"#,
                r#".a[.k1:] = ["x"]"#,
                Ok(r#"{"a":[1,2,"x"],"k1":2}"#),
            ),
            // Resolved bounds that reach an unsliceable target: `?` prunes
            // just that branch, and its absence propagates the error — the
            // same two spellings `resolve_index_expr` distinguishes for a
            // computed key.
            (b"5", r#".[(0+0):(2+0)]? = ["x"]"#, Ok("5")),
            (
                b"5",
                r#".[(0+0):(2+0)] = ["x"]"#,
                Err("Cannot index number with object"),
            ),
        ]);
    }

    /// #499: a computed slice's target and bounds must round-trip through
    /// user-defined function expansion (`expand_func_calls`/
    /// `substitute_func_param`) the same way `IndexExpr`'s target/key already
    /// do — a call or parameter hiding in any of the three must still be
    /// found and substituted.
    #[test]
    fn test_computed_slice_bounds_in_user_defined_functions() {
        assert_outcomes(&[
            // A function parameter used as a dynamic bound.
            (b"[1,2,3,4]", "def f($n): .[$n:3]; f(1)", Ok("[2,3]")),
            // A recursive-call site hiding in the bound of a different
            // slice, and in its target.
            (b"[1,2,3,4]", "def f: 1; .[(f):(3)]", Ok("[2,3]")),
            (
                br#"{"a":[1,2,3,4]}"#,
                "def f: .a; (f)[(1):(3)]",
                Ok("[2,3]"),
            ),
            (b"[1,2,3,4]", "def f: 3; .[(1):(f)]", Ok("[2,3]")),
        ]);
    }

    #[test]
    fn test_set_path_and_set_path_steps_autovivify_null_directly() {
        // Direct-function coverage for the three walkers `autovivify_object`/
        // `autovivify_array`/`write_index` touch (#486), bypassing the parser.
        let mut root = OwnedValue::Null;
        set_path::<JqSemantics>(
            &mut root,
            &Expr::Field("a".to_string()),
            OwnedValue::Int(1),
            false,
            false,
        )
        .unwrap();
        assert_eq!(
            root,
            OwnedValue::Object(IndexMap::from([("a".to_string(), OwnedValue::Int(1),)]))
        );

        let mut root = OwnedValue::Null;
        set_path::<JqSemantics>(&mut root, &Expr::index(0), OwnedValue::Int(1), false, false)
            .unwrap();
        assert_eq!(root, OwnedValue::Array(vec![OwnedValue::Int(1)]));

        let mut root = OwnedValue::Array(vec![OwnedValue::Int(1), OwnedValue::Int(2)]);
        set_path::<JqSemantics>(&mut root, &Expr::index(4), OwnedValue::Int(9), false, false)
            .unwrap();
        assert_eq!(
            root,
            OwnedValue::Array(vec![
                OwnedValue::Int(1),
                OwnedValue::Int(2),
                OwnedValue::Null,
                OwnedValue::Null,
                OwnedValue::Int(9),
            ])
        );

        // `set_path_steps` vivifies each intermediate as it walks a
        // multi-part chain, not just the first step (#1429: this used to be
        // `get_path_mut`'s job, and its own direct-call coverage).
        let mut root = OwnedValue::Object(IndexMap::new());
        let steps = [
            Expr::Field("a".to_string()),
            Expr::Field("b".to_string()),
            Expr::Field("c".to_string()),
        ];
        set_path_steps::<JqSemantics>(
            &mut root,
            &steps,
            OwnedValue::Int(7),
            false,
            false,
            iterate_suffix_len(&steps),
        )
        .unwrap();
        assert_eq!(
            root,
            OwnedValue::Object(IndexMap::from([(
                "a".to_string(),
                OwnedValue::Object(IndexMap::from([(
                    "b".to_string(),
                    OwnedValue::Object(IndexMap::from([("c".to_string(), OwnedValue::Int(7))])),
                )])),
            )]))
        );
    }

    /// #1494: `set_path`/`set_path_steps` threaded `S:
    /// EvalSemantics` through to `cannot_iterate_with(S::TAG, ...)`,
    /// matching the other four call sites this issue covers.
    ///
    /// Note on reachability: `eval_assign` -- the only external caller --
    /// always passes `scalar_noop = (S::TAG == EvalTag::Yq)` for plain `=`
    /// (no operator-based exception the way `-=`/`*=` have), and
    /// `is_yq_field_index_noop_scalar` is unconditionally `true` for any
    /// non-container, non-null value -- exactly what reaches the `_` arm
    /// these `cannot_iterate_with` calls live in. So with `scalar_noop =
    /// true`, the no-op guard *always* wins first in real yq-mode usage
    /// today (confirmed live: `succinctly yq '(1.0+2.0) | .[] = 9'` prints
    /// `3.0` unchanged, never errors) -- `cannot_iterate_with(EvalTag::Yq,
    /// ..)` is correctly wired but not yet reachable through that one
    /// caller. This test calls both functions directly with
    /// `scalar_noop: false` to verify the wiring itself, independent of
    /// whether today's one caller happens to exercise it.
    #[test]
    fn test_set_path_cannot_iterate_uses_the_real_mode_tag_1494() {
        let mut root = OwnedValue::Float(3.0);
        let err =
            set_path::<YqSemantics>(&mut root, &Expr::Iterate, OwnedValue::Int(9), false, false)
                .unwrap_err();
        assert_eq!(err.message, "Cannot iterate over number (3.0)");

        let mut root = OwnedValue::Float(3.0);
        let err =
            set_path::<JqSemantics>(&mut root, &Expr::Iterate, OwnedValue::Int(9), false, false)
                .unwrap_err();
        assert_eq!(err.message, "Cannot iterate over number (3)");

        // The mid-chain fan-out arm, which #1429 folded out of
        // `set_path_through_iterate` and into `set_path_steps` -- reached
        // with a real tail after the `.[]` so it is the mid-chain arm and
        // not the terminal one above that raises.
        let steps = [Expr::Iterate, Expr::Field("b".to_string())];
        let mut target = OwnedValue::Float(3.0);
        let err = set_path_steps::<YqSemantics>(
            &mut target,
            &steps,
            OwnedValue::Int(9),
            false,
            false,
            iterate_suffix_len(&steps),
        )
        .unwrap_err();
        assert_eq!(err.message, "Cannot iterate over number (3.0)");

        let mut target = OwnedValue::Float(3.0);
        let err = set_path_steps::<JqSemantics>(
            &mut target,
            &steps,
            OwnedValue::Int(9),
            false,
            false,
            iterate_suffix_len(&steps),
        )
        .unwrap_err();
        assert_eq!(err.message, "Cannot iterate over number (3)");
    }

    #[test]
    fn test_del_field() {
        // del(.a) removes a field
        query!(br#"{"a": 1, "b": 2}"#, r"del(.a)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert!(!obj.contains_key("a"));
                assert!(obj.contains_key("b"));
            }
        );
    }

    #[test]
    fn test_del_array_element() {
        // del(.[1]) removes an array element
        query!(br"[1, 2, 3]", r"del(.[1])",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 2);
                assert_eq!(arr[0], OwnedValue::Int(1));
                assert_eq!(arr[1], OwnedValue::Int(3));
            }
        );
    }

    #[test]
    fn test_del_nested() {
        // del(.a.b) removes nested field
        query!(br#"{"a": {"b": 1, "c": 2}}"#, r"del(.a.b)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                let a = obj.get("a").unwrap();
                if let OwnedValue::Object(inner) = a {
                    assert!(!inner.contains_key("b"));
                    assert!(inner.contains_key("c"));
                } else {
                    panic!("Expected nested object");
                }
            }
        );
    }

    /// `delete_path_steps`'s (#2115) `Expr::Index` arm reassigns `root` to an
    /// existing array element and loops rather than recursing -- covered
    /// here by continuing one more step (`.b`) past it, so the walk doesn't
    /// stop at the very first component.
    #[test]
    fn test_del_index_then_field_peels_in_place_2115() {
        query!(br#"{"a": [{"b": 1}, {"b": 2}]}"#, r"del(.a[1].b)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                let OwnedValue::Array(arr) = obj.get("a").unwrap() else {
                    panic!("expected array");
                };
                let OwnedValue::Object(first) = &arr[0] else {
                    panic!("expected object");
                };
                assert!(first.contains_key("b"), "del() touched the wrong element");
                let OwnedValue::Object(second) = &arr[1] else {
                    panic!("expected object");
                };
                assert!(!second.contains_key("b"), "del() left the key behind");
            }
        );
    }

    #[test]
    fn test_del_through_a_missing_field_walks_the_rest_against_null() {
        // #527: a field the object doesn't have reads as `null`, and jq keeps
        // walking the rest of the path against that `null` rather than
        // stopping at it — so the *tail* decides whether this is a no-op.
        // These all reach `delete_at_path`'s `Expr::Pipe` chain-walk, which
        // used to raise succinctly's own `field 'b' not found`.
        query!(br#"{"a": {"x": 1}}"#, r"del(.a.b.c)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                let OwnedValue::Object(inner) = obj.get("a").unwrap() else {
                    panic!("expected nested object");
                };
                assert!(inner.contains_key("x"));
                // Walking through the absent key must not materialise it.
                assert!(!inner.contains_key("b"), "del() created the missing key");
            }
        );
        // The missing key can be the first component too.
        query!(br#"{"a": 1}"#, r"del(.b.c)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert!(obj.contains_key("a"));
                assert!(!obj.contains_key("b"), "del() created the missing key");
            }
        );
        // Any length of `Field` tail, and an `Index`/`Slice` tail, stay
        // no-ops: `null` tolerates all three (#476).
        for filter in [r"del(.a.b.c.d)", r"del(.a.b[0])", r"del(.a.b[1:2])"] {
            query!(br#"{"a": {"x": 1}}"#, filter,
                QueryResult::Owned(OwnedValue::Object(obj)) => {
                    let OwnedValue::Object(inner) = obj.get("a").unwrap() else {
                        panic!("expected nested object");
                    };
                    assert_eq!(inner.len(), 1, "`{filter}` changed the object");
                }
            );
        }
        // An `[]` tail is the exception — iterating `null` raises in jq, and
        // a `?` on the *missing* step does not suppress what the tail itself
        // raises.
        query!(br#"{"a": {"x": 1}}"#, r"del(.a.b[])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over null (null)");
            }
        );
        query!(br#"{"a": {"x": 1}}"#, r"del(.a.b?[])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over null (null)");
            }
        );
        // `?` on the iterate step itself does suppress it.
        query!(br#"{"a": {"x": 1}}"#, r"del(.a.b[]?)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                let OwnedValue::Object(inner) = obj.get("a").unwrap() else {
                    panic!("expected nested object");
                };
                assert_eq!(inner.len(), 1);
            }
        );
        // The `[]` can be any distance past the absent key — the walk has to
        // survive more than one step, which is what makes this a walk rather
        // than a one-off check of the very next component.
        for filter in [r"del(.a.b.c[])", r"del(.a.b[0][])", r"del(.a.b[1:2][])"] {
            query!(br#"{"a": {"x": 1}}"#, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "Cannot iterate over null (null)", "`{filter}`");
                }
            );
        }
    }

    #[test]
    fn test_del_through_null_still_raises_on_an_iterate_tail() {
        // #476 exempted `null` from `Field`/`Index`/`Slice` steps but
        // explicitly not from `.[]`, which jq refuses on `null` — and the
        // exemption is per *step*, so it cannot be granted by returning early
        // and skipping whatever the path still had to say. #527: every one of
        // these used to be a silent no-op.
        for (json, filter) in [
            (&br"null"[..], r"del(.a[])"),
            (&br"null"[..], r"del(.a.b[])"),
            (&br"null"[..], r"del(.[0][])"),
            (&br"null"[..], r"del(.[0:2][])"),
            (&br#"{"x": null}"#[..], r"del(.x.a[])"),
            (&br#"{"a": {"b": null}}"#[..], r"del(.a.b.c[])"),
        ] {
            query!(json, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "Cannot iterate over null (null)", "`{filter}`");
                }
            );
        }
        // Every other tail keeps the #476 no-op it already had.
        for filter in [r"del(.a.b)", r"del(.[0].a)", r"del(.[0:2].a)"] {
            query!(br"null", filter,
                QueryResult::Owned(OwnedValue::Null) => {}
            );
        }
    }

    #[test]
    fn test_del_through_an_out_of_range_index_still_raises_on_an_iterate_tail() {
        // #529: an out-of-range index (positive, negative, or into an empty
        // array) reads as `null` just like a missing field does (#527), and
        // jq keeps walking the rest of the path against that `null` — so a
        // `[]` tail still raises `Cannot iterate over null (null)` even
        // though every other tail stays a no-op. Both `[1,2]`'s single-path
        // walker (`delete_at_path`) and its grouped/comma walker
        // (`delete_trie_array`) must agree.
        for (json, filter) in [
            (&br"[1,2]"[..], r"del(.[5][])"),
            (&br#"{"a":[1,2]}"#[..], r"del(.a[5][])"),
            (&br"[1,2]"[..], r"del(.[-5][])"),
            (&br"[]"[..], r"del(.[0][])"),
            (&br#"{"a":[]}"#[..], r"del(.a[0][])"),
            // The `[]` can sit further down than the very next component.
            (&br"[1,2]"[..], r"del(.[5].c[])"),
            (&br"[1,2]"[..], r"del(.[5][1:2][])"),
            // A `?` on the out-of-range step does not suppress what the tail
            // itself raises.
            (&br"[1,2]"[..], r"del(.[5]?[])"),
            // Grouped/comma spelling must land the same as the single path.
            (&br"[1,2]"[..], r"del(.[5][], .[6][])"),
        ] {
            query!(json, filter,
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "Cannot iterate over null (null)", "`{filter}`");
                }
            );
        }
        // `?` on the iterate step itself does suppress it.
        query!(br"[1,2]", r"del(.[5][]?)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![OwnedValue::Int(1), OwnedValue::Int(2)]);
            }
        );
        // Every other tail keeps the #477 no-op it already had, single-path
        // and grouped alike.
        for filter in [
            r"del(.[5])",
            r"del(.[5].a)",
            r"del(.[-5])",
            r"del(.[5], .[6])",
        ] {
            query!(br"[1,2]", filter,
                QueryResult::Owned(OwnedValue::Array(arr)) => {
                    assert_eq!(arr, vec![OwnedValue::Int(1), OwnedValue::Int(2)], "`{filter}`");
                }
            );
        }
    }

    #[test]
    fn test_del_field_through_null_is_a_no_op() {
        // #476: `null` tolerates any field key, so `null | del(.a)` is `null`
        // rather than `Cannot index null with string "a"`, matching jq.
        query!(br"null", r"del(.a)",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
        // The exemption applies mid-chain too: `.x` stays `null` untouched.
        query!(br#"{"x": null}"#, r"del(.x.a)",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("x"), Some(&OwnedValue::Null));
            }
        );
        // And when `null` is the root of a 2+-element chain itself (rather
        // than reached by descending into an already-null field) — this
        // exercises the `Null` arm inside the `Expr::Pipe` chain-walk, a
        // separate code path from the single-step arm above.
        query!(br"null", r"del(.a.b)",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
    }

    #[test]
    fn test_del_index_through_null_is_a_no_op() {
        // #476: same exemption for a numeric index — `null | del(.[0])` is
        // `null`, matching jq's `null | .[0]` reading `null` back.
        query!(br"null", r"del(.[0])",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
        query!(br#"{"x": null}"#, r"del(.x[0])",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("x"), Some(&OwnedValue::Null));
            }
        );
        // Same chain-root case as the field test above, for the `Index`
        // arm's `Null` case inside the `Expr::Pipe` chain-walk.
        query!(br"null", r"del(.[0].a)",
            QueryResult::Owned(OwnedValue::Null) => {}
        );
    }

    #[test]
    fn test_del_field_on_wrong_type_respects_optional() {
        // A genuinely wrong (non-null) type still respects `?`, both as the
        // sole path component and mid-chain: no-op rather than error.
        query!(br"5", r"del(.a?)",
            QueryResult::Owned(OwnedValue::Int(5) | OwnedValue::NumberLiteral(NumberRepr::Int(5), _)) => {}
        );
        query!(br"5", r"del(.a?.b)",
            QueryResult::Owned(OwnedValue::Int(5) | OwnedValue::NumberLiteral(NumberRepr::Int(5), _)) => {}
        );
        // Without `?`, the same wrong type still raises, mid-chain too.
        query!(br"5", r"del(.a.b)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with string \"a\"");
            }
        );
    }

    #[test]
    fn test_del_index_on_wrong_type_respects_optional() {
        // Same shape as the field test above, for a numeric index.
        query!(br"5", r"del(.[0]?)",
            QueryResult::Owned(OwnedValue::Int(5) | OwnedValue::NumberLiteral(NumberRepr::Int(5), _)) => {}
        );
        query!(br"5", r"del(.[0]?.a)",
            QueryResult::Owned(OwnedValue::Int(5) | OwnedValue::NumberLiteral(NumberRepr::Int(5), _)) => {}
        );
        query!(br"5", r"del(.[0])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with number");
            }
        );
        query!(br"5", r"del(.[0].a)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with number");
            }
        );
    }

    #[test]
    fn test_del_slice_on_string_target_ignores_optional_1312() {
        // #1312: `delete_at_path`'s standalone (terminal) `Expr::Slice` arm
        // checked its `_ if optional => Ok(())` catch-all *before* the
        // `OwnedValue::String(_)` arm, so a `?`-marked slice targeting a
        // string was shadowed into a silent no-op instead of raising. Real
        // jq's inline `?` only suppresses a failure to *reach* a target, not
        // a write-time application refusal like this one -- the same
        // distinction #1303 fixed for `=`'s equivalent gap. A genuinely
        // non-sliceable target (a `?`-marked slice on a boolean) is a
        // navigation failure and stays correctly suppressed either way. All
        // confirmed against real jq 1.7.1.
        query!(br#""hello""#, r"del(.[0:1]?)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot delete fields from string");
            }
        );
        query!(br#"{"a":"hello"}"#, r"del(.a[0:1]?)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot delete fields from string");
            }
        );
        // Unaffected: no `?` at all still errors the same way.
        query!(br#""hello""#, r"del(.[0:1])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot delete fields from string");
            }
        );
        // Unaffected: an array slice target still deletes normally.
        query!(br"[1,2,3]", r"del(.[0:1]?)",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "[2,3]");
            }
        );
        // Unaffected: a genuinely non-sliceable target under `?` stays
        // suppressed -- this is a navigation failure, not a write-time one.
        query!(br"true", r"del(.[0:1]?)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

    #[test]
    fn test_del_string_slice_mid_chain_reports_the_tail_own_error_1321() {
        // #1321: found verifying #1312, which only fixed the *standalone*
        // (terminal) `Expr::Slice` arm above. This is the different,
        // mid-chain case (more path *after* the slice) -- `through_slice`
        // itself unconditionally refused any `OwnedValue::String` root
        // before this fix, masking whatever the *tail*'s own navigation
        // would have raised. All confirmed live against real jq 1.7.1.
        query!(br#"{"a":"hello"}"#, r"del(.a[0:1].b)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"Cannot index string with string "b""#);
            }
        );
        query!(br#"{"a":"hello"}"#, r"del(.a[0:1][0])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index string with number");
            }
        );
        query!(br#"{"a":"hello"}"#, r"del(.a[0:1][])",
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"Cannot iterate over string ("h")"#);
            }
        );
        // Bare-root mid-chain (no `.a` prefix) -- the same fix, reached via
        // `delete_at_path`'s Pipe arm directly rather than through a
        // preceding `Expr::Field` step.
        query!(br#""hello""#, r"del(.[0:1].b)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"Cannot index string with string "b""#);
            }
        );
        // `?` on the tail component suppresses *that* component's own
        // failure, no-op'ing the whole thing -- distinct from `?` on the
        // slice itself (`test_del_slice_on_string_target_ignores_optional_
        // 1312` above), which never suppresses the write-time refusal.
        query!(br#"{"a":"hello"}"#, r"del(.a[0:1].b?)",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":"hello"}"#);
            }
        );
        query!(br#"{"a":"hello"}"#, r"del(.a[0:1][0]?)",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":"hello"}"#);
            }
        );
        // Array/object mid-chain targets are unaffected -- still splice the
        // sub-range's own deletion back, matching pre-existing behavior.
        query!(br"[1,[2],[3]]", r"del(.[1:3][0])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "[1,[3]]");
            }
        );
    }

    #[test]
    fn test_del_string_slice_mid_chain_yq_mode_unaffected_1321() {
        // #1321 code review: yq mode's own del() call site into
        // `through_slice` deliberately forces `terminal_write: true` for a
        // string target, keeping the OLD, unconditional "Cannot update
        // string slices" refusal there byte-for-byte unchanged -- NOT the
        // new jq-mode fix above. At the time #1321 landed, this was the
        // same real-yq-diverges gap #1219 tracked for a container target
        // (`del(.a[1:3][0])` on an array), left open as "#1219's own scope
        // to fix, not this issue's."
        //
        // #1219 has since landed and closes this string case too, as a
        // side effect rather than a deliberate target: `yq_del_slice_
        // outcome` classifies a chained-slice-then-non-slice path as
        // `Noop` from its *shape* alone, before `builtin_del` ever calls
        // `delete_at_path` -- so `through_slice`'s `terminal_write` forcing
        // above is never reached for this query at all, regardless of
        // `.a`'s type. The whole `del()` call now correctly no-ops,
        // matching real yq exactly (confirmed live, `del(.a[0:1].b)` on
        // `a: hello` leaves `a: hello` untouched) -- this test's own
        // *previous* expectation (the old, unconditional "Cannot update
        // string slices" error) is what's now stale, not this update.
        yq_query!(br#"{"a":"hello"}"#, r"del(.a[0:1].b)",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":"hello"}"#);
            }
        );
        // jq mode is unaffected by #1219's yq-only gating -- still the
        // ordinary per-step error #1312/#1321 already established above.
        query!(br#"{"a":"hello"}"#, r"del(.a[0:1].b)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"Cannot index string with string "b""#);
            }
        );
    }

    #[test]
    fn test_assign_string_slice_mid_chain_reports_the_tail_own_error_1321() {
        // #1321 also affects `=`/`|=`: `through_slice` is the single choke
        // point both share with `del()`. `.a[0:1].b = 5` reports the
        // tail's own field-access error rather than masking it behind the
        // slice's own "cannot update string slices" refusal -- confirmed
        // live against real jq 1.7.1.
        query!(br#"{"a":"hello"}"#, r".a[0:1].b = 5",
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"Cannot index string with string "b""#);
            }
        );
        query!(br#"{"a":"hello"}"#, r".a[0:1].b? = 5",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":"hello"}"#);
            }
        );
        // The slice itself as the terminal write target (nothing after
        // it) must still refuse, whether reached bare-root or through a
        // preceding field -- this is the terminal-slice case (#1429's
        // `set_path_steps` reaches it as a one-element `steps`; before that
        // it was `split_at_slice`'s `Identity` tail), which looks
        // structurally identical to the mid-chain case above but must NOT
        // get the same treatment (code review, #1321:
        // an earlier version of this fix mis-classified it and silently
        // no-op'd `.a[0:1] = v` instead of erroring).
        query!(br#"{"a":"hello"}"#, r#".a[0:1] = ["x"]"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot update string slices");
            }
        );
        query!(br#""hello""#, r#".[0:1] = ["x"]"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot update string slices");
            }
        );
        query!(br#"{"a":"hello"}"#, r#".a[0:1] |= (. + "X")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot update string slices");
            }
        );
        // Array/object mid-chain assignment targets are unaffected.
        query!(br"[1,2,3,4]", r".[1:3][] |= .*10",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "[1,20,30,4]");
            }
        );
    }

    /// #1340: `through_slice`'s `Null` target used to be a silent
    /// non-suppressible catch-all no-op-or-error before this fix, rather
    /// than a real auto-vivification attempt -- `set_value_at_path`
    /// (`setpath()`'s own walker) already got this right, and `through_slice`
    /// (`=`/`|=`'s shared choke point) had drifted from it. Every case here
    /// is oracle-verified against real jq 1.7.1.
    #[test]
    fn test_assign_slice_mid_chain_null_target_auto_vivifies_1340() {
        // The issue's own repro: a further path step after an absent
        // field's slice raises the tail's write-time application error
        // instead of silently no-op'ing.
        query!(br#"{"c":0}"#, r"(.b[0:1]? | .c) = 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "A slice of an array can only be assigned another array");
            }
        );
        // Same without the `?` -- `?` never suppresses this class of error.
        query!(br#"{"c":0}"#, r"(.b[0:1] | .c) = 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "A slice of an array can only be assigned another array");
            }
        );
        query!(br#"{"c":0}"#, r".b[0:1]? = 5",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "A slice of an array can only be assigned another array");
            }
        );
        // The terminal slice write itself still auto-vivifies successfully
        // when the RHS genuinely is an array -- this was ALSO broken before
        // this fix (it hard-errored with "Cannot index null with object"),
        // even though it isn't the shape #1340 was filed against.
        query!(br#"{"c":0}"#, r".b[0:1] = [1]",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"c":0,"b":[1]}"#);
            }
        );
        query!(br#"{"c":0}"#, r".b[0:1]? = [1]",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"c":0,"b":[1]}"#);
            }
        );
        // `|=` shares `through_slice`, so it shares the bug and the fix.
        query!(br#"{"c":0}"#, r".b[0:1].c |= 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "A slice of an array can only be assigned another array");
            }
        );
        query!(br#"{"c":0}"#, r".b[0:1] |= [1]",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"c":0,"b":[1]}"#);
            }
        );
        // A genuinely non-vivifiable scalar (not `Null`) with `?` on the
        // slice is unaffected -- still an ordinary suppressed navigation
        // failure, not a write-time application error.
        query!(br"5", r"(.[0:1]? | .c) = 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "5");
            }
        );
        // A root that is already an array (not auto-vivified from `Null`)
        // is unaffected -- still fails indexing the sliced array directly,
        // a different, correct message for a different shape.
        query!(br#"{"b":[10,20,30]}"#, r".b[0:1].c = 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"Cannot index array with string "c""#);
            }
        );
    }

    /// #1873: `through_slice`'s `Null` arm (added by #1340 above) required
    /// `edit`'s result to become an `Array` unconditionally, even for a
    /// mid-chain tail (`terminal_write: false`) whose own navigation
    /// determines there's nothing to write at all -- a `?`-suppressed
    /// `cannot_iterate` over the empty slice range leaves `edit`'s `sub`
    /// untouched at `Null`, which used to be forced through the array
    /// check and raise "A slice of an array can only be assigned another
    /// array" where real jq leaves the whole document unchanged (verified
    /// live against `/usr/bin/jq` 1.7.1: `null | .a[0:1][]? = 9` is `null`).
    /// This test asserts only the no-error/error split and the shapes whose
    /// exact output does match jq byte-for-byte -- the sibling test below
    /// characterizes the one shape whose exact output does not (a separate,
    /// pre-existing bug, #1428).
    #[test]
    fn test_assign_slice_mid_chain_iterate_over_null_noops_1873() {
        // The fix itself: no longer a write-time error. `null`, `{}` and
        // `{"a":null}` all reach `through_slice` with byte-identical state
        // (`Field("a")` navigation converges every one of them to a fresh
        // `&mut Null`), so one representative root suffices here -- the
        // sibling characterization test below is where the exact resulting
        // value (which does differ per root, via #1428) is pinned.
        query!(br"null", r".a[0:1][]? = 9", QueryResult::Owned(_) => {});
        // `|=` and every compound assignment operator desugar through the
        // same `through_slice`/`set_path`-or-`update_path` arm, so they
        // share the bug and the fix identically -- oracle-verified each
        // one is a no-op on `null` in real jq too (`+=`/`-=`/`*=`/`/=`/
        // `//=`/`%=`, not just `|=`).
        for op in ["|=", "+=", "-=", "*=", "/=", "//=", "%="] {
            query!(br"null", &format!(".a[0:1][]? {op} 9"), QueryResult::Owned(_) => {});
        }
        // A non-optional `Iterate` tail still raises the ordinary
        // navigation failure -- unaffected by this fix since `edit`
        // propagates the error before `sub` is ever inspected. Oracle-
        // verified: `/usr/bin/jq` raises the identical message.
        query!(br"null", r".a[0:1][] = 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over null (null)");
            }
        );
        // A `Field` tail after the slice still has to raise the array
        // requirement -- `edit` autovivifies `sub` into an `Object`, never
        // leaving it `Null`, so it still falls through to the existing
        // check. Oracle-verified this errors identically with or without
        // `?` on the field (`?` never suppresses this error class), so one
        // case covers both.
        query!(br"null", r".a[0:1].b? = 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "A slice of an array can only be assigned another array");
            }
        );
        // A literal `null` RHS on the terminal slice write itself is a
        // different shape (`terminal_write: true`) and must still error --
        // `sub` staying `Null` there reflects the RHS, not a swallowed
        // no-op. Oracle-verified: `/usr/bin/jq` raises the identical error.
        query!(br"null", r".a[0:1] = null",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "A slice of an array can only be assigned another array");
            }
        );
        // An `Index` tail after the slice still auto-vivifies successfully
        // -- `edit` leaves `sub` as a real `Array`, never `Null`, so this
        // exact value is oracle-verified against `/usr/bin/jq` (no #1428
        // stub involved: the result never touches the eager-autovivify
        // path, since `sub` genuinely becomes the array being spliced in).
        query!(br"null", r".a[0:1][0]? = 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":[9]}"#);
            }
        );
        // An existing array parent is unaffected either way -- `root`
        // never reaches the `Null` arm at all for this shape. Exact values
        // oracle-verified.
        query!(br#"{"a":[1,2,3]}"#, r".a[0:1][]? = 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":[9,2,3]}"#);
            }
        );
        query!(br#"{"a":[1,2,3]}"#, r".a[0:1][]? |= 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"a":[9,2,3]}"#);
            }
        );
    }

    /// Was a characterization test pinning the `.a: null` stub #1873's fix
    /// left behind, with the standing instruction "if #1428 is ever fixed,
    /// update these expectations to match real jq instead". #1428 is fixed,
    /// so these now assert `/usr/bin/jq` 1.7.1's own answers: the document is
    /// left completely untouched, because an `Iterate` over the `Null` that
    /// autovivification produced has no elements to assign to, so the write
    /// never happens and the chain built to reach it is never committed.
    ///
    /// Kept under its original subject (a slice with a mid-chain iterate
    /// tail) rather than folded into the `#1428` tests in
    /// `tests/jq_cli_tests.rs`: this exercises the library entry point
    /// directly, and it is the shape where `through_slice`'s own `Null` arm
    /// and #1428's parent-probe have to agree.
    #[test]
    fn test_assign_slice_mid_chain_iterate_over_null_leaves_document_untouched_1428() {
        query!(br"null", r".a[0:1][]? = 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r"null");
            }
        );
        query!(br#"{"b":1}"#, r".a[0:1][]? = 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"b":1}"#);
            }
        );
        query!(br"null", r".a[0:1][]? |= 9",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r"null");
            }
        );
    }

    /// #1340: yq mode's own `Null`-target no-op (`is_yq_slice_empty_container_
    /// scalar`, #1101/#1116) sits in `through_slice`'s match *before* the new
    /// `OwnedValue::Null` arm this fix adds, so it must keep matching `Null`
    /// first and stay completely unaffected -- confirmed live against real
    /// yq v4.53.3.
    #[test]
    fn test_assign_slice_mid_chain_null_target_yq_mode_unaffected_1340() {
        yq_query!(br#"{"c":0}"#, r".b[0:1] = [1]",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"c":0,"b":null}"#);
            }
        );
        yq_query!(br#"{"c":0}"#, r".b[0:1] = 5",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"{"c":0,"b":null}"#);
            }
        );
        yq_query!(br#"{"c":0}"#, r".b[0:1].c = 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"Cannot index array with string "c""#);
            }
        );
        yq_query!(br#"{"c":0}"#, r"(.b[0:1]? | .c) = 9",
            QueryResult::Error(e) => {
                assert_eq!(e.message, r#"Cannot index array with string "c""#);
            }
        );
    }

    /// #1340 code review: an initial version of this fix's new `Null`
    /// arm fired unconditionally, so yq's `-=`/`*=` (both `scalar_noop ==
    /// false`, unclaimed by the arm above) fell into it too and started
    /// attempting jq-style auto-vivification instead of their own,
    /// different (already broken, pre-existing) yq behavior -- the arm is
    /// now gated on `!container_noop` (jq mode only) specifically so this
    /// can't happen. Pins that `-=`/`*=` on a null slice target, terminal
    /// or mid-chain, are byte-for-byte identical to the pre-#1340-fix
    /// baseline (verified against a build of `main` before this PR).
    #[test]
    fn test_assign_slice_mid_chain_null_target_yq_mode_sub_mul_unaffected_1340() {
        for op in ["-=", "*="] {
            yq_query!(br#"{"c":0}"#, &format!(".b[0:1] {op} 5"),
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "Cannot index null with object");
                }
            );
            yq_query!(br#"{"c":0}"#, &format!(".b[0:1].c {op} 9"),
                QueryResult::Error(e) => {
                    assert_eq!(e.message, "Cannot index null with object");
                }
            );
        }
        // jq mode is structurally unaffected either way: `scalar_slice_noop`
        // only ever reaches `through_slice` gated by `S::TAG == EvalTag::Yq`
        // (`eval_update`), and the new `Null` arm's own `!container_noop`
        // guard is the same gate in the opposite direction -- both leave jq
        // mode exactly as it already was.
        query!(br#"{"c":0}"#, r".b[0:1] -= [1]",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "null (null) and array ([1]) cannot be subtracted");
            }
        );
    }

    #[test]
    fn test_del_call_optional_prunes_output_rather_than_no_op() {
        // #537: `del(f)?` wraps the *whole call* in try/catch-empty, like jq —
        // a step error must prune the output entirely, not fall back to a
        // silent no-op that still emits the unchanged input. Contrast with
        // `test_del_field_on_wrong_type_respects_optional` above, where the
        // `?` sits *inside* the path (`del(.a?)`) and a no-op is correct.
        query!(br"5", r"del(.a)?", QueryResult::None => {});
        query!(br"5", r"del(.[0])?", QueryResult::None => {});
        query!(br#"{"a":5}"#, r"del(.a.b)?", QueryResult::None => {});
        query!(br#"{"a":{"x":1}}"#, r"del(.a.b[])?", QueryResult::None => {});

        // Without the outer `?`, the same queries still raise as before.
        query!(br"5", r"del(.a)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot index number with string \"a\"");
            }
        );
    }

    #[test]
    fn test_chained_assign() {
        // Chained: .a = 1 | .b = 2
        query!(br#"{"a": 0, "b": 0}"#, r".a = 1 | .b = 2",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                let a = obj.get("a").unwrap();
                assert_eq!(*a, OwnedValue::Int(1));
                let b = obj.get("b").unwrap();
                assert_eq!(*b, OwnedValue::Int(2));
            }
        );
    }

