    #[test]
    fn test_label_catches_its_own_bare_break_with_path_context() {
        // The break fires on the very first element, so the enclosing
        // `.[]` loop's fan-out aborts with zero accumulated output --
        // `result` is a bare `Break`, not a `Partial`.
        assert_eq!(
            eval_all_outputs(
                b"[10,20]",
                &[7, 8],
                "label $out | .[] | if key == 0 then break $out else file_index end"
            ),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_label_catches_partial_break_with_path_context() {
        // The break fires on the second element, after the first already
        // produced output -- `result` is `Partial(prefix, Break(_))`, and
        // catching it must keep the prefix rather than discarding it.
        assert_eq!(
            eval_all_outputs(
                b"[10,20]",
                &[7, 8],
                "label $out | .[] | if key == 1 then break $out else file_index end"
            ),
            vec!["7"]
        );
    }

    /// Object-input mirror of the two tests above (#1477 review) --
    /// `Expr::Iterate`'s array and object loop bodies share
    /// `iterate_element_step` since #1477's unification, but the early-stop
    /// path had coverage only from the array side. `file_index` isn't used
    /// here (it's array-position-keyed, not meaningful for an object's own
    /// entries); `key` plays both roles instead.
    #[test]
    fn test_label_catches_its_own_bare_break_with_path_context_object() {
        assert_eq!(
            eval_all_outputs(
                br#"{"a":10,"b":20}"#,
                &[],
                r#"label $out | .[] | if key == "a" then break $out else key end"#
            ),
            Vec::<String>::new()
        );
    }

