    #[test]
    fn test_file_index_inside_user_defined_function() {
        // User-defined functions used to be out of scope for `--eval-all`
        // path-context resolution -- `needs_path_context` didn't see
        // through a `FuncDef`, so `.[] | f` never routed through
        // path-context evaluation and `file_index` inside `f`'s body fell
        // back to its default (0) instead of resolving per-element. Fixed
        // by #1306's `needs_path_context`/`eval_pipe_with_path_context_internal`
        // `FuncDef` arms (added for `key`, but shared by every path-context
        // builtin including this one): each element now correctly sees its
        // own origin file (3 and 4) via `expand_func_calls`'s `FileIndex`
        // arm, hit while inlining `f`'s body at call time -- not
        // per-element resolution itself, `test_file_index_continues_pipe_after_itself`
        // covers that.
        assert_eq!(
            eval_all_outputs(b"[10,20]", &[3, 4], "def f: file_index; .[] | f"),
            vec!["3", "4"]
        );
    }

    #[test]
    fn test_file_index_inside_parameterized_user_defined_function() {
        // Same fix as above (#1306), via `substitute_func_param`'s
        // `FileIndex` arm instead of `expand_func_calls`'s.
        assert_eq!(
            eval_all_outputs(b"[10]", &[9], "def f($x): (file_index, $x); .[] | f(1)"),
            vec!["9", "1"]
        );
    }

    // The remaining branches in this plumbing are provably unreachable
    // through any real filter, so they're exercised directly against the
    // private functions instead of via a filter: `accumulate_path_context_step`'s
    // `One` and `continue_rest_with_context`'s `One`/non-empty-`Many` exist
    // only because `eval_fanout` (shared with plain `select`) is generic
    // over borrowed-cursor results, but the `Select` arm's own fan-out body
    // (`Owned`/`None` only, never `One`/`Many`) can never construct a
    // non-empty borrowed variant.

    #[test]
    fn test_accumulate_path_context_step_handles_borrowed_one() {
        let bytes: &[u8] = b"42";
        let index = JsonIndex::build(bytes);
        let cursor = index.root(bytes);
        let sj = cursor.value();

        let mut results = Vec::new();
        let stop = accumulate_path_context_step::<Vec<u64>>(&mut results, QueryResult::One(sj));
        assert!(stop.is_none());
        assert_eq!(results, vec![OwnedValue::Int(42)]);
    }

    #[test]
    fn test_continue_rest_with_context_handles_borrowed_one() {
        let bytes: &[u8] = b"42";
        let index = JsonIndex::build(bytes);
        let cursor = index.root(bytes);
        let sj = cursor.value();
        let rest_expr = parse("tostring").unwrap();

        let result = continue_rest_with_context::<Vec<u64>, JqSemantics>(
            QueryResult::One(sj),
            core::slice::from_ref(&rest_expr),
            &OwnedValue::Null,
            None,
            &[],
            false,
        );
        match result {
            QueryResult::Owned(OwnedValue::String(s)) => assert_eq!(s, "42"),
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[test]
    fn test_continue_rest_with_context_handles_borrowed_many() {
        let bytes: &[u8] = br#"{"a": [1, false, 2]}"#;
        let index = JsonIndex::build(bytes);
        let cursor = index.root(bytes);
        let many = match eval::<Vec<u64>, JqSemantics>(&parse(".a[] // 9").unwrap(), cursor) {
            QueryResult::Many(vs) => vs,
            other => panic!("expected Many, got {other:?}"),
        };
        assert_eq!(many.len(), 2);

        let rest_expr = parse("tostring").unwrap();
        let result = continue_rest_with_context::<Vec<u64>, JqSemantics>(
            QueryResult::Many(many),
            core::slice::from_ref(&rest_expr),
            &OwnedValue::Null,
            None,
            &[],
            false,
        );
        match result {
            QueryResult::ManyOwned(vs) => {
                assert_eq!(
                    vs,
                    vec![
                        OwnedValue::String("1".to_string()),
                        OwnedValue::String("2".to_string())
                    ]
                );
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    /// #1445 (code review): a genuinely empty `rest` must return the
    /// intermediate value directly rather than recursing into
    /// `eval_pipe_with_path_context_internal` purely to hit its own
    /// `exprs.is_empty()` base case -- that recursion clones the value
    /// right back out on every call, a real cost with no test able to
    /// catch it before this one (every other test here always appends a
    /// further pipe stage). Doesn't assert on allocation count directly
    /// (not observable from a black-box `QueryResult` comparison), but
    /// pins the *value* each variant produces for `rest.is_empty()`,
    /// which the fast path added by this fix must still match exactly.
    #[test]
    fn test_continue_rest_with_context_empty_rest_short_circuits_1445() {
        let bytes: &[u8] = b"42";
        let index = JsonIndex::build(bytes);
        let cursor = index.root(bytes);
        let sj = cursor.value();

        // `Owned`
        let result = continue_rest_with_context::<Vec<u64>, JqSemantics>(
            QueryResult::Owned(OwnedValue::Int(42)),
            &[],
            &OwnedValue::Null,
            None,
            &[],
            false,
        );
        match result {
            QueryResult::Owned(OwnedValue::Int(42)) => {}
            other => panic!("unexpected: {other:?}"),
        }

        // `One` (borrowed cursor) -- still converts to `Owned` via
        // `to_owned_lossy`, matching what the pre-#1445 recursive path already
        // did, just without the extra clone. `to_owned_lossy` on a
        // cursor-borrowed number preserves the source literal (`"42"`),
        // not a plain `Int`, matching this crate's own established
        // literal-preservation convention -- confirmed via a match on
        // `NumberLiteral` rather than assuming `Int`.
        let result = continue_rest_with_context::<Vec<u64>, JqSemantics>(
            QueryResult::One(sj),
            &[],
            &OwnedValue::Null,
            None,
            &[],
            false,
        );
        match result {
            QueryResult::Owned(OwnedValue::NumberLiteral(NumberRepr::Int(42), ref lit)) => {
                assert_eq!(&**lit, "42");
            }
            other => panic!("unexpected: {other:?}"),
        }

        // `ManyOwned`
        let result = continue_rest_with_context::<Vec<u64>, JqSemantics>(
            QueryResult::ManyOwned(vec![OwnedValue::Int(1), OwnedValue::Int(2)]),
            &[],
            &OwnedValue::Null,
            None,
            &[],
            false,
        );
        match result {
            QueryResult::ManyOwned(vs) => {
                assert_eq!(vs, vec![OwnedValue::Int(1), OwnedValue::Int(2)]);
            }
            other => panic!("unexpected: {other:?}"),
        }

        // `Many` (borrowed cursor)
        let bytes: &[u8] = br#"{"a": [1, 2]}"#;
        let index = JsonIndex::build(bytes);
        let cursor = index.root(bytes);
        let many = match eval::<Vec<u64>, JqSemantics>(&parse(".a[]").unwrap(), cursor) {
            QueryResult::Many(vs) => vs,
            other => panic!("expected Many, got {other:?}"),
        };
        let result = continue_rest_with_context::<Vec<u64>, JqSemantics>(
            QueryResult::Many(many),
            &[],
            &OwnedValue::Null,
            None,
            &[],
            false,
        );
        match result {
            QueryResult::ManyOwned(vs) => {
                assert_eq!(vs, vec![OwnedValue::Int(1), OwnedValue::Int(2)]);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[test]
    fn test_continue_rest_with_context_many_owned_loop_stops_on_error() {
        // `(1, 2)` (a `Comma`, evaluated with no error at all) hands
        // `continue_rest_with_context` a genuine `ManyOwned([1, 2])`
        // intermediate; erroring on the *second* value while continuing
        // `rest` per-element exercises the loop's early-return "stop" path
        // rather than the case (`test_select_fanout_produces_many_owned_with_path_context`)
        // where every element's continuation succeeds.
        match eval_all_result(
            b"1",
            &[0],
            r#"(1, 2) | if . == 2 then error("boom") else file_index end"#,
        ) {
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(vs, vec![OwnedValue::Int(0)]);
                assert_eq!(e.message, "boom");
            }
            other => panic!("expected Partial, got {other:?}"),
        }
    }

    #[test]
    fn test_continue_rest_with_context_borrowed_many_loop_stops_on_error() {
        // Same "stop early, keep the prefix" contract as the `ManyOwned`
        // loop above, for the borrowed-cursor `Many` loop -- reachable
        // only via a direct call (see the borrowed-`One`/`Many` tests
        // above for why).
        let bytes: &[u8] = br#"{"a": [1, 2]}"#;
        let index = JsonIndex::build(bytes);
        let cursor = index.root(bytes);
        let many = match eval::<Vec<u64>, JqSemantics>(&parse(".a[]").unwrap(), cursor) {
            QueryResult::Many(vs) => vs,
            other => panic!("expected Many, got {other:?}"),
        };
        assert_eq!(many.len(), 2);

        let rest_expr = parse(r#"if . == 2 then error("boom") else tostring end"#).unwrap();
        let result = continue_rest_with_context::<Vec<u64>, JqSemantics>(
            QueryResult::Many(many),
            core::slice::from_ref(&rest_expr),
            &OwnedValue::Null,
            None,
            &[],
            false,
        );
        match result {
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(vs, vec![OwnedValue::String("1".to_string())]);
                assert_eq!(e.message, "boom");
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[test]
    fn test_generic_fallback_continues_pipe_with_path_context() {
        // `1 as $x | $x` (`Expr::As`) has no dedicated path-context arm, so
        // it falls into the generic `_` fallback -- which must still
        // continue the rest of the pipe (here, `file_index`) rather than
        // treating itself as the pipe's final value.
        assert_eq!(
            eval_all_outputs(b"[10,20]", &[7, 8], ".[] | (1 as $x | $x) | file_index"),
            vec!["7", "8"]
        );
    }

    #[test]
    fn test_key_continues_pipe_after_itself_yq_semantics() {
        // Same shape as `test_key_continues_pipe_after_itself`, but through
        // `YqSemantics` -- the generic path-context functions are
        // monomorphized per `EvalSemantics` impl, and the yq CLI (the only
        // real caller of the eval-all-adjacent parts of this file) always
        // uses `YqSemantics`, never `JqSemantics`.
        let index = JsonIndex::build(b"[10,20]");
        let cursor = index.root(b"[10,20]");
        let expr = parse(".[] | key | tostring").unwrap();
        let out: Vec<String> = eval::<Vec<u64>, YqSemantics>(&expr, cursor)
            .collect_owned()
            .iter()
            .map(OwnedValue::to_json)
            .collect();
        assert_eq!(out, vec![r#""0""#, r#""1""#]);
    }

    // Phase 12 tests: Additional builtins

    #[test]
    fn test_now() {
        // now returns current Unix timestamp as a float (std), or a fixed
        // 0.0 fallback in no_std context (builtin_now has no clock there) --
        // same variant either way, so one query! call covers both, same as
        // test_env/test_dollar_env above.
        query!(b"null", "now",
            QueryResult::Owned(OwnedValue::Float(n)) => {
                #[cfg(feature = "std")]
                {
                    // Should be a reasonable Unix timestamp (after year 2020)
                    assert!(n > 1577836800.0, "timestamp should be after 2020");
                    // Should be before year 2100
                    assert!(n < 4102444800.0, "timestamp should be before 2100");
                }
                #[cfg(not(feature = "std"))]
                assert_eq!(n, 0.0, "now should fall back to 0.0 in no_std context");
            }
        );
    }

    #[test]
    fn test_abs() {
        // abs is an alias for fabs
        query!(b"-5", "abs", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 5.0).abs() < f64::EPSILON);
        });
        query!(b"5", "abs", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 5.0).abs() < f64::EPSILON);
        });
        query!(b"-7.25", "abs", QueryResult::Owned(OwnedValue::Float(n)) => {
            assert!((n - 7.25).abs() < f64::EPSILON);
        });
    }

    #[test]
    fn test_builtins() {
        // builtins returns an array of builtin function names
        query!(b"null", "builtins | length",
            QueryResult::Owned(OwnedValue::Int(n)) => {
                // Should have many builtins (at least 100)
                assert!(n > 100, "should have many builtins, got {n}");
            }
        );
        // Check some known builtins exist
        query!(b"null", r#"builtins | map(select(startswith("now"))) | length"#,
            QueryResult::Owned(OwnedValue::Int(n)) => {
                assert!(n >= 1, "should have now builtin");
            }
        );
        // #2035: modulemeta is arity 0 (matching real jq's modulemeta/0),
        // not the arity-1 entry this list carried before the parser fix --
        // pinned here since builtin_builtins's hand-maintained list has no
        // other guard tying it to the parser's actual accepted grammar.
        query!(b"null", r#"builtins | any(. == "modulemeta/0")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b, "builtins should list modulemeta/0");
            }
        );
        query!(b"null", r#"builtins | any(. == "modulemeta/1")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b, "builtins should not list modulemeta/1");
            }
        );
    }

    #[test]
    fn test_normals() {
        // normals selects only normal numbers (not 0, inf, nan, subnormal)
        query!(b"5", "normals", QueryResult::One(_) => {});
        query!(b"-3.14", "normals", QueryResult::One(_) => {});
        query!(b"0", "normals", QueryResult::None => {}); // 0 is not normal
        query!(b"null", "normals", QueryResult::None => {}); // null is not a number
        query!(br#""string""#, "normals", QueryResult::None => {}); // string is not a number
    }

    #[test]
    fn test_finites() {
        // finites selects only finite numbers (not inf or nan)
        query!(b"5", "finites", QueryResult::One(_) => {});
        query!(b"-3.14", "finites", QueryResult::One(_) => {});
        query!(b"0", "finites", QueryResult::One(_) => {}); // 0 is finite
        query!(b"null", "finites", QueryResult::None => {}); // null is not a number
        query!(br#""string""#, "finites", QueryResult::None => {}); // string is not a number
    }

    #[test]
    fn test_format_urid() {
        // @urid decodes URI/percent encoding
        query!(br#""hello%20world""#, "@urid",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "hello world");
            }
        );
        query!(br#""foo%2Fbar""#, "@urid",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "foo/bar");
            }
        );
        // Test roundtrip with @uri
        query!(br#""hello world""#, "@uri | @urid",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "hello world");
            }
        );
    }

    /// #1138: a malformed `%` escape (not immediately followed by two
    /// valid hex digits) errors rather than silently passing the `%`
    /// through -- matching real yq's `invalid URL escape "..."` wording
    /// (yq is the only oracle here; real jq has no `@urid` at all). An
    /// earlier version of `test_format_urid` above pinned the old
    /// passthrough behavior for exactly this input
    /// (`"hello%GGworld"` -> `"hello%GGworld"`); this replaces it.
    #[test]
    fn test_format_urid_malformed_escape_errors_1138() {
        query!(br#""hello%GGworld""#, "@urid",
            QueryResult::Error(e) => {
                assert!(
                    e.to_string().contains(r#"invalid URL escape "%GG""#),
                    "error: {e}"
                );
            }
        );
    }

    #[test]
    fn test_loc_basic() {
        // $__loc__ returns {"file": "<stdin>", "line": N}
        query!(b"null", "$__loc__",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("file"), Some(&OwnedValue::String("<stdin>".into())));
                assert_eq!(obj.get("line"), Some(&OwnedValue::Int(1)));
            }
        );
    }

    #[test]
    fn test_loc_line_number() {
        // $__loc__ should report line 1 for single-line filter
        query!(b"null", "$__loc__.line",
            QueryResult::Owned(v) => {
                assert_eq!(v, OwnedValue::Int(1));
            }
        );
    }

    #[test]
    fn test_loc_file() {
        // $__loc__.file should be "<stdin>"
        query!(b"null", "$__loc__.file",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "<stdin>");
            }
        );
    }

    #[test]
    fn test_loc_multiline() {
        // Multi-line filter: $__loc__ on line 2 should report line 2
        let filter = ".\n| $__loc__.line";
        let json = b"null";
        let index = crate::json::JsonIndex::build(json);
        let cursor = index.root(json);
        let expr = crate::jq::parse(filter).unwrap();
        match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
            QueryResult::Owned(v) => {
                assert_eq!(
                    v,
                    OwnedValue::Int(2),
                    "expected line 2 for $__loc__ on second line"
                );
            }
            other => panic!("expected Owned, got {other:?}"),
        }
    }

    #[test]
    fn test_loc_multiline_line3() {
        // $__loc__ on line 3 should report line 3
        // Use valid jq syntax: pipe identity on separate lines
        let filter = ".\n|\n$__loc__.line";
        let json = b"null";
        let index = crate::json::JsonIndex::build(json);
        let cursor = index.root(json);
        let expr = crate::jq::parse(filter).unwrap();
        match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
            QueryResult::Owned(v) => {
                assert_eq!(
                    v,
                    OwnedValue::Int(3),
                    "expected line 3 for $__loc__ on third line"
                );
            }
            other => panic!("expected Owned, got {other:?}"),
        }
    }

    #[test]
    fn test_loc_in_function_def() {
        // $__loc__ inside a function should report the line where it appears
        let filter = "def f: $__loc__.line; f";
        let json = b"null";
        let index = crate::json::JsonIndex::build(json);
        let cursor = index.root(json);
        let expr = crate::jq::parse(filter).unwrap();
        match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
            QueryResult::Owned(v) => {
                assert_eq!(
                    v,
                    OwnedValue::Int(1),
                    "expected line 1 for $__loc__ in function on line 1"
                );
            }
            other => panic!("expected Owned, got {other:?}"),
        }
    }

